window.COURSE = {"meta": {"id": "rust-from-first-program", "title": "Rust: From First Program to Systems Programming", "subtitle": "One course built from five Rust books, from your first println! to threads, async and a web server", "description": "You will learn Rust step by step: read a short explanation, run the example in the page, change it, then prove it with a quiz or an exercise checked by real tests. Nothing is assumed: every term is explained the first time it appears.\n\nThe course merges *The Rust Programming Language* (2024 edition), *Programming Rust*, *Rust in Action* and *Comprehensive Rust* into one path, with each topic taught once.\n", "ui_lang": "en", "language": "en", "level": "beginner", "source": {"title": "The Rust Programming Language (2024 ed.); Programming Rust, 2nd ed.; Rust in Action; Comprehensive Rust", "author": "Klabnik, Nichols, Krycho; Blandy, Orendorff, Tindall; McNamara; Geisler et al.", "file": "merged"}, "roadmap": [{"id": "ch01", "title": "Getting Started with Rust"}, {"id": "ch02", "title": "Your First Program: a Guessing Game"}, {"id": "ch03", "title": "Common Programming Concepts"}, {"id": "ch04", "title": "Ownership, Borrowing and Slices"}, {"id": "ch05", "title": "Structs: Grouping Related Data"}, {"id": "ch06", "title": "Enums and Pattern Matching"}, {"id": "ch07", "title": "Packages, Crates and Modules"}, {"id": "ch08", "title": "Common Collections and Text"}, {"id": "ch09", "title": "Error Handling"}, {"id": "ch10", "title": "Generics, Traits and Lifetimes"}, {"id": "ch11", "title": "Writing Automated Tests"}, {"id": "ch12", "title": "Project: a Command-Line Search Tool"}, {"id": "ch13", "title": "Closures and Iterators"}, {"id": "ch14", "title": "Cargo and Crates.io"}, {"id": "ch15", "title": "Smart Pointers"}, {"id": "ch16", "title": "Fearless Concurrency"}, {"id": "ch17", "title": "Async Programming"}, {"id": "ch18", "title": "Trait Objects and OOP in Rust"}, {"id": "ch19", "title": "Patterns in Depth"}, {"id": "ch20", "title": "Advanced Features: Unsafe, Advanced Traits and Types, Macros"}, {"id": "ch21", "title": "Data in Depth: Bits, Integers and Floats"}, {"id": "ch22", "title": "Files, Storage and I/O"}, {"id": "ch23", "title": "Networking and Time"}, {"id": "ch24", "title": "Going Low-Level: FFI, Kernels and Signals"}, {"id": "ch25", "title": "Final Project: a Multithreaded Web Server"}], "built_at": "2026-10-23T03:29:54+00:00", "version": 1}, "ui": {"home": "Home", "glossary": "Glossary", "cont": "Continue", "startCourse": "Start the course", "lessonsDone": "Lessons completed", "exercisesDone": "Exercises passed", "quizScore": "Correct quiz answers", "minLeft": "About", "min": "min", "chapter": "Chapter", "lesson": "Lesson", "test": "Chapter test", "quiz": "Quick quiz", "exercise": "Exercise", "flashcards": "Flashcards", "summary": "Key takeaways", "frombook": "From the book", "terms": "New terms", "check": "Check", "checkTest": "Check test", "retry": "Try again", "hint": "Hint", "showAnswer": "Show answer", "correct": "Correct!", "wrong": "Not yet.", "score": "Score", "passed": "Passed", "failed": "Not passed", "needScore": "Required: {0}%", "best": "best", "unanswered": "Unanswered questions: {0}. Check anyway?", "tTrue": "True", "tFalse": "False", "next": "Next", "prev": "Back", "again": "Restart", "step": "Step {0} of {1}", "reveal": "Show answer", "thinkFirst": "Think about it before you click.", "goal": "Goal", "behavior": "What the program should do", "examples": "Input and output examples", "input": "Input", "output": "Expected output", "startFiles": "Starter files", "testFiles": "Tests (you can read them)", "whereToWork": "Where to work", "runCmd": "Terminal command", "runTests": "Run tests", "running": "Running…", "noServer": "To run tests with one click, open the course via start.sh / start.bat. You can also run the command yourself in a terminal.", "markDone": "Mark as passed", "markUndone": "Undo", "showSolution": "Show solution", "hideSolution": "Hide solution", "confirmSolution": "Try once more on your own first! Really show the solution?", "dlgYes": "Yes", "dlgNo": "Cancel", "stTodo": "To do", "stPassed": "Passed", "stFailed": "Tests not passing yet", "easy": "easy", "medium": "medium", "hard": "hard", "checklist": "Check yourself", "know": "I know it", "notYet": "Not yet", "flipHint": "Click the card to flip it", "cardsLeft": "Left to learn: {0}", "allKnown": "All cards mastered! 🎉", "finishLesson": "Finish lesson", "lessonDone": "Lesson completed 🎉", "nextLesson": "Next lesson", "yourPractice": "Your practice", "quizzes": "Quizzes", "exercises": "Exercises", "later": "You can come back to the exercises later — you can still finish the lesson.", "reset": "Reset progress", "resetConfirm": "Really reset all progress?", "savedFile": "💾 saved to file", "savedBrowser": "💾 saved in browser", "search": "Search terms…", "none": "No results", "courseDone": "Whole course completed! 🎓", "passTest": "Pass the test to complete this chapter.", "solution": "Reference solution", "yourAnswer": "Your answer", "correctIs": "Correct answer", "moveUp": "Up", "moveDown": "Down", "copy": "Copy", "copied": "Copied", "progressFile": "Progress is saved in the progress/ folder.", "exitCode": "exit code", "testsOk": "All tests passed ✓", "testsFail": "Tests are failing — read the messages below and fix your code.", "serverErr": "Could not reach the helper (serve.py).", "timedOut": "Time limit exceeded — check for an infinite loop.", "questionsN": "questions", "attempts": "attempts", "readTime": "reading + practice", "chOf": "Chapter {0}", "openSidebar": "Menu", "callout_tip": "Tip", "callout_note": "Note", "callout_warning": "Careful", "callout_analogy": "Analogy", "callout_key": "Remember", "callout_example": "Example", "derivation": "Derivation", "why": "Why", "result": "Result", "showAll": "Show all", "stepByStep": "Step by step", "mathmlUnsupported": "Your browser can't display math formulas properly — update it to see equations typeset correctly."}, "chapters": [{"id": "ch01", "title": "Getting Started with Rust", "summary": "Why Rust exists, how to install it, your first program, and the Cargo tool you will use for everything else.", "goals": ["Explain in plain words what problem Rust solves and what it costs you", "Install Rust and check that the compiler works", "Write, compile and run a Hello, world! program", "Create, build, check and run a project with Cargo"], "lessons": ["ch01-01-why-rust", "ch01-02-install-hello", "ch01-03-cargo", "ch01-99-test"]}, {"id": "ch02", "title": "Your First Program: a Guessing Game", "summary": "Build a complete little game. You read input from the keyboard, compare numbers, repeat until the player wins, and cope with bad input.", "goals": ["Read a line of text typed by the user and turn it into a number", "Use a crate (a library) from crates.io in a Cargo project", "Compare values with `match` and `Ordering`", "Repeat work with `loop`, and leave it with `break`", "Handle invalid input without crashing, using `match` on a `Result`"], "lessons": ["ch02-01-setup-input", "ch02-02-random-compare", "ch02-03-loop-quit", "ch02-99-test"]}, {"id": "ch03", "title": "Common Programming Concepts", "summary": "The building blocks every program uses: variables and constants, number and text types, tuples and arrays, functions, and decisions and loops.", "goals": ["Choose between immutable variables, mutable variables, shadowing and constants", "Pick the right number type and know what happens when a number overflows", "Group values with tuples and arrays", "Write functions with parameters and return values, and tell statements from expressions", "Control the flow of a program with if, loop, while and for"], "lessons": ["ch03-01-variables", "ch03-02-scalar-types", "ch03-03-compound-types", "ch03-04-functions", "ch03-05-control-flow", "ch03-99-test"]}, {"id": "ch04", "title": "Ownership, Borrowing and Slices", "summary": "The idea that makes Rust different: every value has one owner, and other code can borrow it under rules the compiler checks. No garbage collector, no manual free, no dangling pointers.", "goals": ["Explain where values live (stack or heap) and why that matters", "Predict when a value is moved, copied or dropped", "Lend values with shared (&) and mutable (&mut) references, and follow the borrowing rules", "Read and fix the borrow checker's most common errors", "Use string slices and array slices to refer to part of a collection"], "lessons": ["ch04-01-ownership", "ch04-02-references", "ch04-03-slices", "ch04-99-test"]}, {"id": "ch05", "title": "Structs", "summary": "Give your data a shape: define structs with named fields, build and update them, print them for debugging, and attach behavior with methods and associated functions.", "goals": ["Define structs, create instances, and use field init shorthand and struct update syntax", "Know when to use tuple structs and unit-like structs", "Refactor loose variables into a struct, and print it with Debug and dbg!", "Write methods taking self, &self or &mut self, and associated functions like new"], "lessons": ["ch05-01-define", "ch05-02-rectangles", "ch05-03-methods", "ch05-99-test"]}], "lessons": {"ch01-01-why-rust": {"title": "Why Rust? Speed without the crashes", "summary": "You will be able to say what kind of bugs Rust prevents, what it gives you in return, and what it costs.", "source": {"chapter": "ch01", "sections": ["TRPL Introduction", "PR ch1 Systems Programmers Can Have Nice Things", "RiA 1.7–1.10 What is Rust, Downsides, Where Rust fits"]}, "blocks": [{"type": "text", "md": "By the end of this lesson you will be able to explain, in one or two sentences, **why people choose Rust** and what trade-off they accept when they do. That matters because every rule you meet later in this course (and there are some strict ones) exists to protect one promise. Knowing the promise makes the rules feel less arbitrary.\n"}, {"type": "callout", "kind": "analogy", "title": "A car with a very picky inspector", "md": "Imagine two car factories. The first one lets you drive away straight after assembly; problems show up on the motorway. The second one has an inspector who refuses to let any car leave until every bolt is checked. Leaving the second factory takes longer, but the car will not lose a wheel at 120 km/h.\n\nRust is the second factory. The inspector is the **compiler**, the program that turns your code into something the computer can run. Where the analogy breaks: the Rust inspector also explains *exactly* which bolt is loose and usually how to fix it.\n"}, {"type": "text", "title": "The problem Rust was built to solve", "md": "Programs keep their data in the computer's **memory**, a long row of numbered boxes. Languages such as C and C++ let you reach into any box directly. That is fast, but nothing stops you from reaching into a box you do not own, or one that was already thrown away.\n\nWhen that happens the C standard calls it **undefined behavior**: the program is allowed to do *anything*. It might print garbage, crash, or quietly let an attacker take over. The *Programming Rust* authors open their book with a four-line C program that writes past the end of a one-element array; on one laptop it ended up printing a message from an unrelated password routine and then crashed.\n"}, {"type": "code", "lang": "c", "title": "Four lines of C that misbehave", "caption": "From *Programming Rust*, ch. 1. The array `a` has one slot, but the code writes to slot number 3.", "code": "int main(int argc, char **argv) {\n  unsigned long a[1];\n  a[3] = 0x7ffff7b36cebUL;\n  return 0;\n}\n", "explain": "A C compiler accepts this happily. Nothing checks that slot 3 exists, so the value lands on top of whatever happens to live next to the array in memory.\n"}, {"type": "text", "title": "Rust's promise", "md": "Rust makes a simple promise: **if your program passes the compiler's checks, it is free of undefined behavior.** Reading memory that was already freed, freeing the same memory twice, and using a \"nothing\" pointer are all caught *before the program ever runs*. Array accesses are checked too: reading past the end stops the program with a clear error instead of silently reading a stranger's data.\n\nStudies by Microsoft and by the Chromium browser team found that around 70% of serious security bugs come from exactly this kind of invalid memory access. Rust removes that whole class of bugs, and it does so without a **garbage collector** (a helper that runs alongside your program to clean up memory, costing time).\n"}, {"type": "playground", "id": "ch01-play-bounds", "expect_panic": true, "title": "See it yourself: Rust checks array access", "lang": "rust", "md": "This is the Rust version of the C mistake: a vector (a growable list) with three items, and an attempt to read item number 10. Press **Run** and read what Rust says. Then change `10` to `2` and run it again.\n", "code": "fn main() {\n    let fruit = vec![\"apple\", \"banana\", \"cherry\"];\n    let index = 10;\n    println!(\"Reading item {index}...\");\n    println!(\"Got: {}\", fruit[index]);\n}\n", "hints": ["Items are counted from 0, so the three items have positions 0, 1 and 2."]}, {"type": "reveal", "prompt": "When you ran the program with `index = 10`, did Rust read some random memory, or did it stop? Why is stopping better?", "md": "It stopped with a **panic**: `index out of bounds: the len is 3 but the index is 10`. Stopping is better because the program never works with data it does not own. A crash with a clear message is annoying; silently using a stranger's data is dangerous and can go unnoticed for years.\n"}, {"type": "table", "title": "Rust's three goals (from *Rust in Action*)", "headers": ["Goal", "What it means for you", "Example you will meet"], "rows": [["**Safety**", "Whole families of bugs cannot compile: dangling references, data races, reading past the end of a buffer.", "Using a value after it was given away is a compile error (chapter 4)."], ["**Productivity**", "Helpful error messages, a built-in build tool and package manager, tests and docs out of the box.", "`cargo new`, `cargo run`, `cargo test` (this chapter)."], ["**Control**", "You decide where data lives and how it is laid out, like in C, with sensible defaults.", "Choosing between a value on the stack and one in a `Box` on the heap (chapter 15)."]]}, {"type": "text", "title": "Fast, too", "md": "Rust follows the **zero-cost abstraction** idea it shares with C++: features you do not use cost nothing, and the ones you do use are as fast as code you could have written by hand. Because there is no garbage collector, Rust starts quickly and uses little memory. That is why it shows up in command-line tools, databases, game engines, web servers, browsers, operating systems and even inside other languages as fast extensions.\n\nRust is also built for **concurrency**, doing several things at the same time. The same rules that keep memory safe also stop two threads from changing the same data at once. The community calls this *fearless concurrency*.\n"}, {"type": "callout", "kind": "warning", "title": "The honest costs", "md": "*Rust in Action* lists the downsides plainly, and you should know them before you start:\n\n- **Strictness.** Programs do not compile until everything is right. Early on you will \"fight the compiler\". Everyone does; it gets much easier.\n- **Compile times.** Rust compiles more slowly than many languages, because it checks and optimizes a lot.\n- **Size.** The language is big. This course introduces it one small piece at a time.\n- **Cyclic data.** Structures where things point at each other in a loop (like a doubly linked list) are awkward in safe Rust. Avoid them while learning.\n"}, {"type": "quiz", "id": "ch01-quiz-why", "title": "Check your understanding", "questions": [{"type": "single", "q": "What does the Rust compiler promise about a program that compiles?", "options": ["It has no bugs at all.", "It is free of undefined behavior such as reading freed memory.", "It runs faster than any C program.", "It never stops with an error at run time."], "answer": 1, "hints": ["Think about which *kind* of bug Rust is designed around.", "Logic mistakes (like adding instead of subtracting) are still possible."], "explanation": "Rust rules out **undefined behavior**: invalid memory access, data races and similar. It cannot know whether your logic is right, so \"no bugs at all\" is too strong. And a program can still stop at run time on purpose, for example with the out-of-bounds panic you just saw.\n"}, {"type": "truefalse", "q": "Rust keeps memory safe by running a garbage collector next to your program.", "answer": false, "hints": ["Look again at the paragraph about speed and memory use."], "explanation": "False. Rust has **no garbage collector**. The safety checks happen at compile time, through the ownership rules you will learn in chapter 4. That is why Rust programs start fast and use little memory.\n"}, {"type": "multi", "q": "Which of these are real downsides of Rust that the books mention? (Choose all that apply.)", "options": ["Compile times are longer than in many languages.", "The compiler is strict, so it takes time to get code accepted.", "Rust programs cannot use more than one CPU core.", "Data structures with cycles, like doubly linked lists, are awkward."], "answer": [0, 1, 3], "hints": ["One option contradicts the 'fearless concurrency' paragraph."], "explanation": "Compile times, strictness and cyclic data are the honest costs. Using many CPU cores is a **strength** of Rust: its rules make concurrent code safe, not impossible.\n"}]}, {"type": "summary", "points": ["Languages like C let you touch any memory, so mistakes become undefined behavior that can crash or be exploited.", "Rust's promise: if it compiles, it is free of undefined behavior, and it achieves this without a garbage collector.", "Rust's three goals are safety, productivity and control, and its abstractions are designed to cost nothing extra at run time.", "The price is a strict compiler, slower compiles and a large language, which this course takes in small steps."]}], "terms": [{"term": "compiler", "def": "A program that checks your source code and translates it into a program the computer can run. For Rust it is called `rustc`."}, {"term": "undefined behavior", "def": "What happens when a C or C++ program breaks a language rule, such as writing past the end of an array: the program is allowed to do anything at all."}, {"term": "garbage collector", "def": "A helper that runs alongside a program and frees memory that is no longer used. Rust does not have one."}, {"term": "panic", "def": "Rust stopping a program on purpose with an error message, for example when you read past the end of a vector."}, {"term": "zero-cost abstraction", "def": "A language feature that adds no run-time cost compared with writing the same thing by hand."}], "id": "ch01-01-why-rust", "chapter": "ch01", "kind": "lesson", "minutes": 10}, "ch01-02-install-hello": {"title": "Install Rust and say Hello, world!", "summary": "You will install the Rust tools, write the classic first program, and understand every line of it.", "source": {"chapter": "ch01", "sections": ["TRPL 1.1 Installation", "TRPL 1.2 Hello, World!", "RiA 1.4 A taste of the language"]}, "blocks": [{"type": "text", "md": "In this lesson you will **install Rust, write a five-line program and run it**. You can do every step of this course in the page's playground, but having Rust on your own computer lets you build real projects and run the exercise tests locally.\n"}, {"type": "callout", "kind": "analogy", "title": "Recipe and dish", "md": "Your `.rs` file is a recipe. The compiler `rustc` is the cook who turns it into a dish: a program file you can run any number of times. Unlike a script in Python or JavaScript, the recipe is not needed to *eat* the dish. You can hand the finished program to a friend who has never installed Rust.\n"}, {"type": "text", "title": "Step 1. Install with rustup", "md": "Rust is installed with **rustup**, a small tool that downloads the compiler and keeps it up to date.\n\n- **Linux or macOS:** open a terminal and run the command below. It downloads the installer script and starts it.\n- **Windows:** go to [rust-lang.org/tools/install](https://www.rust-lang.org/tools/install) and follow the steps. It will ask you to install Visual Studio's build tools, which provide the **linker** (the program that joins compiled pieces into one runnable file).\n\nOn Linux you may also need a C compiler such as GCC (on Ubuntu: the `build-essential` package); on macOS run `xcode-select --install`.\n"}, {"type": "code", "lang": "bash", "file": "terminal", "code": "curl --proto '=https' --tlsv1.2 https://sh.rustup.rs -sSf | sh\n", "output": "Rust is installed now. Great!", "output_label": "The last line you should see"}, {"type": "text", "title": "Step 2. Check that it worked", "md": "Open a **new** terminal (so it picks up the updated settings) and ask the compiler for its version. If you see a version number, Rust is ready. If the terminal says the command is not found, the Rust folder is not on your `PATH`, the list of places the terminal searches for programs; reopening the terminal or restarting usually fixes it.\n\nTwo more commands you will use later: `rustup update` installs the newest version, and `rustup doc` opens the full documentation in your browser, even offline.\n"}, {"type": "code", "lang": "bash", "file": "terminal", "code": "rustc --version\ncargo --version\n", "output": "rustc 1.97.0 (2d8144b78 2026-07-07)\ncargo 1.97.0 (...)\n", "output_label": "Example output (your numbers may be newer)"}, {"type": "text", "title": "Step 3. Write the program", "md": "Make a folder for your projects (for example `~/projects/hello_world`), and in it create a file named `main.rs`. Rust files always end in `.rs`; when a name has several words, separate them with an underscore: `hello_world.rs`, not `helloworld.rs`. Type this in:\n"}, {"type": "code", "lang": "rust", "file": "main.rs", "code": "fn main() {\n    println!(\"Hello, world!\");\n}\n", "output": "Hello, world!"}, {"type": "stepper", "title": "Reading the program line by line", "lang": "rust", "steps": [{"title": "fn main()", "md": "`fn` starts a **function**, a named block of instructions. This one is called `main`, and `main` is special: it is always the first code that runs in a Rust program. The empty parentheses `()` mean it takes no input.\n", "code": "fn main() {\n    println!(\"Hello, world!\");\n}\n", "highlight": [1]}, {"title": "The curly brackets", "md": "Everything between `{` and `}` is the function's **body**. Rust requires the brackets around every function body. Style tip: put the opening `{` on the same line as `fn main()`, with one space before it.\n", "code": "fn main() {\n    println!(\"Hello, world!\");\n}\n", "highlight": [1, 3]}, {"title": "println! is a macro", "md": "`println!` prints text and moves to a new line. The `!` tells you it is a **macro**, not a normal function. A macro is code that writes more code for you; you will build your own in chapter 20. For now: `!` means macro, and macros can do things functions cannot, like accept a varying number of arguments.\n", "code": "fn main() {\n    println!(\"Hello, world!\");\n}\n", "highlight": [2]}, {"title": "The text and the semicolon", "md": "`\"Hello, world!\"` is a **string**, a piece of text in double quotes, passed to `println!`. The line ends with `;`, which says \"this instruction is finished\". Most Rust lines end with a semicolon.\n", "code": "fn main() {\n    println!(\"Hello, world!\");\n}\n", "highlight": [2], "output": "Hello, world!"}]}, {"type": "flow", "title": "From source file to running program", "nodes": [{"label": "main.rs", "detail": "You write **source code**, text a person can read, in a file ending in `.rs`."}, {"label": "rustc main.rs", "detail": "The compiler checks the code. If anything is wrong it prints errors and stops; nothing is produced."}, {"label": "main (or main.exe)", "detail": "If the code is fine, `rustc` writes an **executable**: a file the operating system can run directly. On Windows it is `main.exe`."}, {"label": "./main", "detail": "You run the executable. It no longer needs the source file or Rust itself. That is what **ahead-of-time compiled** means."}]}, {"type": "code", "lang": "bash", "file": "terminal", "title": "Compile, then run (two separate steps)", "code": "rustc main.rs\n./main          # on Windows: .\\main\n", "output": "Hello, world!"}, {"type": "callout", "kind": "tip", "title": "Let a tool do the formatting", "md": "Rust ships with **rustfmt**, which formats code in the standard style. Run `rustfmt main.rs` (or, inside a Cargo project, `cargo fmt`) and stop worrying about spaces and brackets.\n"}, {"type": "playground", "id": "ch01-play-hello", "title": "Your turn: change the message", "lang": "rust", "task": "Make the program print exactly `Hello, Rustacean!` (Rust programmers call themselves Rustaceans).", "code": "fn main() {\n    println!(\"Hello, world!\");\n}\n", "expected_output": "Hello, Rustacean!", "hints": ["Only the text between the double quotes needs to change.", "Keep the exclamation mark at the end of the text, and keep the `;` at the end of the line."]}, {"type": "text", "title": "Text in any language", "md": "Rust strings are **UTF-8**, a way of storing text that covers every writing system. *Rust in Action* shows this by greeting the world in three languages. The program below introduces two things you will learn properly soon: `let` gives a name to a value, and `for` repeats code for each item in a list.\n"}, {"type": "playground", "id": "ch01-play-three-greetings", "title": "Greetings in three languages", "lang": "rust", "md": "Run it, then add a fourth greeting in a language you know. Add a new `let` line, then put the new name inside the square brackets.", "code": "fn greet_world() {\n    println!(\"Hello, world!\");\n\n    let southern_germany = \"Grüß Gott!\";\n    let japan = \"ハロー・ワールド\";\n\n    let regions = [southern_germany, japan];\n\n    for region in regions.iter() {\n        println!(\"{}\", region);\n    }\n}\n\nfn main() {\n    greet_world();\n}\n", "hints": ["For example: `let poland = \"Witaj, świecie!\";` and then `[southern_germany, japan, poland]`."]}, {"type": "quiz", "id": "ch01-quiz-hello", "title": "Quick check", "questions": [{"type": "single", "q": "Why does `println!` have an exclamation mark?", "options": ["It makes the output louder (bold) in the terminal.", "It marks a macro, code that generates more code.", "It means the function can fail.", "It is required at the end of every Rust name."], "answer": 1, "hints": ["Look at the third step of the walkthrough."], "explanation": "The `!` marks a **macro**. Macros are not ordinary functions; for example `println!` accepts any number of values to print. Plain functions, like `main`, are called without `!`.\n"}, {"type": "fill", "q": "Which function runs first in every executable Rust program? Type its name.", "answer": ["main", "main()", "fn main", "fn main()"], "hints": ["It is the function in the very first line of the program."], "explanation": "`main` is the entry point: the operating system starts your program there."}, {"type": "order", "q": "Put the steps of building and running a program with `rustc` in order.", "items": ["Write the source code in `main.rs`", "Run `rustc main.rs`", "The compiler produces an executable file", "Run `./main` (or `.\\main` on Windows)"], "hints": ["You cannot run a file that has not been produced yet."], "explanation": "Source code first, then the compiler, which produces the executable, which you then run. Because compiling and running are separate steps, you can give the executable to someone who has never installed Rust.\n"}, {"type": "truefalse", "q": "A friend needs Rust installed to run the `main` executable you compiled.", "answer": false, "hints": ["Think about the recipe and the dish."], "explanation": "False. Rust is compiled **ahead of time**: the executable runs on its own. Python, Ruby or JavaScript files, by contrast, need their language installed to run.\n"}]}, {"type": "summary", "points": ["rustup installs Rust and keeps it updated; `rustc --version` checks that it works.", "Every program starts in `fn main()`, and its body lives between curly brackets.", "`println!` is a macro (note the `!`) that prints a line of text.", "Compiling (`rustc main.rs`) and running (`./main`) are separate steps, and the result runs without Rust installed."]}], "terms": [{"term": "rustup", "def": "The installer and version manager for Rust: `rustup update` upgrades, `rustup doc` opens offline docs."}, {"term": "function", "def": "A named block of instructions, started with `fn`. It can take inputs (parameters) and give back a value."}, {"term": "macro", "def": "Code that writes more code. Called with a `!`, like `println!`. Macros can do things ordinary functions cannot, such as take any number of arguments."}, {"term": "string", "def": "A piece of text. A string literal is text written in double quotes in your code, like `\"Hello\"`."}, {"term": "executable", "def": "A file produced by the compiler that the operating system can run directly."}, {"term": "linker", "def": "A tool that joins compiled pieces into one executable. Installed with a C compiler or Visual Studio's build tools."}, {"term": "UTF-8", "def": "The text encoding Rust strings use. It can store characters from every writing system."}], "id": "ch01-02-install-hello", "chapter": "ch01", "kind": "lesson", "minutes": 20}, "ch01-03-cargo": {"title": "Hello, Cargo! Rust's build tool", "summary": "You will create, check, build and run a project with Cargo, and know what every file it creates is for.", "source": {"chapter": "ch01", "sections": ["TRPL 1.3 Hello, Cargo!", "CR Using Cargo", "PR ch1 Rust makes collaboration easier"]}, "blocks": [{"type": "text", "md": "After this lesson you will manage a Rust project the way almost every Rust programmer does: with **Cargo**. Calling `rustc` by hand is fine for one file, but real programs have many files and use code written by other people. Cargo handles all of that with a handful of commands that are the same on Windows, macOS and Linux.\n"}, {"type": "callout", "kind": "analogy", "title": "A kitchen manager", "md": "If `rustc` is the cook, Cargo is the kitchen manager. It knows where the recipes are kept, orders ingredients from suppliers (other people's code, called **dependencies**), tells the cook what to make, and keeps the finished dishes on the right shelf. You talk to the manager; the manager talks to the cook.\n"}, {"type": "text", "title": "Creating a project", "md": "`cargo new hello_cargo` creates a folder named `hello_cargo` with a ready-made project inside. It also starts a **Git** repository (Git tracks changes to your files) unless you are already inside one.\n\nInside you will find two things: a `Cargo.toml` file and a `src` folder holding `main.rs`. Cargo has even written Hello, world! into `main.rs` for you.\n"}, {"type": "code", "lang": "bash", "file": "terminal", "code": "cargo new hello_cargo\ncd hello_cargo\n", "output": "Creating binary (application) `hello_cargo` package\n"}, {"type": "svg", "caption": "What `cargo new` creates. Source code lives in `src/`; the top folder is for configuration, the README and the license.", "svg": "<svg viewBox='0 0 520 210' xmlns='http://www.w3.org/2000/svg' font-family='ui-monospace, monospace' font-size='14'>\n  <g fill='none' stroke='currentColor' stroke-width='1'>\n    <rect x='20' y='20' width='170' height='34'/>\n    <path d='M40 54 V170 M40 92 H70 M40 132 H70 M100 150 V184 M100 170 H130'/>\n    <rect x='70' y='76' width='150' height='32'/>\n    <rect x='70' y='116' width='110' height='32'/>\n    <rect x='130' y='156' width='110' height='30'/>\n  <\/g>\n  <g fill='currentColor'>\n    <text x='32' y='42'>hello_cargo/<\/text>\n    <text x='82' y='97'>Cargo.toml<\/text>\n    <text x='82' y='137'>src/<\/text>\n    <text x='142' y='176'>main.rs<\/text>\n    <text x='250' y='97' font-family='sans-serif' font-size='13'>settings: name, version, edition,<\/text>\n    <text x='250' y='113' font-family='sans-serif' font-size='13'>dependencies<\/text>\n    <text x='250' y='176' font-family='sans-serif' font-size='13'>your code starts here (fn main)<\/text>\n  <\/g>\n<\/svg>\n"}, {"type": "code", "lang": "toml", "file": "Cargo.toml", "code": "[package]\nname = \"hello_cargo\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n", "explain": "This file uses **TOML**, a simple settings format. `[package]` starts a section about your project: its `name`, its `version`, and the Rust **edition** it is written for. An edition is a snapshot of language conventions (2015, 2018, 2021, 2024); old code keeps compiling while new projects get the newest idioms. `[dependencies]` is where you will list other people's packages. In Rust a package of code is called a **crate**.\n"}, {"type": "text", "title": "Build, run and check", "md": "`cargo build` compiles the project and puts the executable in `target/debug/`. The first build also creates `Cargo.lock`, which records the exact versions of every dependency so the build can be repeated exactly. You never edit `Cargo.lock` by hand.\n\n`cargo run` builds (only if something changed) and runs in one step, so it is what you will type most. `cargo check` only checks that the code compiles, without producing an executable. It is much faster than a build, so many Rustaceans run it constantly while writing code.\n"}, {"type": "stepper", "title": "What each command prints", "lang": "bash", "steps": [{"title": "cargo build", "md": "Compiles the project. The word **dev** means a development build: compiled quickly, not optimized.", "code": "$ cargo build\n   Compiling hello_cargo v0.1.0 (/projects/hello_cargo)\n    Finished `dev` profile [unoptimized + debuginfo] target(s) in 2.85s\n", "highlight": [2, 3]}, {"title": "cargo run, nothing changed", "md": "No `Compiling` line: Cargo noticed the source did not change and just ran the existing executable.", "code": "$ cargo run\n    Finished `dev` profile [unoptimized + debuginfo] target(s) in 0.02s\n     Running `target/debug/hello_cargo`\nHello, world!\n", "highlight": [2, 3, 4]}, {"title": "cargo run, after an edit", "md": "You changed `main.rs`, so Cargo rebuilds first, then runs.", "code": "$ cargo run\n   Compiling hello_cargo v0.1.0 (/projects/hello_cargo)\n    Finished `dev` profile [unoptimized + debuginfo] target(s) in 0.33s\n     Running `target/debug/hello_cargo`\nHello, world!\n", "highlight": [2]}, {"title": "cargo check", "md": "Only checks for errors. No executable is written, which is why it is fast.", "code": "$ cargo check\n    Checking hello_cargo v0.1.0 (/projects/hello_cargo)\n    Finished `dev` profile [unoptimized + debuginfo] target(s) in 0.32s\n", "highlight": [2]}]}, {"type": "text", "title": "Building for release", "md": "When your program is ready for real users, run `cargo build --release`. It turns on **optimizations**, so the program runs faster, but the build takes longer. The result goes to `target/release/` instead of `target/debug/`. That is why there are two **profiles**: one for quick rebuilds while you work, one for the fastest possible final program. If you ever measure how fast your code is, always measure the release build.\n"}, {"type": "table", "title": "Cargo cheat sheet", "headers": ["Command", "What it does", "Output goes to"], "rows": [["`cargo new NAME`", "Create a new project folder", "`NAME/`"], ["`cargo build`", "Compile (development profile)", "`target/debug/`"], ["`cargo run`", "Compile if needed, then run", "`target/debug/`"], ["`cargo check`", "Check that it compiles, produce nothing", "(nothing)"], ["`cargo build --release`", "Compile with optimizations", "`target/release/`"], ["`cargo test`", "Build and run the project's tests (chapter 11)", "`target/debug/`"], ["`cargo fmt`", "Format all code in the standard style", "(edits files)"]]}, {"type": "callout", "kind": "key", "md": "Day to day you need three commands: `cargo new` to start, `cargo check` while you write, `cargo run` to try it."}, {"type": "callout", "kind": "tip", "title": "Working on someone else's project", "md": "Because Cargo's layout is the same everywhere, getting any Rust project running looks like this: `git clone <address>`, `cd` into the folder, `cargo build`. If you started a project without Cargo, move the code into `src/` and run `cargo init` to create the `Cargo.toml`.\n"}, {"type": "flashcards", "id": "ch01-cards-cargo", "title": "Cargo vocabulary", "cards": [{"front": "`Cargo.toml`", "back": "The project's settings file: name, version, edition, dependencies."}, {"front": "`Cargo.lock`", "back": "Records the exact versions of all dependencies. Managed by Cargo, never edited by hand."}, {"front": "crate", "back": "A package of Rust code: your project, or a library you depend on."}, {"front": "`cargo check`", "back": "Checks that the code compiles without producing an executable. Fast."}, {"front": "`target/debug/` vs `target/release/`", "back": "Where development builds and optimized `--release` builds are written."}, {"front": "edition", "back": "A snapshot of Rust's language conventions (2015, 2018, 2021, 2024) chosen in `Cargo.toml`."}]}, {"type": "exercise", "id": "ch01-ex-first-cargo-project", "title": "Your first Cargo project", "difficulty": "easy", "minutes": 10, "goal": "Create a Cargo project on your own computer, change what it prints, and build it in both profiles.", "behavior": "1. Run `cargo new hello_cargo` and `cd hello_cargo`.\n2. Open `src/main.rs` and change the message to `Hello, Cargo!`.\n3. Run `cargo check`, then `cargo run`.\n4. Run `cargo build --release` and run the optimized program directly from `target/release/`.\n", "examples": [{"input": "cargo run", "output": "Hello, Cargo!"}, {"input": "./target/release/hello_cargo", "output": "Hello, Cargo!", "note": "On Windows: `.\\target\\release\\hello_cargo.exe`"}], "checklist": ["`cargo new hello_cargo` created `Cargo.toml` and `src/main.rs`.", "`cargo check` finished without errors.", "`cargo run` printed `Hello, Cargo!`.", "The second `cargo run` (with no changes) did not print a `Compiling` line.", "`cargo build --release` created an executable in `target/release/` that prints the same text."], "hints": ["If `cargo` is not found, open a new terminal after installing Rust.", "Change only the text inside `println!(\"...\")`."], "solution_lang": "rust", "solution": "// src/main.rs\nfn main() {\n    println!(\"Hello, Cargo!\");\n}\n", "solution_explain": "Cargo only rebuilds when a source file changes, which is why the second `cargo run` skips the `Compiling` line. The release build lives in a different folder, so both executables exist side by side.\n", "mode": "selfcheck"}, {"type": "quiz", "id": "ch01-quiz-cargo", "title": "Quick check", "questions": [{"type": "single", "q": "You are halfway through writing a function and want to know whether it compiles, as quickly as possible. Which command?", "options": ["`cargo build --release`", "`cargo run`", "`cargo check`", "`cargo new`"], "answer": 2, "hints": ["You do not need an executable yet."], "explanation": "`cargo check` only checks the code, skipping the slow step of producing an executable. `cargo build --release` is the slowest option of all because it also optimizes.\n"}, {"type": "fill", "q": "In which folder does `cargo build --release` put the executable? (format: `folder/subfolder`)", "answer": ["target/release", "target/release/", "./target/release"], "hints": ["Development builds go to `target/debug`."], "explanation": "Release builds go to `target/release/`, development builds to `target/debug/`, so both can exist at the same time."}, {"type": "single", "q": "Which file should you **never** edit by hand?", "options": ["`Cargo.toml`", "`src/main.rs`", "`Cargo.lock`", "`README.md`"], "answer": 2, "hints": ["One file is written by Cargo to record exact dependency versions."], "explanation": "`Cargo.lock` is managed by Cargo. You *do* edit `Cargo.toml`, for example to add dependencies; Cargo then updates `Cargo.lock` itself.\n"}]}, {"type": "summary", "points": ["Cargo is Rust's build tool and package manager; its commands are the same on every operating system.", "`cargo new` creates `Cargo.toml` (settings) and `src/main.rs` (code); `Cargo.lock` appears on the first build.", "`cargo check` is the fast compile check, `cargo run` builds and runs, `cargo build --release` makes the optimized program.", "Development builds go to `target/debug/`, release builds to `target/release/`."]}], "terms": [{"term": "Cargo", "def": "Rust's build system and package manager. It builds code, downloads dependencies and runs tests."}, {"term": "crate", "def": "A package of Rust code. Your project is a crate; libraries you use are crates too."}, {"term": "dependency", "def": "A crate that your project uses, listed under `[dependencies]` in `Cargo.toml`."}, {"term": "Cargo.toml", "def": "The project settings file written in TOML: package name, version, edition and dependencies."}, {"term": "Cargo.lock", "def": "A file that records the exact versions of all dependencies so builds can be repeated. Managed by Cargo."}, {"term": "edition", "def": "A set of language conventions (2015, 2018, 2021, 2024) a crate opts into in `Cargo.toml`."}, {"term": "release profile", "def": "The build settings used by `cargo build --release`: slower to compile, faster to run."}], "id": "ch01-03-cargo", "chapter": "ch01", "kind": "lesson", "minutes": 25}, "ch01-99-test": {"title": "Chapter test: Getting Started", "kind": "test", "summary": "Ten questions on why Rust exists, your first program and Cargo. You need 70% to pass; you can retry.", "blocks": [{"type": "quiz", "id": "ch01-test", "pass_score": 0.7, "questions": [{"type": "single", "q": "A C program writes to `a[3]` of an array that has one element. What does the C standard say happens?", "options": ["The compiler refuses to build the program.", "The program always crashes immediately with a clear message.", "The behavior is undefined: the program may do anything.", "The array grows to four elements automatically."], "answer": 2, "hints": ["This is the four-line program from *Programming Rust*."], "explanation": "It is **undefined behavior**: the standard places no requirements at all, so the program might crash, print nonsense or be exploited. A Rust program doing the same with a vector stops with a clear `index out of bounds` panic instead.\n"}, {"type": "truefalse", "q": "If a Rust program compiles, it cannot contain any logic errors.", "answer": false, "hints": ["What exactly does the compiler know about your intentions?"], "explanation": "False. Rust rules out undefined behavior (invalid memory use, data races), not mistakes in your logic. A program that adds where it should subtract still compiles."}, {"type": "multi", "q": "Which are Rust's three goals, as *Rust in Action* puts them?", "options": ["Safety", "Productivity", "Control", "Garbage collection", "Dynamic typing"], "answer": [0, 1, 2], "hints": ["Two options describe things Rust specifically does *not* have."], "explanation": "Safety, productivity and control. Rust has no garbage collector, and it is statically typed: types are checked at compile time."}, {"type": "single", "q": "What does this program print?", "code": "fn main() {\n    println!(\"Ready\");\n    println!(\"Steady\");\n}\n", "lang": "rust", "options": ["`Ready Steady` on one line", "`Ready` and `Steady` on two lines", "Nothing: `main` is never called", "An error: two `println!` calls are not allowed"], "answer": 1, "hints": ["What does the `ln` in `println!` stand for?"], "explanation": "`println!` prints its text and then a new line, so each call prints one line. `main` runs automatically; you never call it yourself."}, {"type": "single", "q": "Which line would fail to compile?", "code": "fn main() {\n    println(\"Hello\");\n}\n", "lang": "rust", "options": ["Line 1: `main` needs parameters", "Line 2: `println` is missing its `!`", "Line 3: the bracket should be `)`", "None, it compiles"], "answer": 1, "hints": ["Is `println` a function or a macro?"], "explanation": "`println!` is a macro and must be called with `!`. Without it Rust looks for a *function* called `println`, which does not exist. `main` taking no parameters is correct."}, {"type": "fill", "q": "Which tool installs Rust and updates it with the `update` subcommand?", "answer": ["rustup"], "hints": ["Its name starts with `rust`."], "explanation": "`rustup` installs the toolchain; `rustup update` upgrades it and `rustup doc` opens the offline documentation."}, {"type": "order", "q": "Order a typical Cargo workflow for a brand-new program.", "items": ["`cargo new guess`", "Edit `src/main.rs`", "`cargo check` to find mistakes quickly", "`cargo run` to try it", "`cargo build --release` to make the final program"], "hints": ["You need a project before you can edit it, and you ship last."], "explanation": "Create, edit, check often, run to try, and build with optimizations at the end."}, {"type": "single", "q": "Where does Cargo expect your source files?", "options": ["In the project's top folder", "In `src/`", "In `target/`", "Anywhere, as long as it is listed in `Cargo.lock`"], "answer": 1, "hints": ["`cargo new` created one folder besides `target/` appearing later."], "explanation": "Source code goes in `src/`. The top folder holds `Cargo.toml`, README and license; `target/` holds build output."}, {"type": "truefalse", "q": "`cargo build --release` produces a faster program than `cargo build`, but takes longer to compile.", "answer": true, "hints": ["What does the release profile turn on?"], "explanation": "True. The release profile enables optimizations: slower to compile, faster to run. Always measure performance with the release build."}, {"type": "single", "q": "What is a crate?", "options": ["A compiled executable file", "A package of Rust code, such as your project or a library", "The `target/` folder", "Rust's error message format"], "answer": 1, "hints": ["Dependencies are listed as crates in `Cargo.toml`."], "explanation": "A **crate** is a package of Rust code. Your project is a crate, and the libraries listed under `[dependencies]` are crates too."}], "mode": "test"}], "id": "ch01-99-test", "chapter": "ch01", "minutes": 10}, "ch02-01-setup-input": {"title": "Reading what the player types", "summary": "Set up the game project and read a guess from the keyboard. Along the way you meet variables, mutability, String and Result.", "minutes": 22, "source": {"chapter": "ch02", "sections": ["TRPL 2 Setting Up a New Project", "TRPL 2 Processing a Guess", "TRPL 2 Storing Values with Variables", "TRPL 2 Receiving User Input", "TRPL 2 Handling Potential Failure with Result", "TRPL 2 Printing Values with println! Placeholders"]}, "blocks": [{"type": "text", "md": "Over the next three lessons you will build a classic beginner game. The program picks a secret number between 1 and 100. The player types a guess. The program says whether the guess was too small or too big. When the guess is right, the program congratulates the player and stops.\n\nThe game is small, but it uses a little of almost everything: **variables**, **user input**, **libraries**, **comparisons**, **loops** and **error handling**. You will meet each idea briefly here, then properly in later chapters. Don't worry if a detail feels fuzzy; the goal now is to see how the pieces fit.\n"}, {"type": "flow", "title": "How the finished game works", "nodes": [{"label": "Pick a secret", "detail": "The program picks a random number from 1 to 100 and keeps it hidden."}, {"label": "Ask for a guess", "detail": "It prints `Please input your guess.` and waits for the player to type a line and press Enter."}, {"label": "Turn text into a number", "detail": "What the player typed is **text**, like `\"42\\n\"`. It has to become the number `42` before it can be compared. If it is not a number, the game asks again."}, {"label": "Compare", "detail": "Is the guess smaller than, bigger than, or equal to the secret? The game prints `Too small!`, `Too big!` or `You win!`."}, {"label": "Repeat or stop", "detail": "On a wrong guess the game goes back to *Ask for a guess*. On the right guess it stops."}]}, {"type": "text", "title": "A new project", "md": "Create the project with Cargo, exactly as in chapter 1:\n"}, {"type": "code", "lang": "bash", "file": "terminal", "code": "cargo new guessing_game\ncd guessing_game\ncargo run\n", "output": "Hello, world!\n"}, {"type": "text", "title": "The first version", "md": "Replace everything in `src/main.rs` with the program below. It asks for a guess, reads it, and prints it back. Read it once top to bottom; then we take it apart line by line.\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "use std::io;\n\nfn main() {\n    println!(\"Guess the number!\");\n\n    println!(\"Please input your guess.\");\n\n    let mut guess = String::new();\n\n    io::stdin()\n        .read_line(&mut guess)\n        .expect(\"Failed to read line\");\n\n    println!(\"You guessed: {guess}\");\n}\n"}, {"type": "stepper", "title": "Line by line", "lang": "rust", "steps": [{"title": "Bring in the input/output library", "md": "Rust loads only a small set of names into every program automatically (the **prelude**). Anything else you name with `use`. `std` is the **standard library** that comes with Rust, and `io` is its part for input and output. After this line, `io::stdin()` works.\n", "code": "use std::io;\n", "highlight": [1]}, {"title": "Print two messages", "md": "`println!` prints a line, as you saw in chapter 1. Nothing new here.", "code": "println!(\"Guess the number!\");\nprintln!(\"Please input your guess.\");\n"}, {"title": "A variable that can change", "md": "`let` creates a **variable**: a name for a value. In Rust, variables are **immutable** by default: once given a value, they keep it. Adding `mut` (short for *mutable*) allows changing it later. We need `mut` because reading the input will *fill* this variable.\n\n`String::new()` makes a new, empty **String**, Rust's growable text type. The `::` means `new` belongs to the `String` type. A function that belongs to a type like this is called an **associated function**.\n", "code": "let mut guess = String::new();\n", "highlight": [1]}, {"title": "Read a line from the keyboard", "md": "`io::stdin()` gives a handle to the program's **standard input**: by default, the keyboard in the terminal. `.read_line(...)` waits until the user presses Enter and **appends** what was typed to a String.\n\n`&mut guess` hands over the variable so `read_line` can write into it. The `&` makes it a **reference**: `read_line` gets access to `guess` without taking it over, and `mut` says the access allows changing it. References are the subject of chapter 4; for now, read `&mut guess` as *lend `guess` out for writing*.\n", "code": "io::stdin()\n    .read_line(&mut guess)\n", "highlight": [2]}, {"title": "Deal with possible failure", "md": "Reading can fail (for example if the input is not valid text). So `read_line` does not just return a value: it returns a **Result**, which is either `Ok` (it worked) or `Err` (it failed, with an explanation).\n\n`.expect(\"...\")` says: if this is `Err`, stop the program and show this message; if it is `Ok`, give me the value inside. Stopping like this is called a **panic**. It is fine for a first program; later lessons show how to recover instead.\n", "code": "io::stdin()\n    .read_line(&mut guess)\n    .expect(\"Failed to read line\");\n", "highlight": [3]}, {"title": "Print with a placeholder", "md": "Curly brackets inside the text are **placeholders**. `{guess}` is replaced by the value of the variable `guess`. To print the result of an expression instead, leave the brackets empty and put the expression after the text: `println!(\"x + y = {}\", x + y);`.\n", "code": "println!(\"You guessed: {guess}\");\n", "highlight": [1]}]}, {"type": "callout", "kind": "warning", "title": "Forgot expect? You get a warning", "md": "If you delete `.expect(...)`, the program still compiles, but Rust warns: `unused Result that must be used`. The compiler is reminding you that an error could happen and you have not decided what to do about it. Rust makes ignoring errors something you have to do on purpose.\n"}, {"type": "code", "lang": "bash", "file": "terminal", "title": "Try the program", "code": "$ cargo run\n   Compiling guessing_game v0.1.0 (file:///projects/guessing_game)\n    Finished `dev` profile [unoptimized + debuginfo] target(s) in 6.44s\n     Running `target/debug/guessing_game`\nGuess the number!\nPlease input your guess.\n6\nYou guessed: 6\n", "highlight": [7, 8]}, {"type": "callout", "kind": "note", "title": "Why the page's console uses a fixed input", "md": "The console in this page runs the program for you, but it cannot type into it. So playgrounds in this chapter put the \"typed\" text straight into the String instead of reading the keyboard. To play the real game, run it with `cargo run` in a terminal.\n"}, {"type": "playground", "id": "ch02-play-placeholders", "title": "Placeholders", "lang": "rust", "md": "Run this program. Then add a line that uses empty `{}` placeholders to print `5 + 10 = 15`, calculating the sum in Rust rather than typing 15.", "task": "Make the program print exactly two lines: `x = 5 and y = 10`, then `5 + 10 = 15`.", "code": "fn main() {\n    let x = 5;\n    let y = 10;\n\n    println!(\"x = {x} and y = {y}\");\n    // add your line here\n}\n", "expected_output": "x = 5 and y = 10\n5 + 10 = 15\n", "hints": ["`println!(\"{} + {} = {}\", x, y, x + y);` fills the three empty placeholders in order.", "Inside named placeholders like `{x}` you can only write a variable name, not `x + y`. That is why the sum needs an empty `{}`."]}, {"type": "reveal", "prompt": "This program does not compile. Without running it, which line does the compiler complain about, and why?\n\n```rust\nfn main() {\n    let count = 1;\n    count = 2;\n    println!(\"{count}\");\n}\n```", "md": "Line 3, `count = 2;`. `count` was created without `mut`, so it is immutable and cannot be given a new value. The error is `cannot assign twice to immutable variable`, and the compiler even suggests the fix: `let mut count = 1;`.\n"}, {"type": "playground", "id": "ch02-play-mutable", "title": "Fix the immutable variable", "lang": "rust", "task": "Make this compile without removing any line, so it prints `2`.", "code": "fn main() {\n    let count = 1;\n    count = 2;\n    println!(\"{count}\");\n}\n", "expected_output": "2", "hints": ["Press Run first and read the compiler's error message: it tells you the fix.", "Add `mut` after `let`."]}, {"type": "text", "title": "What read_line really puts in the String", "md": "When the player types `6` and presses Enter, the String does not contain just `6`. It contains `6` followed by a **newline** character, written `\\n` in Rust (on Windows, `\\r\\n`). That is why `You guessed: 6` is followed by an empty line in the terminal: the newline is printed too. The next lesson removes it with `trim` before turning the text into a number.\n"}, {"type": "playground", "id": "ch02-play-newline", "title": "See the hidden newline", "lang": "rust", "md": "Here the typed line is written into the String by hand. `{:?}` is a **debug** placeholder: it shows a value the way a programmer would write it, so the `\\n` becomes visible. Run it, then change the second `println!` so it prints the guess *without* the newline by using `guess.trim()`.", "task": "Print `\"42\\n\"` (with the quotes, from the debug placeholder) and then `[42]`.", "code": "fn main() {\n    let mut guess = String::new();\n    guess.push_str(\"42\\n\"); // pretend the player typed 42 and pressed Enter\n\n    println!(\"{:?}\", guess);\n    println!(\"[{}]\", guess);\n}\n", "expected_output": "\"42\\n\"\n[42]\n", "hints": ["`trim()` gives back the text without spaces or newlines at the start and end.", "Change the last line to `println!(\"[{}]\", guess.trim());`."]}, {"type": "quiz", "id": "ch02-quiz-input", "title": "Check yourself", "questions": [{"type": "single", "q": "Why is the variable declared as `let mut guess` and not `let guess`?", "options": ["`String` values must always be mutable.", "`read_line` writes into the variable, so it has to be changeable.", "`mut` makes the variable visible to other functions.", "Without `mut`, the program would read numbers only."], "answer": 1, "explanation": "Variables are immutable by default. `read_line(&mut guess)` adds the typed text to `guess`, which changes it, so `guess` must be declared `mut`.", "hints": []}, {"type": "fill", "q": "Complete the line so the program stops with the message `Failed to read line` if reading fails: `io::stdin().read_line(&mut guess).______(\"Failed to read line\");`", "answer": ["expect"], "explanation": "`expect` returns the value inside `Ok`, or panics with your message on `Err`.", "hints": []}, {"type": "truefalse", "q": "After the player types `7` and presses Enter, `guess` contains exactly the text `7`.", "answer": false, "explanation": "It contains `7\\n` (or `7\\r\\n` on Windows): Enter is part of what `read_line` reads.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "let a = 3;\nlet b = 4;\nprintln!(\"{a} * {b} = {}\", a * b);\n", "lang": "rust", "options": ["`{a} * {b} = 12`", "`3 * 4 = {}`", "`3 * 4 = 12`", "Nothing: it does not compile"], "answer": 2, "explanation": "Named placeholders take variables; the empty `{}` takes the expression `a * b` listed after the text.", "hints": []}, {"type": "order", "q": "Put the steps of reading a guess in the order they happen in the program.", "items": ["Create an empty, mutable String", "Get a handle to standard input", "Read a line into the String", "Panic if reading failed, otherwise continue", "Print the guess"], "explanation": "`String::new()`, `io::stdin()`, `.read_line(&mut guess)`, `.expect(...)`, then `println!`.", "hints": []}]}, {"type": "summary", "points": ["`use std::io;` brings the standard library's input/output module into scope.", "`let` makes a variable; it is immutable unless you write `let mut`.", "`String::new()` creates an empty, growable text value; `::` calls a function that belongs to a type.", "`read_line(&mut guess)` appends the typed line, newline included, to `guess`.", "`read_line` returns a `Result` (`Ok` or `Err`); `.expect(\"msg\")` unwraps it or panics with your message.", "`{name}` prints a variable; `{}` prints the next expression after the text; `{:?}` shows the debug form."]}], "terms": [{"term": "variable", "def": "A name bound to a value with `let`. Immutable by default; `let mut` makes it changeable."}, {"term": "String", "def": "Rust's growable, owned UTF-8 text type. `String::new()` makes an empty one."}, {"term": "associated function", "def": "A function that belongs to a type and is called with `::`, like `String::new()`."}, {"term": "Result", "def": "A value that is either `Ok(value)` for success or `Err(error)` for failure. Rust uses it for anything that can fail."}, {"term": "panic", "def": "Stopping the program immediately with an error message, for example when `expect` meets an `Err`."}, {"term": "reference", "def": "A way to let code use a value without taking it over, written `&value` (read-only) or `&mut value` (may change it)."}, {"term": "prelude", "def": "The short list of names Rust brings into every program automatically, such as `String` and `println!`."}], "id": "ch02-01-setup-input", "chapter": "ch02", "kind": "lesson"}, "ch02-02-random-compare": {"title": "A secret number and a comparison", "summary": "Add your first library from crates.io to pick a random number, then compare the guess with match. You also turn text into a number and meet shadowing.", "minutes": 28, "source": {"chapter": "ch02", "sections": ["TRPL 2 Generating a Secret Number", "TRPL 2 Using a Crate to Get More Functionality", "TRPL 2 Ensuring Reproducible Builds", "TRPL 2 Updating a Crate", "TRPL 2 Comparing the Guess to the Secret Number"]}, "blocks": [{"type": "text", "md": "The game needs a secret number that changes every time it is played. Rust's standard library does not generate random numbers, on purpose: it stays small, and the community maintains excellent libraries instead. In this lesson you add one of them, then compare the player's guess with the secret.\n"}, {"type": "text", "title": "Crates and crates.io", "md": "A **crate** is a package of Rust code. Your guessing game is a **binary crate**: it builds into a program you can run. The `rand` crate is a **library crate**: code meant to be used by other programs, which cannot run on its own.\n\nLibraries are published on **crates.io**, the public registry of Rust crates. To use one, you name it and its version in the `[dependencies]` section of `Cargo.toml`. Cargo downloads it (and anything it needs in turn) the next time you build.\n"}, {"type": "code", "lang": "toml", "file": "Cargo.toml", "code": "[package]\nname = \"guessing_game\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\nrand = \"0.10.1\"\n", "highlight": [7]}, {"type": "callout", "kind": "key", "title": "What \"0.10.1\" means", "md": "Cargo reads versions as **Semantic Versioning** (SemVer). `\"0.10.1\"` is short for `^0.10.1`: *at least 0.10.1, but below 0.11.0*. Versions inside that range promise to stay compatible with the code you wrote, so Cargo may pick a newer one with bug fixes, but never one that could break your program.\n"}, {"type": "code", "lang": "bash", "file": "terminal", "title": "The first build downloads the crate", "code": "$ cargo build\n  Updating crates.io index\n Locking 3 packages to latest Rust 1.97.0 compatible versions\nDownloaded rand_core v0.10.1\nDownloaded rand v0.10.1\n   Compiling rand_core v0.10.1\n   Compiling getrandom v0.4.3\n   Compiling rand v0.10.1\n   Compiling guessing_game v0.1.0 (file:///projects/guessing_game)\n    Finished `dev` profile [unoptimized + debuginfo] target(s) in 2.13s\n", "explain": "You asked for one crate and got several: `rand` itself depends on `rand_core` and `getrandom`, and Cargo fetched them too. Build again and nothing is downloaded or recompiled: Cargo remembers what it built.\n"}, {"type": "text", "title": "Cargo.lock keeps builds repeatable", "md": "The first build also writes **Cargo.lock**, listing the exact version of every crate it chose. Later builds use exactly those versions, even if a newer compatible one appears on crates.io. So the program you build next month, or a teammate builds today, uses the same code as yours. Commit `Cargo.lock` to version control together with your source.\n\nWhen you *want* newer versions, run `cargo update`. It picks the newest versions allowed by `Cargo.toml` (still below 0.11.0 here) and rewrites the lock file. Moving to 0.11 or later is a deliberate step: you change the number in `Cargo.toml` yourself.\n"}, {"type": "table", "title": "Who decides which version you get", "headers": ["File", "Written by", "Says"], "rows": [["`Cargo.toml`", "You", "Which crates, and which range of versions is acceptable"], ["`Cargo.lock`", "Cargo", "The exact version of every crate actually used"], ["`cargo update`", "You run it", "Move to the newest versions the ranges allow, update the lock file"]]}, {"type": "text", "title": "Generating the number", "md": "Two new lines create the secret. `use rand::prelude::*;` brings in the most commonly used parts of `rand` (the `*` means *everything public in it*). Then `rand::rng()` gives a random number generator seeded by the operating system, and `.random_range(1..=100)` asks it for a number in a range.\n\n`1..=100` is a **range expression**. With `..=` both ends are included, so 1 and 100 are both possible. With `..` (as in `1..100`) the end is left out.\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "use std::io;\n\nuse rand::prelude::*;\n\nfn main() {\n    println!(\"Guess the number!\");\n\n    let secret_number = rand::rng().random_range(1..=100);\n\n    println!(\"The secret number is: {secret_number}\");\n\n    println!(\"Please input your guess.\");\n\n    let mut guess = String::new();\n\n    io::stdin()\n        .read_line(&mut guess)\n        .expect(\"Failed to read line\");\n\n    println!(\"You guessed: {guess}\");\n}\n", "highlight": [3, 8, 10], "explain": "Printing the secret is only for testing. You will remove that line once the game works."}, {"type": "callout", "kind": "tip", "title": "Documentation for every crate you use", "md": "Run `cargo doc --open` inside the project. Cargo builds documentation for all your dependencies and opens it in the browser, so you can look up what `random_range` or anything else in `rand` does, even offline."}, {"type": "text", "title": "Comparing the guess with the secret", "md": "Now the interesting part. Here is the comparison, using a new tool called `match`:\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs (part)", "code": "use std::cmp::Ordering;\n\n// ... inside main, after reading the guess:\nmatch guess.cmp(&secret_number) {\n    Ordering::Less => println!(\"Too small!\"),\n    Ordering::Greater => println!(\"Too big!\"),\n    Ordering::Equal => println!(\"You win!\"),\n}\n"}, {"type": "stepper", "title": "How the comparison works", "lang": "rust", "steps": [{"title": "Ordering: the three possible answers", "md": "`Ordering` is an **enum** (short for enumeration): a type whose value is exactly one of a fixed list of **variants**. `Ordering` has three: `Less`, `Greater` and `Equal`. Those are the only possible results of comparing two values.\n", "code": "use std::cmp::Ordering;\n// Ordering is one of: Ordering::Less, Ordering::Greater, Ordering::Equal\n"}, {"title": "cmp compares two values", "md": "`a.cmp(&b)` compares `a` with `b` and returns an `Ordering`. Anything that can be ordered (numbers, text, ...) has `cmp`.", "code": "guess.cmp(&secret_number)\n"}, {"title": "match picks the arm that fits", "md": "A `match` expression is made of **arms**. Each arm is a **pattern** followed by `=>` and the code to run. Rust checks the value against each pattern from top to bottom and runs the first arm that fits. If the guess is 50 and the secret 38, `cmp` returns `Ordering::Greater`: the first arm does not fit, the second does, so `Too big!` is printed and the `match` ends.\n", "code": "match guess.cmp(&secret_number) {\n    Ordering::Less => println!(\"Too small!\"),\n    Ordering::Greater => println!(\"Too big!\"),\n    Ordering::Equal => println!(\"You win!\"),\n}\n", "highlight": [3]}, {"title": "Rust checks you covered every case", "md": "Delete one arm and the program does not compile: `non-exhaustive patterns: Ordering::Equal not covered`. A `match` must handle **every** possible value. This is one of the ways Rust catches forgotten cases before the program ever runs.\n", "code": "match guess.cmp(&secret_number) {\n    Ordering::Less => println!(\"Too small!\"),\n    Ordering::Greater => println!(\"Too big!\"),\n    // error[E0004]: non-exhaustive patterns: `Equal` not covered\n}\n"}]}, {"type": "text", "title": "Text is not a number: mismatched types", "md": "If you build now, the compiler stops with `error[E0308]: mismatched types ... expected struct String, found integer`. `guess` is a `String` (text), while `secret_number` is a number. Rust is **statically typed**: every value has a type known at compile time, and it will not silently compare text with a number.\n\nThe secret's type was **inferred**: Rust saw a number from 1 to 100 and picked `i32`, its default integer type. We need to turn the guess into a number too. We add one line:\n"}, {"type": "code", "lang": "rust", "code": "let guess: u32 = guess.trim().parse().expect(\"Please type a number!\");\n", "explain": "- `guess.trim()` removes the newline (and any spaces) around the text, so `\"5\\n\"` becomes `\"5\"`.\n- `.parse()` converts text into another type. Which type? The one we wrote after the colon: `u32`, an unsigned (never negative) 32-bit integer. This is a **type annotation**.\n- Parsing can fail (the player might type `abc`), so `parse` returns a `Result`, and `.expect` handles it as before.\n\nBecause `guess` is now a `u32` and it is compared with `secret_number`, Rust infers that `secret_number` should be a `u32` too.\n"}, {"type": "callout", "kind": "key", "title": "Shadowing", "md": "Notice that the new line *reuses the name* `guess` with `let`. This is **shadowing**: a new variable with the same name hides the old one from that point on. It is handy for converting a value from one type to another without inventing names like `guess_str` and `guess_num`. Shadowing makes a brand-new variable (it may even have a different type), which is different from changing a `mut` variable.\n"}, {"type": "playground", "id": "ch02-play-compare", "title": "Compare a guess", "lang": "rust", "md": "This is the game's comparison with fixed values instead of keyboard input and randomness. Run it. Then change the text in `typed` to `\"38\\n\"` and run again.", "task": "With `typed` set so the guess equals the secret, the program prints `You guessed: 38` and then `You win!`.", "code": "use std::cmp::Ordering;\n\nfn main() {\n    let secret_number: u32 = 38;\n    let typed = String::from(\"50\\n\"); // what the player \"typed\"\n\n    let guess: u32 = typed.trim().parse().expect(\"Please type a number!\");\n    println!(\"You guessed: {guess}\");\n\n    match guess.cmp(&secret_number) {\n        Ordering::Less => println!(\"Too small!\"),\n        Ordering::Greater => println!(\"Too big!\"),\n        Ordering::Equal => println!(\"You win!\"),\n    }\n}\n", "expected_output": "You guessed: 38\nYou win!\n", "hints": ["Only the text inside `String::from(...)` needs to change.", "`String::from(\"38\\n\")`. The `\\n` is the Enter key; `trim()` removes it."]}, {"type": "playground", "id": "ch02-play-parse-fail", "expect_panic": true, "title": "What happens with bad input?", "lang": "rust", "md": "Run this. The player typed `forty`, which is not a number, so `parse` returns `Err` and `expect` **panics**. Read the message in the console: it names the file, the line, and the reason (`invalid digit found in string`). Then try `\"-5\\n\"`: why does that fail for a `u32`? The next lesson replaces the panic with a friendly second chance.\n", "code": "fn main() {\n    let typed = String::from(\"forty\\n\");\n    let guess: u32 = typed.trim().parse().expect(\"Please type a number!\");\n    println!(\"You guessed: {guess}\");\n}\n", "hints": ["`u32` is unsigned: it can hold 0 to 4,294,967,295 but no negative numbers, so `-5` is invalid for it."]}, {"type": "from_book", "source": "Programming Rust, ch. 2", "md": "*Programming Rust* makes the same point about types with its first function, which computes the greatest common divisor of two numbers. Rust insists on types at function boundaries (`u64` here: an unsigned 64-bit integer) and infers them inside. `assert!` checks a condition and panics if it is false, so the function refuses the input it cannot handle instead of returning nonsense.\n", "code": "fn gcd(mut n: u64, mut m: u64) -> u64 {\n    assert!(n != 0 && m != 0);\n    while m != 0 {\n        if m < n {\n            let t = m;\n            m = n;\n            n = t;\n        }\n        m = m % n;\n    }\n    n\n}\n", "lang": "rust"}, {"type": "quiz", "id": "ch02-quiz-compare", "title": "Check yourself", "questions": [{"type": "single", "q": "Your `Cargo.toml` says `rand = \"0.10.1\"`. Which version could `cargo update` move you to?", "options": ["0.10.4", "0.11.0", "1.0.0", "Only exactly 0.10.1"], "answer": 0, "explanation": "`0.10.1` means at least 0.10.1 and below 0.11.0. Crossing to 0.11 needs a change in `Cargo.toml`.", "hints": []}, {"type": "truefalse", "q": "You should commit `Cargo.lock` so everyone builds with the same dependency versions.", "answer": true, "explanation": "For programs, yes: the lock file is what makes builds repeatable.", "hints": []}, {"type": "single", "q": "The secret is 70 and the guess is 25. Which arm runs?", "code": "match guess.cmp(&secret_number) {\n    Ordering::Less => println!(\"Too small!\"),\n    Ordering::Greater => println!(\"Too big!\"),\n    Ordering::Equal => println!(\"You win!\"),\n}\n", "lang": "rust", "options": ["`Too small!`", "`Too big!`", "`You win!`", "All three, top to bottom"], "answer": 0, "explanation": "25 compared with 70 is `Less`. Only the first matching arm runs, then the `match` is done.", "hints": []}, {"type": "multi", "q": "Which numbers can `random_range(1..=100)` return?", "options": ["0", "1", "50", "100", "101"], "answer": [1, 2, 3], "explanation": "`..=` includes both ends, so 1 through 100. `1..100` would exclude 100.", "hints": []}, {"type": "single", "q": "Why does `let guess: u32 = guess.trim().parse()...` need the `: u32`?", "options": ["Without it, `parse` does not know what type to produce.", "Variables must always have written types in Rust.", "It makes `guess` mutable.", "It removes the newline."], "answer": 0, "explanation": "`parse` can produce many types. The annotation tells it which one; elsewhere Rust usually infers types for you.", "hints": []}, {"type": "fill", "q": "Reusing a variable name with a new `let`, as in `let guess: u32 = guess.trim()...`, is called ______.", "answer": ["shadowing"], "explanation": "Shadowing creates a new variable that hides the previous one with the same name.", "hints": []}, {"type": "single", "q": "Which mistake causes this error? `error[E0308]: mismatched types: expected struct String, found integer`", "options": ["A `String` was compared with a number", "A variable was changed without `mut`", "A `match` is missing an arm", "A crate was not downloaded"], "answer": 0, "explanation": "`guess.cmp(&secret_number)` before converting the guess: Rust never compares text with numbers implicitly.", "hints": []}]}, {"type": "summary", "points": ["Crates are packages of Rust code; binary crates run, library crates are used by others. They live on crates.io.", "List dependencies in `Cargo.toml`; `\"0.10.1\"` accepts compatible versions from 0.10.1 up to (not including) 0.11.0.", "`Cargo.lock` pins exact versions for repeatable builds; `cargo update` refreshes it within the allowed ranges.", "`rand::rng().random_range(1..=100)` picks a number from 1 to 100; `..=` includes the end, `..` excludes it.", "`a.cmp(&b)` returns an `Ordering` (`Less`, `Greater`, `Equal`); `match` runs the first arm whose pattern fits and must cover every case.", "`text.trim().parse()` turns text into a number; the type comes from the annotation, like `let n: u32`.", "Shadowing reuses a name with a new `let`, often to change a value's type."]}], "terms": [{"term": "crate", "def": "A package of Rust code. A binary crate builds a program; a library crate is code for other programs to use."}, {"term": "crates.io", "def": "The public registry where Rust crates are published and downloaded from."}, {"term": "Semantic Versioning", "def": "Version numbers as MAJOR.MINOR.PATCH with rules about compatibility. Cargo uses it to decide which versions are safe."}, {"term": "Cargo.lock", "def": "File written by Cargo listing the exact versions of all dependencies, so builds can be repeated."}, {"term": "match", "def": "An expression that compares a value against patterns (arms) and runs the code of the first one that fits. It must cover every possible value."}, {"term": "enum", "def": "A type whose value is one of a fixed list of variants, like `Ordering::Less`, `Ordering::Greater`, `Ordering::Equal`."}, {"term": "type annotation", "def": "Writing a type explicitly, as in `let n: u32 = ...`, when Rust cannot or should not infer it."}, {"term": "shadowing", "def": "Declaring a new variable with the same name as an earlier one, which hides the earlier one from then on."}], "id": "ch02-02-random-compare", "chapter": "ch02", "kind": "lesson"}, "ch02-03-loop-quit": {"title": "Play until you win", "summary": "Repeat the game with loop, stop with break, and replace the crash on bad input with a second chance. Then build the game's logic yourself, checked by real tests.", "minutes": 40, "source": {"chapter": "ch02", "sections": ["TRPL 2 Allowing Multiple Guesses with Looping", "TRPL 2 Quitting After a Correct Guess", "TRPL 2 Handling Invalid Input", "PR ch2 Writing and Running Unit Tests", "PR ch2 Handling Command-Line Arguments"]}, "blocks": [{"type": "text", "md": "The game so far allows exactly one guess. In this lesson you make it repeat until the player wins, stop cleanly, and survive input like `foo` without crashing. Then you write the game's logic yourself as small functions, and Rust's test runner tells you when they are right.\n"}, {"type": "text", "title": "loop and break", "md": "`loop` repeats a block of code **forever**: when the end of the block is reached, it starts again at the top. To get out, use `break`, which ends the loop immediately. In the game we break when the guess is correct. Because `match` arms can hold several statements inside `{ }`, the `Equal` arm can both print and break:\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs (part)", "code": "loop {\n    println!(\"Please input your guess.\");\n\n    // ... read and parse the guess as before ...\n\n    match guess.cmp(&secret_number) {\n        Ordering::Less => println!(\"Too small!\"),\n        Ordering::Greater => println!(\"Too big!\"),\n        Ordering::Equal => {\n            println!(\"You win!\");\n            break;\n        }\n    }\n}\n", "highlight": [1, 9, 10, 11, 12]}, {"type": "text", "title": "A second chance instead of a crash", "md": "With `.expect`, typing `foo` still crashes the whole game. We want to ignore the bad line and ask again. Since `parse` returns a `Result`, we can `match` on it just like on `Ordering`:\n"}, {"type": "code", "lang": "rust", "code": "let guess: u32 = match guess.trim().parse() {\n    Ok(num) => num,\n    Err(_) => continue,\n};\n", "explain": "- If parsing worked, the value is `Ok(num)`. The pattern `Ok(num)` **binds** the number inside to the name `num`, and the arm's result is `num`. That becomes the value of the whole `match`, which is stored in `guess`.\n- If parsing failed, the value is `Err(...)`. The `_` is a **catch-all**: it matches any error, and we don't care which. `continue` jumps straight to the next round of the `loop`, so the game asks for another guess.\n\nMoving from `expect` to `match` is the usual path in Rust: crash while you are sketching, then handle the error properly.\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "title": "The finished game", "code": "use std::cmp::Ordering;\nuse std::io;\n\nuse rand::prelude::*;\n\nfn main() {\n    println!(\"Guess the number!\");\n\n    let secret_number = rand::rng().random_range(1..=100);\n\n    loop {\n        println!(\"Please input your guess.\");\n\n        let mut guess = String::new();\n\n        io::stdin()\n            .read_line(&mut guess)\n            .expect(\"Failed to read line\");\n\n        let guess: u32 = match guess.trim().parse() {\n            Ok(num) => num,\n            Err(_) => continue,\n        };\n\n        println!(\"You guessed: {guess}\");\n\n        match guess.cmp(&secret_number) {\n            Ordering::Less => println!(\"Too small!\"),\n            Ordering::Greater => println!(\"Too big!\"),\n            Ordering::Equal => {\n                println!(\"You win!\");\n                break;\n            }\n        }\n    }\n}\n", "output": "Guess the number!\nPlease input your guess.\n10\nYou guessed: 10\nToo small!\nPlease input your guess.\nfoo\nPlease input your guess.\n61\nYou guessed: 61\nYou win!\n", "explain": "Copy this into your project and run `cargo run` to play. Notice that `foo` simply leads to another prompt."}, {"type": "playground", "id": "ch02-play-loop", "title": "A whole game, played by the computer", "lang": "rust", "md": "Here the player's lines come from a list instead of the keyboard, so the console can run a full game. `for typed in inputs` runs the loop body once for each line in the list (you will learn `for` properly in chapter 3). Run it and read the output.\n", "task": "Add `\"oops\"` as the first entry of `inputs`, and change `continue` so that, before skipping, the game prints `Please type a number!`. The output must then start with `Please type a number!`.", "code": "use std::cmp::Ordering;\n\nfn main() {\n    let secret_number: u32 = 61;\n    let inputs = [\"10\", \"80\", \"61\", \"99\"];\n\n    for typed in inputs {\n        let guess: u32 = match typed.trim().parse() {\n            Ok(num) => num,\n            Err(_) => continue,\n        };\n\n        println!(\"You guessed: {guess}\");\n\n        match guess.cmp(&secret_number) {\n            Ordering::Less => println!(\"Too small!\"),\n            Ordering::Greater => println!(\"Too big!\"),\n            Ordering::Equal => {\n                println!(\"You win!\");\n                break;\n            }\n        }\n    }\n}\n", "expected_output": "Please type a number!\nYou guessed: 10\nToo small!\nYou guessed: 80\nToo big!\nYou guessed: 61\nYou win!\n", "hints": ["The list becomes `[\"oops\", \"10\", \"80\", \"61\", \"99\"]`.", "An arm can run several statements inside braces: `Err(_) => { println!(\"Please type a number!\"); continue; }`", "Why is `99` never used? `break` leaves the loop as soon as the player wins."]}, {"type": "text", "title": "Splitting logic out so it can be tested", "md": "Real Rust projects keep their logic in small **functions** that take values and return results, and leave reading the keyboard to `main`. Functions like that can be checked automatically by **unit tests**: small functions marked `#[test]` that call your code and check the result with `assert_eq!(actual, expected)`. `cargo test` finds and runs them all.\n\n*Programming Rust* shows this right after its `gcd` function:\n"}, {"type": "code", "lang": "rust", "code": "#[test]\nfn test_gcd() {\n    assert_eq!(gcd(14, 15), 1);\n    assert_eq!(gcd(2 * 3 * 5 * 11 * 17, 3 * 7 * 11 * 13 * 19), 3 * 11);\n}\n", "explain": "`#[test]` is an **attribute**: a note to the compiler. It marks `test_gcd` as a test, so it is compiled and run by `cargo test` and left out of a normal build. If an `assert_eq!` sees two different values, the test fails and shows both. You will write tests yourself in chapter 11; for now you will *use* them to check your exercises.\n"}, {"type": "callout", "kind": "note", "title": "How the exercises below work", "md": "Press **Open in console**, write your code in `src/lib.rs`, and press **Run tests**. The tests in `src/tests.rs` are read-only; open that tab to see exactly what is checked. Each test turns green when your function returns the right value. With `start.sh` running, your edits are also saved into `exercises/<folder>/src/lib.rs`, so you can work in your own editor and run `cargo test` there.\n\n`todo!()` in the starter code is a placeholder that panics when reached. Replace it with your code.\n"}, {"type": "exercise", "id": "ch02-ex-compare", "exercise_dir": "ch02-compare", "title": "Too small, too big, you win", "difficulty": "easy", "goal": "Write the function at the heart of the game: given a guess and the secret, return the message the game prints.", "behavior": "`pub fn verdict(guess: u32, secret: u32) -> &'static str` returns:\n\n- `\"Too small!\"` when `guess` is less than `secret`\n- `\"Too big!\"` when `guess` is greater than `secret`\n- `\"You win!\"` when they are equal\n\n(`&'static str` is the type of a piece of fixed text written in quotes in your program. Chapter 4 explains the `&` and chapter 10 the `'static`.)\n", "examples": [{"input": "verdict(10, 61)", "output": "\"Too small!\""}, {"input": "verdict(80, 61)", "output": "\"Too big!\""}, {"input": "verdict(61, 61)", "output": "\"You win!\""}], "hints": ["Start with `use std::cmp::Ordering;` at the top of the file.", "`match guess.cmp(&secret) { ... }` with three arms; each arm's result is the text, with no `println!` and no semicolon.", "A function returns the value of its last expression, so the `match` itself can be the last thing in the function."], "solution_explain": "The `match` is the last expression of the function, so its value is returned. Each arm produces a piece of text instead of printing it, which is what makes the function testable.", "mode": "tests", "dir": "ch02-compare", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// Returns what the game says for this guess.\npub fn verdict(guess: u32, secret: u32) -> &'static str {\n    // TODO: compare `guess` with `secret` and return\n    // \"Too small!\", \"Too big!\" or \"You win!\".\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch02_compare\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn smaller_guess_is_too_small() {\n    assert_eq!(verdict(10, 61), \"Too small!\", \"guess 10, secret 61\");\n}\n\n#[test]\nfn bigger_guess_is_too_big() {\n    assert_eq!(verdict(80, 61), \"Too big!\", \"guess 80, secret 61\");\n}\n\n#[test]\nfn equal_guess_wins() {\n    assert_eq!(verdict(61, 61), \"You win!\", \"guess 61, secret 61\");\n}\n\n#[test]\nfn edges_of_the_range() {\n    assert_eq!(verdict(1, 100), \"Too small!\", \"guess 1, secret 100\");\n    assert_eq!(verdict(100, 1), \"Too big!\", \"guess 100, secret 1\");\n    assert_eq!(verdict(1, 1), \"You win!\", \"guess 1, secret 1\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "use std::cmp::Ordering;\n\n/// Returns what the game says for this guess.\npub fn verdict(guess: u32, secret: u32) -> &'static str {\n    match guess.cmp(&secret) {\n        Ordering::Less => \"Too small!\",\n        Ordering::Greater => \"Too big!\",\n        Ordering::Equal => \"You win!\",\n    }\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "exercise", "id": "ch02-ex-parse-guess", "exercise_dir": "ch02-parse-guess", "title": "Read a guess safely", "difficulty": "easy", "goal": "Turn a line typed by the player into a guess, without ever crashing on bad input.", "behavior": "`pub fn parse_guess(line: &str) -> Option<u32>` returns:\n\n- `Some(n)` when the line, after removing surrounding spaces and the newline, is a whole number `n` from **1 to 100**\n- `None` for anything else: text, an empty line, negative numbers, 0, or numbers above 100\n\n**Option** is a close cousin of Result for \"maybe there is a value\": it is either `Some(value)` or `None`. Chapter 6 covers it fully.\n", "examples": [{"input": "\"42\\n\"", "output": "Some(42)"}, {"input": "\"  7  \"", "output": "Some(7)"}, {"input": "\"foo\\n\"", "output": "None"}, {"input": "\"101\\n\"", "output": "None", "note": "Outside the game's range"}], "hints": ["`match line.trim().parse::<u32>() { Ok(n) => ..., Err(_) => None }`. The `::<u32>` tells `parse` the target type without a `let` annotation.", "Inside the `Ok(n)` arm, check the range: `if n >= 1 && n <= 100 { Some(n) } else { None }`. In Rust, `if` produces a value too.", "Parsing `\"-5\"` as `u32` already fails, so negative numbers land in the `Err` arm by themselves."], "solution_explain": "`trim` handles spaces and both kinds of newline. `parse::<u32>()` rejects text and negative numbers by returning `Err`. The `if` inside the `Ok` arm rejects numbers outside the game's range. (Later you will learn shorter ways to write this, such as `.ok()` and `.filter(...)`.)", "mode": "tests", "dir": "ch02-parse-guess", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// Turns one typed line into a guess from 1 to 100, or None if it is not one.\npub fn parse_guess(line: &str) -> Option<u32> {\n    // TODO: trim the line, parse it as u32,\n    // and return Some(number) only if it is between 1 and 100.\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch02_parse_guess\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn plain_number_with_newline() {\n    assert_eq!(parse_guess(\"42\\n\"), Some(42), \"input \\\"42\\\\n\\\"\");\n}\n\n#[test]\nfn spaces_and_windows_newline_are_ignored() {\n    assert_eq!(parse_guess(\"  7  \"), Some(7), \"input \\\"  7  \\\"\");\n    assert_eq!(parse_guess(\"15\\r\\n\"), Some(15), \"input \\\"15\\\\r\\\\n\\\"\");\n}\n\n#[test]\nfn text_is_not_a_guess() {\n    assert_eq!(parse_guess(\"foo\\n\"), None, \"input \\\"foo\\\\n\\\"\");\n    assert_eq!(parse_guess(\"\\n\"), None, \"an empty line\");\n    assert_eq!(parse_guess(\"4 2\"), None, \"input \\\"4 2\\\"\");\n}\n\n#[test]\nfn numbers_outside_1_to_100_are_rejected() {\n    assert_eq!(parse_guess(\"0\"), None, \"input \\\"0\\\"\");\n    assert_eq!(parse_guess(\"101\"), None, \"input \\\"101\\\"\");\n    assert_eq!(parse_guess(\"-5\"), None, \"input \\\"-5\\\"\");\n}\n\n#[test]\nfn both_ends_of_the_range_are_allowed() {\n    assert_eq!(parse_guess(\"1\"), Some(1), \"input \\\"1\\\"\");\n    assert_eq!(parse_guess(\"100\"), Some(100), \"input \\\"100\\\"\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// Turns one typed line into a guess from 1 to 100, or None if it is not one.\npub fn parse_guess(line: &str) -> Option<u32> {\n    match line.trim().parse::<u32>() {\n        Ok(n) => {\n            if n >= 1 && n <= 100 {\n                Some(n)\n            } else {\n                None\n            }\n        }\n        Err(_) => None,\n    }\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "exercise", "id": "ch02-ex-play", "exercise_dir": "ch02-play-game", "title": "The whole game, as a function", "difficulty": "medium", "goal": "Combine the two previous exercises into the complete game: given the secret and the lines the player typed, produce exactly what the game prints.", "behavior": "`pub fn play(secret: u32, lines: &[&str]) -> Vec<String>` goes through `lines` in order and builds the list of messages the game would print:\n\n- For a line that is not a valid guess (use the rules of `parse_guess`): add `\"Please type a number!\"` and go on to the next line.\n- For a valid guess `n`: add `\"You guessed: n\"`, then the verdict (`\"Too small!\"`, `\"Too big!\"` or `\"You win!\"`).\n- After `\"You win!\"`, stop: later lines are ignored.\n- If the lines run out before a win, just return what you have.\n\n`&[&str]` is a list of text lines, and `Vec<String>` is a growable list of Strings. The starter already creates the list and returns it; you only add to it with `output.push(...)`. `format!` works like `println!` but gives back a String instead of printing it.\n", "examples": [{"input": "play(61, &[\"10\", \"80\", \"61\"])", "output": "[\"You guessed: 10\", \"Too small!\", \"You guessed: 80\", \"Too big!\", \"You guessed: 61\", \"You win!\"]"}, {"input": "play(5, &[\"x\", \"5\", \"9\"])", "output": "[\"Please type a number!\", \"You guessed: 5\", \"You win!\"]"}], "hints": ["Copy your `verdict` and `parse_guess` functions into this file. Splitting work into functions you already trust is half the job.", "`for line in lines { ... }` visits every line. Use `match parse_guess(line) { Some(n) => ..., None => ... }`.", "`output.push(format!(\"You guessed: {n}\"));` and `output.push(verdict(n, secret).to_string());` (`to_string` turns fixed text into a String).", "After pushing the verdict, `if n == secret { break; }`."], "solution_explain": "The solution reuses the two earlier functions. `parse_guess` uses a **match guard** (`Ok(n) if ...`), a pattern with an extra condition, which chapter 19 covers; the `if` version from the previous exercise works just as well.", "mode": "tests", "dir": "ch02-play-game", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// Plays a whole game with the given secret and typed lines,\n/// returning every message the game prints, in order.\npub fn play(secret: u32, lines: &[&str]) -> Vec<String> {\n    let mut output = Vec::new();\n    for line in lines {\n        // TODO: handle one typed line.\n        // Add messages with output.push(String::from(\"...\")) or output.push(format!(...)).\n        let _ = (line, secret);\n    }\n    output\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch02_play_game\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\nfn strings(v: &[&str]) -> Vec<String> {\n    v.iter().map(|s| s.to_string()).collect()\n}\n\n#[test]\nfn three_guesses_until_a_win() {\n    assert_eq!(\n        play(61, &[\"10\", \"80\", \"61\"]),\n        strings(&[\"You guessed: 10\", \"Too small!\", \"You guessed: 80\", \"Too big!\", \"You guessed: 61\", \"You win!\"]),\n    );\n}\n\n#[test]\nfn bad_input_gets_a_second_chance() {\n    assert_eq!(\n        play(5, &[\"x\", \"5\", \"9\"]),\n        strings(&[\"Please type a number!\", \"You guessed: 5\", \"You win!\"]),\n    );\n}\n\n#[test]\nfn lines_after_the_win_are_ignored() {\n    assert_eq!(play(3, &[\"3\", \"4\", \"5\"]), strings(&[\"You guessed: 3\", \"You win!\"]));\n}\n\n#[test]\nfn running_out_of_lines_without_winning() {\n    assert_eq!(\n        play(50, &[\"20\\n\", \"\", \"200\"]),\n        strings(&[\"You guessed: 20\", \"Too small!\", \"Please type a number!\", \"Please type a number!\"]),\n    );\n}\n\n#[test]\nfn no_lines_no_messages() {\n    assert_eq!(play(50, &[]), Vec::<String>::new());\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "use std::cmp::Ordering;\n\nfn verdict(guess: u32, secret: u32) -> &'static str {\n    match guess.cmp(&secret) {\n        Ordering::Less => \"Too small!\",\n        Ordering::Greater => \"Too big!\",\n        Ordering::Equal => \"You win!\",\n    }\n}\n\nfn parse_guess(line: &str) -> Option<u32> {\n    match line.trim().parse::<u32>() {\n        Ok(n) if (1..=100).contains(&n) => Some(n),\n        _ => None,\n    }\n}\n\n/// Plays a whole game with the given secret and typed lines,\n/// returning every message the game prints, in order.\npub fn play(secret: u32, lines: &[&str]) -> Vec<String> {\n    let mut output = Vec::new();\n    for line in lines {\n        match parse_guess(line) {\n            None => output.push(String::from(\"Please type a number!\")),\n            Some(n) => {\n                output.push(format!(\"You guessed: {n}\"));\n                output.push(verdict(n, secret).to_string());\n                if n == secret {\n                    break;\n                }\n            }\n        }\n    }\n    output\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "text", "title": "Bonus: reading command-line arguments", "md": "*Programming Rust* ends its first program by reading numbers from the **command line**, the words typed after the program's name. `std::env::args()` gives them as Strings; the first one is the program's own name, so `.skip(1)` drops it. You will build a full command-line tool in chapter 12.\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "use std::env;\n\nfn main() {\n    let mut total: u64 = 0;\n    for arg in env::args().skip(1) {\n        let n: u64 = arg.parse().expect(\"each argument must be a number\");\n        total += n;\n    }\n    println!(\"Sum: {total}\");\n}\n", "output": "$ cargo run -- 4 8 15\nSum: 27\n", "explain": "`cargo run -- 4 8 15`: everything after `--` is passed to your program instead of to Cargo."}, {"type": "quiz", "id": "ch02-quiz-loop", "title": "Check yourself", "questions": [{"type": "single", "q": "What does `continue` do inside a `loop`?", "options": ["Ends the loop for good", "Skips the rest of this round and starts the next one", "Ends the whole program", "Repeats the current line"], "answer": 1, "explanation": "`continue` jumps to the start of the next round; `break` leaves the loop.", "hints": []}, {"type": "single", "q": "In `Err(_) => continue`, what does `_` mean?", "options": ["The error is printed", "Match any error, without giving it a name", "Only match empty input", "The arm is optional"], "answer": 1, "explanation": "`_` is a catch-all pattern that ignores the value.", "hints": []}, {"type": "truefalse", "q": "Without a `break`, a `loop` runs until the program is stopped from outside.", "answer": true, "explanation": "`loop` repeats forever by design (or until a `break`, a `return`, or a panic).", "hints": []}, {"type": "single", "q": "The player types `abc`. Which version of the game keeps running?", "options": ["`let guess: u32 = guess.trim().parse().expect(\"Please type a number!\");`", "`let guess: u32 = match guess.trim().parse() { Ok(num) => num, Err(_) => continue };`", "Both", "Neither"], "answer": 1, "explanation": "`expect` panics on `Err`, ending the program. The `match` version continues the loop.", "hints": []}, {"type": "single", "q": "What is printed?", "code": "let mut n = 0;\nloop {\n    n += 1;\n    if n == 3 {\n        break;\n    }\n}\nprintln!(\"{n}\");\n", "lang": "rust", "options": ["0", "2", "3", "It never stops"], "answer": 2, "explanation": "`n` goes 1, 2, 3; at 3 the loop breaks and 3 is printed.", "hints": []}, {"type": "fill", "q": "Which macro is like `println!` but returns a String instead of printing?", "answer": ["format!", "format"], "explanation": "`format!(\"You guessed: {n}\")` builds the String.", "hints": []}]}, {"type": "summary", "points": ["`loop { ... }` repeats forever; `break` leaves it, `continue` starts the next round.", "A `match` arm can run several statements inside `{ }`.", "`match value.parse() { Ok(num) => num, Err(_) => continue }` handles bad input instead of panicking.", "`Ok(num)` binds the inner value to `num`; `_` matches anything and ignores it.", "Logic in small functions that return values can be checked with unit tests (`#[test]`, `assert_eq!`, `cargo test`).", "`std::env::args()` gives the command-line arguments as Strings."]}], "terms": [{"term": "loop", "def": "Repeats its block forever, until `break` (or `return`) leaves it."}, {"term": "break", "def": "Ends the innermost loop immediately."}, {"term": "continue", "def": "Skips the rest of the current round of a loop and starts the next one."}, {"term": "unit test", "def": "A small function marked `#[test]` that calls your code and checks the result; `cargo test` runs them all."}, {"term": "Option", "def": "A value that is either `Some(value)` or `None`: Rust's way of saying 'there may be no value' without null."}, {"term": "Vec", "def": "A growable list of values of one type, like `Vec<String>`."}], "id": "ch02-03-loop-quit", "chapter": "ch02", "kind": "lesson"}, "ch02-99-test": {"title": "Chapter test: the Guessing Game", "kind": "test", "summary": "Ten questions on input, crates, match, loops and error handling. You need 70% to pass; you can retry and your best score is kept.", "blocks": [{"type": "quiz", "id": "ch02-test", "pass_score": 0.7, "questions": [{"type": "single", "q": "Which line reads a line from the keyboard into `guess`?", "options": ["`let guess = io::stdin();`", "`io::stdin().read_line(&mut guess).expect(\"Failed to read line\");`", "`guess = read_line();`", "`println!(\"{guess}\");`"], "answer": 1, "explanation": "`read_line` needs a mutable reference to the String it fills, and returns a Result that `expect` unwraps.", "hints": []}, {"type": "single", "q": "Why does this fail to compile?", "code": "let guess = String::new();\nio::stdin().read_line(&mut guess).expect(\"read failed\");\n", "lang": "rust", "options": ["`String::new` needs an argument", "`guess` is not declared `mut`", "`expect` needs a number", "`io` was not imported"], "answer": 1, "hints": ["What does `&mut` require from the variable?"], "explanation": "You cannot borrow an immutable variable as mutable. `let mut guess` fixes it."}, {"type": "numeric", "q": "`random_range(1..10)` can return how many different numbers?", "answer": 9, "explanation": "`..` excludes the end: 1 through 9, nine numbers. `1..=10` would give ten.", "hints": []}, {"type": "single", "q": "A colleague clones your project and builds it. What makes sure they get the same `rand` version as you?", "options": ["`Cargo.toml`", "`Cargo.lock`", "`cargo update`", "The `target/` folder"], "answer": 1, "explanation": "`Cargo.lock` records exact versions. `cargo update` would change them.", "hints": []}, {"type": "truefalse", "q": "A `match` on an `Ordering` that only handles `Less` and `Greater` compiles, and does nothing when the values are equal.", "answer": false, "explanation": "`match` must be exhaustive; the compiler reports `Equal` not covered.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "let typed = \" 12\\n\";\nlet n: u32 = typed.trim().parse().expect(\"number\");\nlet n = n * 2;\nprintln!(\"{n}\");\n", "lang": "rust", "options": ["12", "24", "It does not compile: `n` is not `mut`", "It panics"], "answer": 1, "hints": ["Is the third line changing `n`, or making a new `n`?"], "explanation": "The third line **shadows** `n` with a new variable, so no `mut` is needed. 12 × 2 = 24."}, {"type": "multi", "q": "Which inputs make `\"...\".trim().parse::<u32>()` return `Err`?", "options": ["`\"7\"`", "`\"-7\"`", "`\"seven\"`", "`\" 7 \"`", "`\"\"`"], "answer": [1, 2, 4], "explanation": "`u32` has no negative numbers, `seven` is not digits, and an empty string is not a number. `\" 7 \"` is trimmed first, so it parses.", "hints": []}, {"type": "order", "q": "Order the pieces of one round of the finished game.", "items": ["Print `Please input your guess.`", "Read a line into a new String", "Parse it; on `Err`, `continue`", "Print `You guessed: ...`", "Compare with `cmp`; on `Equal`, print `You win!` and `break`"], "explanation": "That is the body of the `loop` in the finished program.", "hints": []}, {"type": "fill", "q": "The keyword that ends a `loop` immediately is ______.", "answer": ["break"], "explanation": "`break` leaves the loop; `continue` only skips to the next round.", "hints": []}, {"type": "single", "q": "Which statement about `expect` is true?", "options": ["It turns any error into the number 0", "It returns the value inside `Ok`, or panics with your message on `Err`", "It retries the operation until it succeeds", "It is required on every function call"], "answer": 1, "explanation": "`expect` is the quick way to say 'this should not fail; if it does, stop with this message'.", "hints": []}], "mode": "test"}], "id": "ch02-99-test", "chapter": "ch02", "minutes": 10}, "ch03-01-variables": {"title": "Variables, constants and shadowing", "summary": "Why Rust makes variables immutable by default, when to use mut, constants or shadowing, and how they differ.", "minutes": 18, "source": {"chapter": "ch03", "sections": ["TRPL 3.1 Variables and Mutability", "TRPL 3.1 Constants", "TRPL 3.1 Shadowing", "CR Variables", "CR Type Inference"]}, "blocks": [{"type": "text", "md": "You already met `let` and `let mut` in the guessing game. This lesson explains *why* Rust works this way and adds two relatives: **constants** and **shadowing**. Knowing which of the four to reach for is one of the first habits of a Rust programmer.\n"}, {"type": "text", "title": "Immutable by default", "md": "A variable made with `let` cannot be changed after it gets its value. Try to assign to it again and the program does not compile:\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "fn main() {\n    let x = 5;\n    println!(\"The value of x is: {x}\");\n    x = 6;\n    println!(\"The value of x is: {x}\");\n}\n", "output": "error[E0384]: cannot assign twice to immutable variable `x`\n --> src/main.rs:4:5\n  |\n2 |     let x = 5;\n  |         - first assignment to `x`\n3 |     println!(\"The value of x is: {x}\");\n4 |     x = 6;\n  |     ^^^^^ cannot assign twice to immutable variable\n  |\nhelp: consider making this binding mutable\n  |\n2 |     let mut x = 5;\n  |         +++\n", "output_label": "Compiler output", "explain": "Why would a language forbid this? Picture a large program where one part relies on a value staying the same and another part quietly changes it. That kind of bug is hard to track down because the change happens far away from where things go wrong. When a value is immutable, you *know* it never changes; the compiler guarantees it. When you need change, you say so with `mut`, which also tells the next reader *this value will change*.\n"}, {"type": "callout", "kind": "analogy", "title": "Ink and pencil", "md": "Think of `let` as writing in ink and `let mut` as writing in pencil. Most notes are fine in ink. You choose pencil only for the things you plan to erase, and anyone reading your page can see which is which."}, {"type": "text", "title": "Constants", "md": "A **constant** is a name for a value that never changes, written with `const`:\n"}, {"type": "code", "lang": "rust", "code": "const THREE_HOURS_IN_SECONDS: u32 = 60 * 60 * 3;\n", "explain": "Constants differ from immutable variables in four ways:\n\n- They are always immutable; `mut` is not allowed.\n- Their **type must be written** (`: u32`); Rust does not infer it.\n- They can be declared anywhere, including outside every function, so the whole file can use them.\n- Their value must be computable **at compile time**. `60 * 60 * 3` is fine; a value read from the keyboard is not.\n\nBy convention constants are written in `UPPER_SNAKE_CASE`. Naming a value like `MAX_POINTS` or `THREE_HOURS_IN_SECONDS` documents what it means, and if it ever changes you edit one line.\n"}, {"type": "text", "title": "Shadowing", "md": "You saw shadowing in the guessing game: a new `let` with the same name creates a **new variable** that hides the old one. Shadowing also respects **scope**: the region of code, usually a block in `{ }`, where a name is valid. Step through this program and predict each value before reading the next step.\n"}, {"type": "stepper", "title": "Shadowing, step by step", "lang": "rust", "steps": [{"title": "x is 5", "md": "The first `x` is bound to 5.", "code": "fn main() {\n    let x = 5;\n}\n", "highlight": [2]}, {"title": "A new x, equal to 6", "md": "`let x = x + 1;` reads the old `x` (5), adds 1, and binds the result to a **new** variable also called `x`. The old one is now hidden.", "code": "fn main() {\n    let x = 5;\n    let x = x + 1;\n}\n", "highlight": [3]}, {"title": "Inside the block, x is 12", "md": "The curly brackets start an inner scope. Inside it, yet another `x` shadows the outer one: 6 × 2 = 12.", "code": "fn main() {\n    let x = 5;\n    let x = x + 1;\n    {\n        let x = x * 2;\n        println!(\"The value of x in the inner scope is: {x}\");\n    }\n}\n", "highlight": [5, 6], "output": "The value of x in the inner scope is: 12"}, {"title": "After the block, x is 6 again", "md": "When the inner scope ends, its `x` disappears and the outer `x` (6) is visible again. Nothing was overwritten; each `x` was a separate variable.", "code": "fn main() {\n    let x = 5;\n    let x = x + 1;\n    {\n        let x = x * 2;\n        println!(\"The value of x in the inner scope is: {x}\");\n    }\n    println!(\"The value of x is: {x}\");\n}\n", "highlight": [8], "output": "The value of x in the inner scope is: 12\nThe value of x is: 6\n"}]}, {"type": "table", "title": "Shadowing versus mut", "headers": ["", "`let mut x`", "shadowing (`let x` again)"], "rows": [["Changes the existing variable?", "Yes", "No, makes a new one"], ["Can change the type?", "No", "Yes"], ["Result after the change", "Mutable", "Immutable again (unless the new `let` says `mut`)"], ["Typical use", "A counter, a String you append to", "Converting a value: text to number, raw to cleaned"]]}, {"type": "code", "lang": "rust", "title": "Shadowing can change the type; mut cannot", "code": "let spaces = \"   \";        // text\nlet spaces = spaces.len();  // now a number: 3   (fine)\n\nlet mut letters = \"   \";\nletters = letters.len();    // error[E0308]: mismatched types\n", "highlight": [2, 5]}, {"type": "callout", "kind": "note", "title": "Type inference", "md": "In `let x = 5;` you did not write a type, yet `x` has one: `i32`. Rust **infers** types from how values are used, and checks them at compile time. You write types where the compiler cannot work them out (like `parse`), at function boundaries (next lessons), and wherever it makes the code clearer.\n"}, {"type": "playground", "id": "ch03-play-shadow", "title": "Predict, then run", "lang": "rust", "md": "Write down the four numbers you expect this to print. Then run it and compare.", "code": "fn main() {\n    let a = 2;\n    let a = a * 10;\n    let mut b = a;\n    {\n        let a = 7;\n        b += a;\n        println!(\"{a} {b}\");\n    }\n    println!(\"{a} {b}\");\n}\n", "hints": ["Inside the block, `a` is 7, and `b` started at 20.", "After the block, the outer `a` (20) is back, but `b` was *changed*, not shadowed, so it keeps 27."]}, {"type": "playground", "id": "ch03-play-const", "title": "Name the magic number", "lang": "rust", "task": "Add two constants above `main`, `SECONDS_PER_MINUTE` and `MINUTES_PER_HOUR` (both `u32`, both 60). Use them instead of the bare `60`, then add a second line that prints the seconds in 2 hours: `2 hours = 7200 seconds`.", "code": "fn main() {\n    let minutes: u32 = 5;\n    let seconds = minutes * 60;\n    println!(\"{minutes} minutes = {seconds} seconds\");\n}\n", "expected_output": "5 minutes = 300 seconds\n2 hours = 7200 seconds\n", "hints": ["`const SECONDS_PER_MINUTE: u32 = 60;` goes on its own line above `fn main()`.", "Seconds in an hour are `MINUTES_PER_HOUR * SECONDS_PER_MINUTE`. A second `let seconds` can shadow the first.", "The point is readability: `hours * MINUTES_PER_HOUR * SECONDS_PER_MINUTE` says what `2 * 60 * 60` only implies."]}, {"type": "quiz", "id": "ch03-quiz-variables", "title": "Check yourself", "questions": [{"type": "multi", "q": "Which are true about `const`?", "options": ["The type must be written", "It can be declared outside any function", "It can be made mutable with `mut`", "Its value can come from user input", "By convention it is written in UPPER_SNAKE_CASE"], "answer": [0, 1, 4], "explanation": "Constants are always immutable, need a type, can live at the top of a file, and must be computable at compile time.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "let x = 1;\n{\n    let x = x + 1;\n    let x = x * 10;\n}\nprintln!(\"{x}\");\n", "lang": "rust", "options": ["1", "2", "20", "It does not compile"], "answer": 0, "explanation": "Both inner `x` variables disappear at the end of the block. The outer `x` is still 1.", "hints": []}, {"type": "single", "q": "Which compiles?", "options": ["`let mut n = \"5\"; n = n.len();`", "`let n = \"5\"; let n = n.len();`", "`const N = 5;`", "`let n = 5; n += 1;`"], "answer": 1, "explanation": "Shadowing may change the type. `mut` may not; a `const` needs a type; and `n += 1` needs `mut`.", "hints": []}, {"type": "truefalse", "q": "Making variables immutable by default helps because the compiler guarantees a value you rely on is not changed elsewhere.", "answer": true, "explanation": "That is exactly the bug class it removes.", "hints": []}]}, {"type": "summary", "points": ["`let` variables are immutable; add `mut` only when the value must change.", "`const NAME: Type = value;` declares a compile-time constant; type required, UPPER_SNAKE_CASE, can be global.", "Shadowing (`let x = ...` again) creates a new variable; it can change the type, and it ends with its scope.", "A scope is a block in `{ }`; names declared inside vanish at its end.", "Rust infers most types and checks all of them at compile time."]}], "terms": [{"term": "immutable", "def": "Cannot be changed after it is given a value. Rust variables are immutable unless declared with `mut`."}, {"term": "constant", "def": "A named value fixed at compile time, declared with `const` and an explicit type."}, {"term": "scope", "def": "The part of the program, usually a `{ }` block, in which a name is valid."}, {"term": "type inference", "def": "The compiler working out a variable's type from how it is used, so you need not write it."}], "id": "ch03-01-variables", "chapter": "ch03", "kind": "lesson"}, "ch03-02-scalar-types": {"title": "Numbers, booleans and characters", "summary": "Rust's scalar types: integers of every size, what overflow does, floating-point numbers, arithmetic, bool and char.", "minutes": 28, "source": {"chapter": "ch03", "sections": ["TRPL 3.2 Data Types", "TRPL 3.2 Scalar Types", "TRPL 3.2 Integer Overflow", "PR ch3 Fixed-Width Numeric Types", "PR ch3 Checked, Wrapping, Saturating, and Overflowing Arithmetic", "PR ch3 Floating-Point Types", "PR ch3 The bool Type", "PR ch3 Characters", "RiA 2.3 Numbers"]}, "blocks": [{"type": "text", "md": "Every value in Rust has a **data type**, and the compiler must know every type before the program runs. A **scalar** type holds a single value. Rust has four kinds: **integers**, **floating-point numbers**, **booleans** and **characters**. This lesson is a tour of them, with the details that trip people up: sizes, overflow and conversions.\n"}, {"type": "text", "title": "Integers", "md": "An integer is a whole number. Rust's integer types say two things in their name: whether they can be negative (**i** for *signed*, **u** for *unsigned*) and how many bits they use. More bits means a bigger range, and more memory.\n"}, {"type": "table", "title": "Integer types", "headers": ["Bits", "Signed", "Unsigned", "Unsigned range"], "rows": [["8", "`i8` (−128 to 127)", "`u8`", "0 to 255"], ["16", "`i16`", "`u16`", "0 to 65,535"], ["32", "`i32` (the default)", "`u32`", "0 to about 4.29 billion"], ["64", "`i64`", "`u64`", "0 to about 1.8 × 10¹⁹"], ["128", "`i128`", "`u128`", "0 to about 3.4 × 10³⁸"], ["pointer size", "`isize`", "`usize`", "depends on the machine (64 bits on most computers)"]]}, {"type": "callout", "kind": "key", "title": "Which one should I use?", "md": "- Not sure? Use `i32`, the default. It is fast everywhere.\n- Counting things in memory, or indexing a list? Use `usize`. Rust requires `usize` for indexes, because the size of memory depends on the machine.\n- Raw bytes (files, network)? `u8`.\n- Something specific: pick the smallest type whose range surely fits, like `u16` for a port number.\n"}, {"type": "code", "lang": "rust", "title": "Ways to write integer literals", "code": "let million = 1_000_000;   // underscores are just for reading\nlet hex = 0xff;            // 255\nlet octal = 0o77;          // 63\nlet binary = 0b1111_0000;  // 240\nlet byte = b'A';           // 65: a u8, only for ASCII characters\nlet small = 42u8;          // the suffix sets the type\nprintln!(\"{million} {hex} {octal} {binary} {byte} {small}\");\n", "output": "1000000 255 63 240 65 42"}, {"type": "text", "title": "Overflow", "md": "A `u8` holds 0 to 255. What if a calculation produces 256? That is **integer overflow**, and Rust's answer depends on how you build:\n\n- In a **debug** build (`cargo run`, `cargo build`), Rust checks every arithmetic operation and **panics** on overflow. Your bug is reported where it happens.\n- In a **release** build (`--release`), the checks are removed for speed and the value **wraps around**: 256 becomes 0, 257 becomes 1, and so on, the way a car's odometer rolls over.\n\nRelying on wrapping by accident is considered a bug. When you *want* a specific behavior, ask for it explicitly with one of four method families:\n"}, {"type": "table", "title": "Choosing what happens on overflow (shown for u8, 250 + 10)", "headers": ["Method", "Result", "Use it when"], "rows": [["`250u8.checked_add(10)`", "`None` (`Some(x)` if no overflow)", "Overflow means invalid input you want to handle"], ["`250u8.wrapping_add(10)`", "`4` (260 − 256)", "You really want modular arithmetic: hashes, checksums"], ["`250u8.saturating_add(10)`", "`255` (stops at the limit)", "Values that should stick at the edge: volume, health points"], ["`250u8.overflowing_add(10)`", "`(4, true)`", "You want the wrapped value and to know it wrapped"]]}, {"type": "playground", "id": "ch03-play-overflow", "title": "Watch overflow happen", "lang": "rust", "md": "`parse` here stops the compiler from noticing the overflow in advance, as it would with a plain `255u8 + 1`. Run it: the debug build panics with `attempt to add with overflow`. Then replace `level + 1` with `level.saturating_add(1)`, and after that with `level.wrapping_add(1)`, and compare.\n", "code": "fn main() {\n    let level: u8 = \"255\".parse().unwrap(); // `unwrap` is like `expect` without a message\n    println!(\"level is {level}\");\n    let next = level + 1;\n    println!(\"next level is {next}\");\n}\n", "expect_panic": true, "hints": ["`saturating_add(1)` gives 255; `wrapping_add(1)` gives 0."]}, {"type": "text", "title": "Floating-point numbers", "md": "Numbers with a decimal point are **floating-point** numbers: `f64` (the default, about 15 to 17 significant digits) and `f32` (about 7). They follow the IEEE-754 standard like almost every language, which brings two surprises worth knowing early:\n\n- Many decimal fractions cannot be stored exactly. `0.1 + 0.2` is `0.30000000000000004`, not `0.3`. Compare floats with a small tolerance instead of `==`.\n- Some operations produce special values: `1.0 / 0.0` is infinity, and `0.0 / 0.0` is `NaN` (\"not a number\"), which is not even equal to itself.\n"}, {"type": "code", "lang": "rust", "title": "Arithmetic", "code": "fn main() {\n    let sum = 5 + 10;          // 15\n    let difference = 95.5 - 4.3; // 91.2\n    let product = 4 * 30;      // 120\n    let quotient = 56.7 / 32.2; // 1.7608695652173911\n    let truncated = -5 / 3;    // -1: integer division drops the fraction\n    let remainder = 43 % 5;    // 3\n    println!(\"{sum} {difference} {product} {quotient} {truncated} {remainder}\");\n}\n", "output": "15 91.2 120 1.7608695652173911 -1 3", "explain": "Integer division rounds toward zero. Both sides of an operator must have the same type: `5 + 2.5` does not compile, because Rust never converts between number types silently."}, {"type": "text", "title": "Converting between number types", "md": "To mix types you convert explicitly. `as` converts between number types, `From`/`into` converts only when no value can be lost, and `try_into` converts when it *might* fail and tells you if it did:\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let small: u8 = 200;\n    let wide: u32 = small.into();      // always fits: u8 -> u32\n    let f = small as f64 / 3.0;         // `as` converts to f64\n    let truncated = 3.99_f64 as i32;    // 3: `as` drops the fraction\n    let squeezed = 300_i32 as u8;       // 44: `as` silently keeps the low 8 bits!\n    let checked: Result<u8, _> = 300_i32.try_into(); // Err: does not fit\n    println!(\"{wide} {f:.2} {truncated} {squeezed} {checked:?}\");\n}\n", "output": "200 66.67 3 44 Err(TryFromIntError(PosOverflow))", "explain": "`{f:.2}` prints with two decimals. Prefer `into` and `try_into`; `as` is handy but quietly loses information when the value does not fit."}, {"type": "text", "title": "Booleans and characters", "md": "`bool` has two values, `true` and `false`, and takes one byte. Conditions in `if` and `while` must be `bool`: unlike C or Python, Rust does not treat `0` or an empty string as false.\n\n`char` is a single **Unicode scalar value**, written in single quotes: `'z'`, `'ß'`, `'😻'`. A `char` is always 4 bytes, so it can hold any character in any script. Text in double quotes is a string, not a `char`; strings are UTF-8 and use 1 to 4 bytes per character (chapter 8).\n"}, {"type": "playground", "id": "ch03-play-chars", "title": "Characters are not bytes", "lang": "rust", "md": "Run it. Each `char` is 4 bytes, but in a UTF-8 string the same characters take 1, 2 and 4 bytes. `as u32` shows each character's Unicode number.", "code": "fn main() {\n    for c in ['a', 'ß', '😻'] {\n        println!(\"{c}: code point {}, {} byte(s) in UTF-8\", c as u32, c.len_utf8());\n    }\n    println!(\"size of a char: {} bytes\", std::mem::size_of::<char>());\n    println!(\"\\\"aß😻\\\" is {} bytes long\", \"aß😻\".len());\n}\n", "hints": []}, {"type": "exercise", "id": "ch03-ex-overflow", "exercise_dir": "ch03-safe-arithmetic", "title": "Arithmetic that cannot go wrong", "difficulty": "easy", "goal": "Write three small functions that each handle overflow in a different, deliberate way.", "behavior": "- `pub fn add_checked(a: u8, b: u8) -> Option<u8>`: `Some(sum)` when the sum fits in a `u8`, `None` otherwise.\n- `pub fn volume_up(level: u8, step: u8) -> u8`: increases the volume but never goes above 255.\n- `pub fn odometer(km: u16, driven: u16) -> u16`: like a car's odometer, rolls over past 65,535 back to 0 and keeps counting.\n", "examples": [{"input": "add_checked(200, 55)", "output": "Some(255)"}, {"input": "add_checked(200, 56)", "output": "None"}, {"input": "volume_up(250, 10)", "output": "255"}, {"input": "odometer(65_530, 10)", "output": "4"}], "hints": ["Each function is one line: the right method from the table in this lesson.", "`a.checked_add(b)`, `level.saturating_add(step)`, `km.wrapping_add(driven)`."], "solution_explain": "Saying which overflow behavior you want makes the code correct in both debug and release builds, and tells the reader it was intended.", "mode": "tests", "dir": "ch03-safe-arithmetic", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// The sum, or None if it does not fit in a u8.\npub fn add_checked(a: u8, b: u8) -> Option<u8> {\n    todo!()\n}\n\n/// Turns the volume up by `step`, stopping at 255.\npub fn volume_up(level: u8, step: u8) -> u8 {\n    todo!()\n}\n\n/// Adds `driven` kilometres, rolling over past 65,535 like a car odometer.\npub fn odometer(km: u16, driven: u16) -> u16 {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch03_safe_arithmetic\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn checked_add_fits() {\n    assert_eq!(add_checked(200, 55), Some(255), \"200 + 55\");\n    assert_eq!(add_checked(0, 0), Some(0), \"0 + 0\");\n}\n\n#[test]\nfn checked_add_overflows() {\n    assert_eq!(add_checked(200, 56), None, \"200 + 56 is 256, too big for u8\");\n    assert_eq!(add_checked(255, 255), None, \"255 + 255\");\n}\n\n#[test]\nfn volume_stops_at_255() {\n    assert_eq!(volume_up(250, 10), 255, \"volume_up(250, 10)\");\n    assert_eq!(volume_up(10, 5), 15, \"volume_up(10, 5)\");\n    assert_eq!(volume_up(255, 1), 255, \"volume_up(255, 1)\");\n}\n\n#[test]\nfn odometer_rolls_over() {\n    assert_eq!(odometer(65_530, 10), 4, \"odometer(65_530, 10)\");\n    assert_eq!(odometer(100, 23), 123, \"odometer(100, 23)\");\n    assert_eq!(odometer(65_535, 1), 0, \"odometer(65_535, 1)\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// The sum, or None if it does not fit in a u8.\npub fn add_checked(a: u8, b: u8) -> Option<u8> {\n    a.checked_add(b)\n}\n\n/// Turns the volume up by `step`, stopping at 255.\npub fn volume_up(level: u8, step: u8) -> u8 {\n    level.saturating_add(step)\n}\n\n/// Adds `driven` kilometres, rolling over past 65,535 like a car odometer.\npub fn odometer(km: u16, driven: u16) -> u16 {\n    km.wrapping_add(driven)\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch03-quiz-scalars", "title": "Check yourself", "questions": [{"type": "single", "q": "Which type must you use to index into an array or a Vec?", "options": ["`i32`", "`u32`", "`usize`", "Any integer type"], "answer": 2, "explanation": "Indexes are `usize`, whose size matches the machine's memory addresses.", "hints": []}, {"type": "single", "q": "`let x: u8 = 255;` then, at run time, `x + 1` in a **debug** build. What happens?", "options": ["The result is 256", "The result wraps to 0", "The program panics", "The result stays 255"], "answer": 2, "explanation": "Debug builds check for overflow and panic. Release builds wrap to 0.", "hints": []}, {"type": "numeric", "q": "What is `-7 / 2` in Rust (integers)?", "answer": -3, "explanation": "Integer division rounds toward zero: −3.5 becomes −3.", "hints": []}, {"type": "single", "q": "What does `300_i32 as u8` give?", "options": ["255", "44", "A compile error", "A panic"], "answer": 1, "explanation": "`as` keeps the low 8 bits: 300 − 256 = 44, silently. That is why `try_into` exists.", "hints": []}, {"type": "multi", "q": "Which compile?", "options": ["`let a = 5 + 2.5;`", "`let b = 5.0 + 2.5;`", "`let c = 5 as f64 + 2.5;`", "`if 1 { }`", "`let d: char = 'é';`"], "answer": [1, 2, 4], "explanation": "Mixed `i32 + f64` and an integer used as a condition do not compile.", "hints": []}, {"type": "truefalse", "q": "`0.1 + 0.2 == 0.3` is `true` in Rust.", "answer": false, "explanation": "As in most languages, the sum is 0.30000000000000004. Compare floats with a tolerance.", "hints": []}]}, {"type": "summary", "points": ["Integers: `i8`–`i128` (signed), `u8`–`u128` (unsigned), plus `isize`/`usize`; `i32` is the default, `usize` is for indexes.", "Overflow panics in debug builds and wraps in release; use `checked_`, `wrapping_`, `saturating_` or `overflowing_` methods to choose.", "`f64` is the default float; floats are approximate, so avoid `==` on them.", "Rust never mixes number types silently: convert with `into` (lossless), `try_into` (may fail) or `as` (may truncate).", "`bool` is `true`/`false` and conditions must be `bool`; `char` is a 4-byte Unicode scalar value in single quotes."]}], "terms": [{"term": "scalar type", "def": "A type holding a single value: an integer, a float, a bool or a char."}, {"term": "integer overflow", "def": "A result outside the type's range. Debug builds panic; release builds wrap around unless you choose otherwise."}, {"term": "usize", "def": "The unsigned integer type as wide as a memory address; used for sizes and indexes."}, {"term": "char", "def": "One Unicode scalar value, 4 bytes, written in single quotes like 'a'."}], "id": "ch03-02-scalar-types", "chapter": "ch03", "kind": "lesson"}, "ch03-03-compound-types": {"title": "Tuples and arrays", "summary": "Group several values into one: tuples hold values of different types, arrays hold a fixed number of values of one type.", "minutes": 22, "source": {"chapter": "ch03", "sections": ["TRPL 3.2 Compound Types", "TRPL 3.2 The Tuple Type", "TRPL 3.2 The Array Type", "PR ch3 Tuples", "PR ch3 Arrays", "CR Tuples and Arrays"]}, "blocks": [{"type": "text", "md": "Scalars hold one value. **Compound types** hold several. Rust has two built in: the **tuple**, a small group of values that can have different types, and the **array**, a fixed-length row of values that all have the same type. Both have a size known when the program is compiled, so they live directly on the stack and cost nothing extra to create.\n"}, {"type": "text", "title": "Tuples", "md": "A tuple is written as values in parentheses, separated by commas. Its type is the list of its element types. Use one to keep together values that belong together but are not the same kind of thing: a name and an age, a coordinate, or a function's two results.\n"}, {"type": "code", "lang": "rust", "title": "Making a tuple and reading it back", "code": "fn main() {\n    let person: (&str, u32, f64) = (\"Ada\", 36, 1.65);\n\n    // 1. destructuring: one name per element\n    let (name, age, height) = person;\n    println!(\"{name} is {age}, {height} m tall\");\n\n    // 2. by position, starting at 0\n    println!(\"first: {}, last: {}\", person.0, person.2);\n}\n", "output": "Ada is 36, 1.65 m tall\nfirst: Ada, last: 1.65\n", "explain": "`let (name, age, height) = person;` is a **pattern**: it splits the tuple into three variables in one step. `person.0` reaches in by position. Positions are fixed when you compile, so `person.3` is a compile error, not a crash."}, {"type": "callout", "kind": "note", "title": "The empty tuple ()", "md": "A tuple with no elements, `()`, is called **unit**. It means \"no meaningful value\". A function that returns nothing, like `main`, actually returns `()`, and you will see `()` in compiler messages often."}, {"type": "playground", "id": "ch03-play-tuple", "title": "Return two results at once", "lang": "rust", "md": "`divide` should return both the quotient and the remainder as a tuple. Fill in the return value (use `/` and `%`), then destructure the result in `main` so it prints `17 / 5 = 3 remainder 2`.\n", "code": "fn divide(a: u32, b: u32) -> (u32, u32) {\n    (0, 0) // replace with the quotient and the remainder\n}\n\nfn main() {\n    let result = divide(17, 5);\n    println!(\"17 / 5 = {} remainder {}\", result.0, result.1);\n}\n", "expected_output": "17 / 5 = 3 remainder 2", "hints": ["The tuple is `(a / b, a % b)`.", "In `main`: `let (q, r) = divide(17, 5);` then print `{q}` and `{r}`."]}, {"type": "text", "title": "Arrays", "md": "An array holds a **fixed number** of values of **one type**. The type is written `[T; N]`: the element type and the length. The length is part of the type, so `[i32; 3]` and `[i32; 4]` are different types, and an array can never grow or shrink. When you need a list that grows, you will use `Vec` (chapter 8), which is the more common choice in everyday code.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let months = [\"Jan\", \"Feb\", \"Mar\", \"Apr\", \"May\", \"Jun\",\n                  \"Jul\", \"Aug\", \"Sep\", \"Oct\", \"Nov\", \"Dec\"];\n    let zeros = [0; 5];            // [0, 0, 0, 0, 0]: value; count\n    let scores: [u8; 3] = [90, 72, 85];\n\n    println!(\"{} months, the first is {}\", months.len(), months[0]);\n    println!(\"{zeros:?}\");\n    let mut total = 0u32;\n    for s in scores {\n        total += s as u32;\n    }\n    println!(\"total score: {total}\");\n}\n", "output": "12 months, the first is Jan\n[0, 0, 0, 0, 0]\ntotal score: 247\n", "explain": "`[0; 5]` repeats a value. `{zeros:?}` uses **debug formatting**, which can print a whole array. `for s in scores` visits each element in order; the next lesson covers loops properly."}, {"type": "text", "title": "Indexing, and what happens past the end", "md": "Elements are numbered from `0`, so the last element of an array of length `n` is at `n - 1`. The index must be a `usize`.\n\nWhat if the index is too big? In C this reads whatever memory happens to sit after the array, a classic source of security holes. Rust checks every index: if the compiler can see the mistake it refuses to compile, and if the index is only known at run time the program **panics** with `index out of bounds` instead of reading memory it does not own.\n"}, {"type": "playground", "id": "ch03-play-bounds", "title": "Read past the end", "lang": "rust", "md": "The index comes from parsing text, so the compiler cannot check it ahead of time. Run it and read the panic message. Then change `\"7\"` to `\"2\"` and run again. Finally, replace `days[index]` with `days.get(index)` and print it with `{:?}`: instead of a panic you get `None` for a bad index.\n", "code": "fn main() {\n    let days = [\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\"];\n    let index: usize = \"7\".parse().unwrap();\n    let day = days[index];\n    println!(\"day {index} is {day}\");\n}\n", "expect_panic": true, "hints": ["The panic message names the length (5) and the index (7).", "`println!(\"{:?}\", days.get(index));` prints `Some(\"Wed\")` for 2 and `None` for 7."]}, {"type": "text", "title": "Arrays of arrays", "md": "An element can itself be an array, which gives a grid. `[[0; 3]; 2]` is two rows of three zeros, and `grid[1][2]` is row 1, column 2.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let mut board = [['.'; 3]; 3];\n    board[1][1] = 'X';\n    board[0][2] = 'O';\n    for row in board {\n        let line: String = row.iter().collect();\n        println!(\"{line}\");\n    }\n}\n", "output": "..O\n.X.\n...\n", "explain": "`row.iter().collect()` turns three `char`s into a `String`. Iterators get their own chapter later; for now, read it as \"join these characters\"."}, {"type": "exercise", "id": "ch03-ex-compound", "exercise_dir": "ch03-tuples-arrays", "title": "Statistics on a week of temperatures", "difficulty": "easy", "goal": "Use tuples and arrays together: take a fixed week of readings and return results as tuples.", "behavior": "- `pub fn min_max(temps: [i32; 7]) -> (i32, i32)`: the lowest and the highest reading, in that order.\n- `pub fn warmest_day(temps: [i32; 7]) -> usize`: the index (0 = Monday) of the highest reading. If several days tie, return the first one.\n- `pub fn swap(pair: (String, i32)) -> (i32, String)`: the same two values in the other order.\n", "examples": [{"input": "min_max([3, -2, 7, 7, 0, 1, 5])", "output": "(-2, 7)"}, {"input": "warmest_day([3, -2, 7, 7, 0, 1, 5])", "output": "2"}, {"input": "swap((String::from(\"Oslo\"), 4))", "output": "(4, \"Oslo\")"}], "hints": ["Start `min` and `max` at `temps[0]`, then go through every reading with `for t in temps` and update them.", "For `warmest_day`, keep the best index in a `let mut best = 0;` and loop over `0..7`, comparing `temps[i]` with `temps[best]`. Use `>` (not `>=`) so ties keep the first day.", "`swap` is one line: destructure with `let (name, n) = pair;` and return `(n, name)`."], "solution_explain": "Starting both `min` and `max` at the first reading avoids picking a magic starting value that could be wrong for all-negative weeks. Comparing with `>` rather than `>=` is what keeps the first of several equal days.", "mode": "tests", "dir": "ch03-tuples-arrays", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// The lowest and the highest temperature of the week: (min, max).\npub fn min_max(temps: [i32; 7]) -> (i32, i32) {\n    todo!()\n}\n\n/// The index of the warmest day (0 = Monday). Ties go to the earliest day.\npub fn warmest_day(temps: [i32; 7]) -> usize {\n    todo!()\n}\n\n/// Returns the same values in the other order.\npub fn swap(pair: (String, i32)) -> (i32, String) {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch03_tuples_arrays\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn min_max_mixed() {\n    assert_eq!(min_max([3, -2, 7, 7, 0, 1, 5]), (-2, 7), \"min_max([3, -2, 7, 7, 0, 1, 5])\");\n}\n\n#[test]\nfn min_max_all_same() {\n    assert_eq!(min_max([4; 7]), (4, 4), \"min_max of seven 4s\");\n}\n\n#[test]\nfn min_max_all_negative() {\n    assert_eq!(min_max([-5, -9, -1, -3, -8, -2, -7]), (-9, -1), \"all below zero\");\n}\n\n#[test]\nfn warmest_first_of_ties() {\n    assert_eq!(warmest_day([3, -2, 7, 7, 0, 1, 5]), 2, \"two days at 7: the first is index 2\");\n}\n\n#[test]\nfn warmest_at_the_ends() {\n    assert_eq!(warmest_day([9, 1, 1, 1, 1, 1, 1]), 0, \"Monday is warmest\");\n    assert_eq!(warmest_day([1, 1, 1, 1, 1, 1, 9]), 6, \"Sunday is warmest\");\n}\n\n#[test]\nfn swap_pair() {\n    assert_eq!(swap((String::from(\"Oslo\"), 4)), (4, String::from(\"Oslo\")), \"swap((\\\"Oslo\\\", 4))\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// The lowest and the highest temperature of the week: (min, max).\npub fn min_max(temps: [i32; 7]) -> (i32, i32) {\n    let mut min = temps[0];\n    let mut max = temps[0];\n    for t in temps {\n        if t < min {\n            min = t;\n        }\n        if t > max {\n            max = t;\n        }\n    }\n    (min, max)\n}\n\n/// The index of the warmest day (0 = Monday). Ties go to the earliest day.\npub fn warmest_day(temps: [i32; 7]) -> usize {\n    let mut best = 0;\n    for i in 0..7 {\n        if temps[i] > temps[best] {\n            best = i;\n        }\n    }\n    best\n}\n\n/// Returns the same values in the other order.\npub fn swap(pair: (String, i32)) -> (i32, String) {\n    let (name, n) = pair;\n    (n, name)\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch03-quiz-compound", "title": "Check yourself", "questions": [{"type": "single", "q": "Which is the type of `(\"Ada\", 36)`?", "options": ["`[&str; 2]`", "`(&str, i32)`", "`(String, u32)`", "`tuple`"], "answer": 1, "explanation": "A tuple's type lists each element's type. `36` defaults to `i32`, and a string literal is a `&str`.", "hints": []}, {"type": "single", "q": "`let a = [1, 2, 3];` What is the type of `a`?", "options": ["`[i32]`", "`[i32; 3]`", "`Vec<i32>`", "`(i32, i32, i32)`"], "answer": 1, "explanation": "The length is part of an array's type: `[i32; 3]`.", "hints": []}, {"type": "single", "q": "`let a = [10, 20, 30];` and an index read from the user is 3. What happens at `a[index]`?", "options": ["It returns 0", "It returns whatever is in memory after the array", "The program panics with index out of bounds", "It returns 30"], "answer": 2, "explanation": "Rust checks every index at run time and panics rather than reading memory it does not own.", "hints": []}, {"type": "fill", "q": "Complete the line so it makes an array of eight zeros: `let z = [0; ___];`", "answer": ["8"], "explanation": "`[value; count]` repeats the value.", "hints": []}, {"type": "truefalse", "q": "You can push a new element onto an array to make it longer.", "answer": false, "explanation": "An array's length is fixed and part of its type. `Vec` is the growable list.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "let t = (1, (2, 3), 4);\nprintln!(\"{}\", (t.1).0 + t.2);\n", "lang": "rust", "options": ["3", "5", "6", "It does not compile"], "answer": 2, "explanation": "`t.1` is the inner tuple `(2, 3)`, its `.0` is 2, and `t.2` is 4: 2 + 4 = 6.", "hints": []}]}, {"type": "summary", "points": ["A tuple groups a fixed number of values of possibly different types: `(\"Ada\", 36)` has type `(&str, i32)`.", "Read a tuple by destructuring, `let (a, b) = t;`, or by position, `t.0`.", "`()` is the unit type: the value of things that return nothing.", "An array `[T; N]` holds N values of one type; its length is fixed and part of its type.", "`[v; n]` repeats a value; `a.len()` is the length; indexes start at 0 and are `usize`.", "Out-of-bounds indexing panics instead of reading memory; `a.get(i)` returns `None` instead of panicking."]}], "terms": [{"term": "tuple", "def": "A fixed-size group of values that may have different types, like (\"Ada\", 36)."}, {"term": "destructuring", "def": "Splitting a compound value into separate variables with a pattern, like let (a, b) = pair;"}, {"term": "unit", "def": "The empty tuple (), the value of expressions and functions that produce nothing useful."}, {"term": "array", "def": "A fixed-length sequence of values of one type, written [T; N]."}], "id": "ch03-03-compound-types", "chapter": "ch03", "kind": "lesson"}, "ch03-04-functions": {"title": "Functions, statements and expressions", "summary": "Define functions with parameters and return values, learn the difference between statements and expressions that makes Rust's return values work, and write comments.", "minutes": 25, "source": {"chapter": "ch03", "sections": ["TRPL 3.3 Functions", "TRPL 3.3 Parameters", "TRPL 3.3 Statements and Expressions", "TRPL 3.3 Functions with Return Values", "TRPL 3.4 Comments", "PR ch6 An Expression Language", "PR ch6 Blocks and Semicolons", "CR Blocks and Scopes", "CR Functions"]}, "blocks": [{"type": "text", "md": "You have written one function many times: `main`. This lesson shows how to write your own, pass values in and get a value back. It also explains the single idea that makes Rust code look the way it does: almost everything is an **expression** that produces a value, and a semicolon turns an expression into a **statement** that does not.\n"}, {"type": "text", "title": "Defining and calling a function", "md": "A function starts with `fn`, a name, parentheses and a body in braces. Rust uses **snake_case** for function and variable names: lowercase words joined by underscores. A function can be defined before or after the place that calls it; Rust does not care about the order.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    println!(\"Hello from main\");\n    another_function();\n}\n\nfn another_function() {\n    println!(\"Hello from another function\");\n}\n", "output": "Hello from main\nHello from another function\n"}, {"type": "text", "title": "Parameters", "md": "**Parameters** are the variables a function receives. Each one must have its type written out: Rust infers types inside a function body, but never in a function's signature. That is deliberate. The signature is a contract other code relies on, and spelling it out means the compiler rarely needs you to annotate anything else.\n"}, {"type": "code", "lang": "rust", "code": "fn print_labeled_measurement(value: i32, unit_label: char) {\n    println!(\"The measurement is: {value}{unit_label}\");\n}\n\nfn main() {\n    print_labeled_measurement(5, 'h');\n}\n", "output": "The measurement is: 5h", "explain": "The values you pass when calling, `5` and `'h'`, are the **arguments**. They must match the parameters' types exactly; passing `5.0` here is a compile error."}, {"type": "text", "title": "Statements and expressions", "md": "This distinction matters more in Rust than in most languages:\n\n- A **statement** performs an action and produces no value. `let y = 6;` is a statement, and so is a function definition.\n- An **expression** evaluates to a value. `5 + 6` is an expression, and so is a function call, a macro call, and a **block** in braces.\n\nBecause `let` is a statement, you cannot write `let x = (let y = 6);` as you might in C (`x = y = 6`). But because a block is an expression, you can do this:\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let y = {\n        let x = 3;\n        x + 1\n    };\n    println!(\"The value of y is: {y}\");\n}\n", "output": "The value of y is: 4", "explain": "The block's value is its last expression, `x + 1`. Note that `x + 1` has **no semicolon**. Adding one would make it a statement, the block would produce `()`, and `y` would be `()`."}, {"type": "callout", "kind": "key", "title": "The semicolon rule", "md": "A semicolon throws a value away. `x + 1` is the value 4; `x + 1;` is a statement whose value is `()`. Whenever a block or function should produce a value, its last line has no semicolon."}, {"type": "text", "title": "Return values", "md": "A function declares its return type after an arrow, `->`. The value returned is the **final expression** of the body. You can also leave early with `return value;`, which is the usual way to return from the middle of a function.\n"}, {"type": "code", "lang": "rust", "code": "fn five() -> i32 {\n    5\n}\n\nfn plus_one(x: i32) -> i32 {\n    x + 1\n}\n\nfn main() {\n    let x = plus_one(five());\n    println!(\"The value of x is: {x}\");\n}\n", "output": "The value of x is: 6"}, {"type": "text", "md": "The most common beginner error with return values is a stray semicolon. Here is what the compiler says, and it even points at the fix:\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "fn plus_one(x: i32) -> i32 {\n    x + 1;\n}\n", "output": "error[E0308]: mismatched types\n --> src/main.rs:1:24\n  |\n1 | fn plus_one(x: i32) -> i32 {\n  |    --------            ^^^ expected `i32`, found `()`\n  |    |\n  |    implicitly returns `()` as its body has no tail or `return` expression\n2 |     x + 1;\n  |          - help: remove this semicolon to return this value\n", "output_label": "Compiler output"}, {"type": "playground", "id": "ch03-play-semicolon", "title": "Find the semicolon", "lang": "rust", "md": "This does not compile. Run it, read the error (the console underlines the line it points at), and fix `area` so the program prints `area: 12`.\n", "code": "fn area(width: u32, height: u32) -> u32 {\n    width * height;\n}\n\nfn main() {\n    println!(\"area: {}\", area(3, 4));\n}\n", "expected_output": "area: 12", "hints": ["The compiler says the function returns `()` instead of `u32`. What turns a value into `()`?", "Remove the semicolon after `width * height`."]}, {"type": "text", "title": "if is an expression too", "md": "Since `if` is an expression, it can choose a value. Both branches must produce the same type, because the variable that receives the value can only have one type. This replaces the `? :` operator of C and JavaScript.\n"}, {"type": "code", "lang": "rust", "code": "fn sign(n: i32) -> &'static str {\n    if n < 0 {\n        \"negative\"\n    } else if n == 0 {\n        \"zero\"\n    } else {\n        \"positive\"\n    }\n}\n\nfn main() {\n    let n = -4;\n    let parity = if n % 2 == 0 { \"even\" } else { \"odd\" };\n    println!(\"{n} is {} and {parity}\", sign(n));\n}\n", "output": "-4 is negative and even", "explain": "`&'static str` is the type of a string literal that lives for the whole program. You will meet the `'static` part properly in chapter 10; for now, read it as \"a fixed piece of text\"."}, {"type": "text", "title": "Comments", "md": "`//` starts a comment that runs to the end of the line. Rust programmers write comments on their own line above the code they describe. A comment with three slashes, `///`, is a **documentation comment**: it describes the item below it, and `cargo doc` turns it into web pages. You saw these in the exercise starters.\n"}, {"type": "code", "lang": "rust", "code": "/// Converts degrees Fahrenheit to degrees Celsius.\nfn to_celsius(f: f64) -> f64 {\n    // subtract the offset first, then scale\n    (f - 32.0) * 5.0 / 9.0\n}\n"}, {"type": "playground", "id": "ch03-play-celsius", "title": "Write a conversion function", "lang": "rust", "md": "Write `to_fahrenheit`, the opposite of `to_celsius` above: F = C × 9 / 5 + 32. Then the program should print `100°C is 212°F` and `-40°C is -40°F`.\n", "code": "fn to_fahrenheit(c: f64) -> f64 {\n    0.0 // replace this\n}\n\nfn main() {\n    for c in [100.0, -40.0] {\n        println!(\"{c}°C is {}°F\", to_fahrenheit(c));\n    }\n}\n", "expected_output": "100°C is 212°F\n-40°C is -40°F\n", "hints": ["Float literals need a decimal point: `9.0`, not `9`.", "`c * 9.0 / 5.0 + 32.0`, with no semicolon."]}, {"type": "exercise", "id": "ch03-ex-functions", "exercise_dir": "ch03-functions", "title": "A small toolbox of functions", "difficulty": "easy", "goal": "Write functions with parameters and return values, using expressions rather than temporary variables where you can.", "behavior": "- `pub fn square(n: i64) -> i64`: n times n.\n- `pub fn hypotenuse(a: f64, b: f64) -> f64`: the length of the longest side of a right triangle, √(a² + b²).\n- `pub fn clamp_score(score: i32) -> i32`: the score limited to the range 0 to 100.\n- `pub fn grade(score: i32) -> char`: `'A'` for 90 and above, `'B'` for 80 to 89, `'C'` for 70 to 79, `'F'` below 70. Clamp the score first.\n", "examples": [{"input": "square(-7)", "output": "49"}, {"input": "hypotenuse(3.0, 4.0)", "output": "5.0"}, {"input": "clamp_score(130)", "output": "100"}, {"input": "grade(85)", "output": "'B'"}], "hints": ["`f64` has a `.sqrt()` method: `(a * a + b * b).sqrt()`.", "`clamp_score` can be an `if`/`else if`/`else` expression with no `return`.", "In `grade`, start with `let s = clamp_score(score);`, then an `if` chain from the top grade down."], "solution_explain": "Every function body ends in an expression, so none needs `return`. `clamp_score` also exists in the standard library as `score.clamp(0, 100)`; writing it once yourself shows why an `if` expression works there.", "mode": "tests", "dir": "ch03-functions", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// n times n.\npub fn square(n: i64) -> i64 {\n    todo!()\n}\n\n/// The hypotenuse of a right triangle with sides a and b.\npub fn hypotenuse(a: f64, b: f64) -> f64 {\n    todo!()\n}\n\n/// Limits a score to 0..=100.\npub fn clamp_score(score: i32) -> i32 {\n    todo!()\n}\n\n/// 'A' (90+), 'B' (80+), 'C' (70+) or 'F', after clamping the score.\npub fn grade(score: i32) -> char {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch03_functions\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn squares() {\n    assert_eq!(square(-7), 49, \"square(-7)\");\n    assert_eq!(square(0), 0, \"square(0)\");\n    assert_eq!(square(100_000), 10_000_000_000, \"square(100_000) needs i64\");\n}\n\n#[test]\nfn hypotenuses() {\n    assert!((hypotenuse(3.0, 4.0) - 5.0).abs() < 1e-9, \"hypotenuse(3.0, 4.0) should be 5.0\");\n    assert!((hypotenuse(1.0, 1.0) - 2f64.sqrt()).abs() < 1e-9, \"hypotenuse(1.0, 1.0) should be √2\");\n}\n\n#[test]\nfn clamping() {\n    assert_eq!(clamp_score(130), 100, \"clamp_score(130)\");\n    assert_eq!(clamp_score(-5), 0, \"clamp_score(-5)\");\n    assert_eq!(clamp_score(64), 64, \"clamp_score(64)\");\n}\n\n#[test]\nfn grades_at_the_edges() {\n    assert_eq!(grade(90), 'A', \"grade(90)\");\n    assert_eq!(grade(89), 'B', \"grade(89)\");\n    assert_eq!(grade(80), 'B', \"grade(80)\");\n    assert_eq!(grade(79), 'C', \"grade(79)\");\n    assert_eq!(grade(70), 'C', \"grade(70)\");\n    assert_eq!(grade(69), 'F', \"grade(69)\");\n}\n\n#[test]\nfn grades_out_of_range() {\n    assert_eq!(grade(250), 'A', \"grade(250) is clamped to 100\");\n    assert_eq!(grade(-3), 'F', \"grade(-3) is clamped to 0\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// n times n.\npub fn square(n: i64) -> i64 {\n    n * n\n}\n\n/// The hypotenuse of a right triangle with sides a and b.\npub fn hypotenuse(a: f64, b: f64) -> f64 {\n    (a * a + b * b).sqrt()\n}\n\n/// Limits a score to 0..=100.\npub fn clamp_score(score: i32) -> i32 {\n    if score < 0 {\n        0\n    } else if score > 100 {\n        100\n    } else {\n        score\n    }\n}\n\n/// 'A' (90+), 'B' (80+), 'C' (70+) or 'F', after clamping the score.\npub fn grade(score: i32) -> char {\n    let s = clamp_score(score);\n    if s >= 90 {\n        'A'\n    } else if s >= 80 {\n        'B'\n    } else if s >= 70 {\n        'C'\n    } else {\n        'F'\n    }\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch03-quiz-functions", "title": "Check yourself", "questions": [{"type": "single", "q": "Which signature is valid Rust?", "options": ["`fn add(a, b) -> i32`", "`fn add(a: i32, b: i32) -> i32`", "`fn add(a: i32, b: i32): i32`", "`function add(a: i32, b: i32) -> i32`"], "answer": 1, "explanation": "Every parameter needs a type, and the return type follows `->`.", "hints": []}, {"type": "single", "q": "What is the value of `y`?", "code": "let y = {\n    let x = 10;\n    x * 2;\n};\n", "lang": "rust", "options": ["20", "10", "`()`", "It does not compile"], "answer": 2, "hints": ["Look at the end of the last line inside the block."], "explanation": "`x * 2;` ends with a semicolon, so it is a statement and the block's value is `()`. It does compile; `y` is simply `()`."}, {"type": "multi", "q": "Which of these are expressions?", "options": ["`5 + 6`", "`let a = 1;`", "`plus_one(4)`", "`{ 3 }`", "`if a > 0 { 1 } else { 2 }`"], "answer": [0, 2, 3, 4], "explanation": "`let` is a statement. Arithmetic, calls, blocks and `if` all produce values.", "hints": []}, {"type": "truefalse", "q": "A function must be defined above the code that calls it.", "answer": false, "explanation": "Rust does not care about order; a function can be defined anywhere in scope.", "hints": []}, {"type": "single", "q": "Why does this not compile? `let n = if ok { 1 } else { \"none\" };`", "options": ["`if` cannot return values", "The branches have different types", "`else` is not allowed with `let`", "`ok` must be an integer"], "answer": 1, "explanation": "Both branches must have one type, because `n` can only have one type.", "hints": []}, {"type": "fill", "q": "A comment that documents the item below it starts with ___ (three characters).", "answer": ["///"], "explanation": "`///` doc comments become documentation with `cargo doc`.", "hints": []}]}, {"type": "summary", "points": ["`fn name(param: Type) -> Return { ... }`; parameter types are always written out.", "Statements (like `let`) do something; expressions (arithmetic, calls, blocks, `if`) produce a value.", "A block's value is its last expression; a trailing semicolon turns it into `()`.", "A function returns its final expression; `return` leaves early.", "`if` is an expression, so it can choose a value; both branches must have the same type.", "`//` comments a line; `///` documents the next item."]}], "terms": [{"term": "parameter", "def": "A variable in a function's signature that receives a value when the function is called."}, {"term": "argument", "def": "The value passed for a parameter when calling a function."}, {"term": "statement", "def": "An instruction that performs an action and produces no value, like let x = 5;"}, {"term": "expression", "def": "Code that evaluates to a value, like 5 + 6, a function call, a block or an if."}, {"term": "doc comment", "def": "A comment starting with /// that documents the item below it and is turned into documentation by cargo doc."}], "id": "ch03-04-functions", "chapter": "ch03", "kind": "lesson"}, "ch03-05-control-flow": {"title": "Decisions and loops", "summary": "Branch with if and else, repeat with loop, while and for, get values out of loops, and break out of nested loops with labels.", "minutes": 28, "source": {"chapter": "ch03", "sections": ["TRPL 3.5 Control Flow", "TRPL 3.5 if Expressions", "TRPL 3.5 Repetition with Loops", "TRPL 3.5 Returning Values from Loops", "TRPL 3.5 Loop Labels", "TRPL 3.5 Looping Through a Collection with for", "CR Loops", "CR break and continue", "PR ch6 Loops", "RiA 2.6 Control flow"]}, "blocks": [{"type": "text", "md": "Programs need to make decisions and repeat work. Rust gives you one way to decide, `if`, and three ways to repeat: `loop`, `while` and `for`. You have used most of them already. This lesson fills in the rules and the patterns you will use every day.\n"}, {"type": "text", "title": "if, else if, else", "md": "An `if` checks a condition and runs a block when it is `true`. The condition must be a `bool`: Rust will not treat a number or an empty string as false, so `if count { }` does not compile; write `if count != 0 { }`. Braces are required around every block, and parentheses around the condition are not used.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let number = 6;\n    if number % 4 == 0 {\n        println!(\"number is divisible by 4\");\n    } else if number % 3 == 0 {\n        println!(\"number is divisible by 3\");\n    } else if number % 2 == 0 {\n        println!(\"number is divisible by 2\");\n    } else {\n        println!(\"number is not divisible by 4, 3, or 2\");\n    }\n}\n", "output": "number is divisible by 3", "explain": "Rust checks each condition in order and runs only the **first** block whose condition is true, so 6 never reaches the \"divisible by 2\" branch. A long `else if` chain is often clearer as a `match`, which chapter 6 covers."}, {"type": "text", "title": "loop, and getting a value out", "md": "`loop` repeats its block forever, until you `break` out. `continue` skips the rest of the current pass and starts the next one. Because `loop` is an expression, `break` can carry a value out of it. That is the natural way to retry something until it succeeds and keep the result.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let mut counter = 0;\n    let result = loop {\n        counter += 1;\n        if counter == 10 {\n            break counter * 2;\n        }\n    };\n    println!(\"The result is {result}\");\n}\n", "output": "The result is 20"}, {"type": "text", "title": "Loop labels", "md": "With loops inside loops, `break` and `continue` apply to the innermost one. To act on an outer loop, give it a **label**, a name starting with a single quote, and name it: `break 'outer;`.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let grid = [[1, 2, 3], [4, 99, 6], [7, 8, 9]];\n    let mut found = None;\n    'rows: for (r, row) in grid.iter().enumerate() {\n        for (c, value) in row.iter().enumerate() {\n            if *value == 99 {\n                found = Some((r, c));\n                break 'rows;\n            }\n        }\n    }\n    println!(\"99 found at {found:?}\");\n}\n", "output": "99 found at Some((1, 1))", "explain": "`enumerate()` gives each element with its index. `*value` reads the number behind a reference; references are chapter 4's topic. Without the label, `break` would only leave the inner loop and the search would carry on through the next rows."}, {"type": "text", "title": "while", "md": "`while` runs as long as a condition stays true. It is the right tool when you do not know how many passes you need but you can say when to stop.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let mut n = 27u64;\n    let mut steps = 0;\n    while n != 1 {\n        n = if n % 2 == 0 { n / 2 } else { 3 * n + 1 };\n        steps += 1;\n    }\n    println!(\"27 reaches 1 after {steps} steps\");\n}\n", "output": "27 reaches 1 after 111 steps", "explain": "This is the Collatz sequence: halve even numbers, triple-and-add-one odd ones. Nobody has proved it always reaches 1, which is exactly the situation `while` is for."}, {"type": "text", "title": "for", "md": "`for` goes through every element of something you can iterate over: an array, a range, and (later) vectors, strings, maps, files and much more. It is the loop you will write most often, because it cannot run past the end and needs no counter to update by hand.\n\nA **range** `a..b` counts from `a` up to but not including `b`; `a..=b` includes `b`. `.rev()` goes backwards and `.step_by(n)` skips.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    for number in (1..4).rev() {\n        print!(\"{number}... \");\n    }\n    println!(\"LIFTOFF!\");\n\n    for even in (0..=10).step_by(2) {\n        print!(\"{even} \");\n    }\n    println!();\n}\n", "output": "3... 2... 1... LIFTOFF!\n0 2 4 6 8 10\n", "explain": "`print!` is `println!` without the newline; `println!()` alone ends the line."}, {"type": "table", "title": "Which loop?", "headers": ["You want to", "Use"], "rows": [["Go through every element, or count over a range", "`for`"], ["Repeat while a condition holds", "`while`"], ["Repeat until something inside decides to stop, possibly returning a value", "`loop` with `break value`"]]}, {"type": "playground", "id": "ch03-play-fizzbuzz", "title": "FizzBuzz", "lang": "rust", "md": "The classic: for the numbers 1 to 15, print `Fizz` for multiples of 3, `Buzz` for multiples of 5, `FizzBuzz` for multiples of both, and the number otherwise, one per line. The loop is there; write the body.\n", "code": "fn main() {\n    for n in 1..=15 {\n        println!(\"{n}\"); // replace with the FizzBuzz rules\n    }\n}\n", "expected_output": "1\n2\nFizz\n4\nBuzz\nFizz\n7\n8\nFizz\nBuzz\n11\nFizz\n13\n14\nFizzBuzz\n", "hints": ["Order matters: check \"both\" (`n % 15 == 0`) before checking 3 and 5 separately.", "`if n % 15 == 0 { ... } else if n % 3 == 0 { ... } else if n % 5 == 0 { ... } else { ... }`"]}, {"type": "playground", "id": "ch03-play-break-value", "title": "Find the first square over 500", "lang": "rust", "md": "Use a `loop` that counts `n` up from 1 and `break`s with the first `n * n` greater than 500. The program should print `first square over 500: 529`.\n", "code": "fn main() {\n    let mut n = 0;\n    let first = loop {\n        n += 1;\n        // break with n * n once it is over 500\n        if n > 1000 {\n            break 0;\n        }\n    };\n    println!(\"first square over 500: {first}\");\n}\n", "expected_output": "first square over 500: 529", "hints": ["Replace the comment and the `if n > 1000` guard with `if n * n > 500 { break n * n; }`."]}, {"type": "exercise", "id": "ch03-ex-loops", "exercise_dir": "ch03-loops", "title": "Loops that compute", "difficulty": "medium", "goal": "Pick the right loop for each job and get the edge cases right.", "behavior": "- `pub fn fibonacci(n: u32) -> u64`: the n-th Fibonacci number, where `fibonacci(0) = 0`, `fibonacci(1) = 1`, and each next one is the sum of the two before. Must work up to `n = 90`.\n- `pub fn sum_of_multiples(limit: u32) -> u32`: the sum of all numbers below `limit` that are multiples of 3 or 5 (counted once).\n- `pub fn digits(n: u64) -> u32`: how many decimal digits `n` has. `digits(0)` is 1.\n- `pub fn is_prime(n: u32) -> bool`: true for primes. 0 and 1 are not prime.\n", "examples": [{"input": "fibonacci(10)", "output": "55"}, {"input": "sum_of_multiples(10)", "output": "23  (3 + 5 + 6 + 9)"}, {"input": "digits(12345)", "output": "5"}, {"input": "is_prime(97)", "output": "true"}], "hints": ["Fibonacci: keep two variables, `let (mut a, mut b) = (0u64, 1u64);`, and repeat `n` times: `(a, b) = (b, a + b);`. Return `a`.", "`sum_of_multiples`: `for i in 0..limit` and add `i` when `i % 3 == 0 || i % 5 == 0`.", "`digits`: start at 1 and divide by 10 in a `while n >= 10` loop.", "`is_prime`: return false below 2, then try divisors `d` from 2 while `d * d <= n`."], "solution_explain": "`for _ in 0..n` repeats n times without needing the counter. `(a, b) = (b, a + b)` updates both at once, so no temporary is needed. `digits` and `is_prime` use `while` because the number of passes depends on the value. Testing divisors only up to √n is enough: any larger divisor pairs with a smaller one already tried.", "mode": "tests", "dir": "ch03-loops", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// The n-th Fibonacci number: 0, 1, 1, 2, 3, 5, 8, ...\npub fn fibonacci(n: u32) -> u64 {\n    todo!()\n}\n\n/// The sum of every number below `limit` that is a multiple of 3 or 5.\npub fn sum_of_multiples(limit: u32) -> u32 {\n    todo!()\n}\n\n/// How many decimal digits `n` has (0 has one digit).\npub fn digits(n: u64) -> u32 {\n    todo!()\n}\n\n/// Is `n` a prime number?\npub fn is_prime(n: u32) -> bool {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch03_loops\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn fibonacci_start() {\n    assert_eq!(fibonacci(0), 0, \"fibonacci(0)\");\n    assert_eq!(fibonacci(1), 1, \"fibonacci(1)\");\n    assert_eq!(fibonacci(2), 1, \"fibonacci(2)\");\n    assert_eq!(fibonacci(10), 55, \"fibonacci(10)\");\n}\n\n#[test]\nfn fibonacci_large() {\n    assert_eq!(fibonacci(90), 2_880_067_194_370_816_120, \"fibonacci(90) must not overflow u64\");\n}\n\n#[test]\nfn multiples() {\n    assert_eq!(sum_of_multiples(10), 23, \"sum_of_multiples(10)\");\n    assert_eq!(sum_of_multiples(16), 60, \"15 is counted once\");\n    assert_eq!(sum_of_multiples(1), 0, \"sum_of_multiples(1)\");\n    assert_eq!(sum_of_multiples(1000), 233_168, \"sum_of_multiples(1000)\");\n}\n\n#[test]\nfn digit_counts() {\n    assert_eq!(digits(0), 1, \"digits(0)\");\n    assert_eq!(digits(9), 1, \"digits(9)\");\n    assert_eq!(digits(10), 2, \"digits(10)\");\n    assert_eq!(digits(12345), 5, \"digits(12345)\");\n    assert_eq!(digits(u64::MAX), 20, \"digits(u64::MAX)\");\n}\n\n#[test]\nfn primes() {\n    for p in [2, 3, 5, 7, 11, 97, 7919] {\n        assert!(is_prime(p), \"{p} is prime\");\n    }\n    for n in [0, 1, 4, 9, 15, 91, 7917] {\n        assert!(!is_prime(n), \"{n} is not prime\");\n    }\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// The n-th Fibonacci number: 0, 1, 1, 2, 3, 5, 8, ...\npub fn fibonacci(n: u32) -> u64 {\n    let (mut a, mut b) = (0u64, 1u64);\n    for _ in 0..n {\n        (a, b) = (b, a + b);\n    }\n    a\n}\n\n/// The sum of every number below `limit` that is a multiple of 3 or 5.\npub fn sum_of_multiples(limit: u32) -> u32 {\n    let mut sum = 0;\n    for i in 0..limit {\n        if i % 3 == 0 || i % 5 == 0 {\n            sum += i;\n        }\n    }\n    sum\n}\n\n/// How many decimal digits `n` has (0 has one digit).\npub fn digits(n: u64) -> u32 {\n    let mut n = n;\n    let mut count = 1;\n    while n >= 10 {\n        n /= 10;\n        count += 1;\n    }\n    count\n}\n\n/// Is `n` a prime number?\npub fn is_prime(n: u32) -> bool {\n    if n < 2 {\n        return false;\n    }\n    let mut d = 2;\n    while d * d <= n {\n        if n % d == 0 {\n            return false;\n        }\n        d += 1;\n    }\n    true\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch03-quiz-control", "title": "Check yourself", "questions": [{"type": "single", "q": "Why does `let n = 3; if n { println!(\"yes\"); }` not compile?", "options": ["`if` needs parentheses", "The condition must be a `bool`", "`println!` cannot be inside `if`", "`n` must be `mut`"], "answer": 1, "explanation": "Rust never treats a number as true or false. Write `if n != 0`.", "hints": []}, {"type": "numeric", "q": "How many times does `for i in 2..7 { }` run?", "answer": 5, "explanation": "2, 3, 4, 5, 6: the end of `..` is excluded.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "let mut i = 0;\nlet x = loop {\n    i += 3;\n    if i > 10 { break i; }\n};\nprintln!(\"{x}\");\n", "lang": "rust", "options": ["10", "11", "12", "It loops forever"], "answer": 2, "explanation": "i goes 3, 6, 9, 12; 12 is the first value over 10, and `break i` returns it.", "hints": []}, {"type": "single", "q": "Inside two nested `for` loops, how do you stop **both** loops at once?", "options": ["`break break;`", "`return` is the only way", "Label the outer loop and use `break 'outer;`", "`exit;`"], "answer": 2, "explanation": "Labels like `'outer:` let `break` and `continue` target an outer loop.", "hints": []}, {"type": "order", "q": "Put the countdown output in order for `for n in (1..=3).rev() { print!(\"{n} \"); }`", "items": ["3", "2", "1"], "explanation": "`rev()` walks the range backwards.", "hints": []}, {"type": "truefalse", "q": "`while` is the safest way to go through every element of an array.", "answer": false, "explanation": "`for` is: it cannot index past the end, and there is no counter to forget to update.", "hints": []}]}, {"type": "summary", "points": ["`if` conditions must be `bool`; only the first true branch of an `else if` chain runs.", "`loop` repeats until `break`; `break value` makes the loop produce a value.", "`continue` skips to the next pass; labels like `'outer` let `break`/`continue` reach an outer loop.", "`while` repeats while a condition holds; use it when the number of passes depends on the data.", "`for x in collection` and `for i in a..b` are the everyday loops: no counters to manage, no running past the end.", "Ranges: `a..b` excludes b, `a..=b` includes it; `.rev()` reverses, `.step_by(n)` skips."]}], "terms": [{"term": "loop label", "def": "A name like 'outer: on a loop, so break 'outer; or continue 'outer; can target it from an inner loop."}, {"term": "range", "def": "A sequence of numbers written a..b (end excluded) or a..=b (end included)."}, {"term": "break value", "def": "break followed by an expression: ends a loop and makes the loop expression produce that value."}], "id": "ch03-05-control-flow", "chapter": "ch03", "kind": "lesson"}, "ch03-99-test": {"title": "Chapter test: Common Programming Concepts", "kind": "test", "summary": "Twelve questions on variables, types, tuples and arrays, functions and loops. You need 70% to pass; you can retry and your best score is kept.", "blocks": [{"type": "quiz", "id": "ch03-test", "pass_score": 0.7, "questions": [{"type": "single", "q": "Which change makes this compile?", "code": "let total = 0;\ntotal += 5;\n", "lang": "rust", "options": ["`const total = 0;`", "`let mut total = 0;`", "`let total: u32 = 0;`", "`total = total + 5;`"], "answer": 1, "explanation": "Variables are immutable by default; `mut` allows changing them.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "let x = 5;\nlet x = x * 2;\n{\n    let x = x + 1;\n    print!(\"{x} \");\n}\nprintln!(\"{x}\");\n", "lang": "rust", "options": ["11 11", "11 10", "6 5", "It does not compile"], "answer": 1, "hints": ["Each `let x` makes a new variable. Where does the inner one stop existing?"], "explanation": "Shadowing: the outer `x` becomes 10; the inner block shadows it with 11 only until the closing brace."}, {"type": "multi", "q": "Which are true of `const` but not of `let`?", "options": ["The type must be written", "The value must be computable at compile time", "It can never be `mut`", "It can be declared at the top level, outside functions", "It can be shadowed"], "answer": [0, 1, 2, 3], "explanation": "Constants need a type, a compile-time value, are always immutable and may be global. Shadowing is a `let` feature.", "hints": []}, {"type": "single", "q": "In a release build, `let x: u8 = 255;` and at run time `x + 1` is computed. What is the result?", "options": ["A panic", "256", "0", "255"], "answer": 2, "explanation": "Release builds drop the overflow check and wrap around. Debug builds would panic.", "hints": []}, {"type": "single", "q": "Which expression returns `None` instead of overflowing?", "options": ["`200u8 + 100`", "`200u8.wrapping_add(100)`", "`200u8.checked_add(100)`", "`200u8.saturating_add(100)`"], "answer": 2, "explanation": "`checked_` methods return `Option`. `wrapping_` gives 44 and `saturating_` gives 255.", "hints": []}, {"type": "single", "q": "What is the type of `[\"a\", \"b\", \"c\"]`?", "options": ["`[&str]`", "`[&str; 3]`", "`(&str, &str, &str)`", "`Vec<&str>`"], "answer": 1, "explanation": "An array's type includes its length.", "hints": []}, {"type": "fill", "q": "`let point = (3, 7);` Write the expression that reads the 7: `point.___`", "answer": ["1"], "explanation": "Tuple positions start at 0, so the second element is `.1`.", "hints": []}, {"type": "single", "q": "What does this function return?", "code": "fn f(x: i32) -> i32 {\n    if x > 0 {\n        return 1;\n    }\n    x * 2\n}\n", "lang": "rust", "options": ["`f(5)` is 10 and `f(-3)` is -6", "`f(5)` is 1 and `f(-3)` is -6", "`f(5)` is 1 and `f(-3)` is 1", "It does not compile"], "answer": 1, "explanation": "`return` leaves early for positive numbers; otherwise the final expression `x * 2` is returned.", "hints": []}, {"type": "truefalse", "q": "`fn double(x: i32) -> i32 { x * 2; }` compiles and returns twice x.", "answer": false, "explanation": "The semicolon makes the body end in a statement, so it returns `()` and the compiler reports mismatched types.", "hints": []}, {"type": "numeric", "q": "What is printed? `let mut s = 0; for i in 1..=4 { s += i; } println!(\"{s}\");`", "answer": 10, "explanation": "1 + 2 + 3 + 4 = 10; `..=` includes 4.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "let mut count = 0;\n'outer: for a in 0..3 {\n    for b in 0..3 {\n        if b == 2 { continue 'outer; }\n        if a == 2 { break 'outer; }\n        count += 1;\n    }\n}\nprintln!(\"{count}\");\n", "lang": "rust", "options": ["4", "6", "9", "2"], "answer": 0, "hints": ["For each `a`, which values of `b` reach `count += 1`?"], "explanation": "For a = 0 and a = 1, b = 0 and b = 1 count (b = 2 jumps to the next a): 4. At a = 2 the outer loop stops before counting."}, {"type": "order", "q": "Put these in the order Rust runs them for `let v = loop { n += 1; if n == 3 { break n * 10; } };` with `n` starting at 0, ending with the value of `v`.", "items": ["n becomes 1", "n becomes 2", "n becomes 3", "break with 30", "v is 30"], "explanation": "The loop runs until n is 3, then `break n * 10` hands 30 to `v`.", "hints": []}], "mode": "test"}], "id": "ch03-99-test", "chapter": "ch03", "minutes": 10}, "ch04-01-ownership": {"title": "Ownership: who cleans up", "summary": "Where values live, the three ownership rules, and what moving, copying, cloning and dropping mean, including when you pass values to functions.", "minutes": 35, "source": {"chapter": "ch04", "sections": ["TRPL 4.1 What Is Ownership?", "TRPL 4.1 The Stack and the Heap", "TRPL 4.1 Ownership Rules", "TRPL 4.1 Memory and Allocation", "TRPL 4.1 Ownership and Functions", "PR ch4 Ownership", "PR ch4 Moves", "PR ch4 Copy Types", "RiA 4.1-4.3 CubeSat ground station", "CR Day 3 Memory Management"]}, "blocks": [{"type": "text", "md": "Every program has to manage memory: get it when it needs to store something, and give it back when it is finished. Languages solve this in one of two ways:\n\n- **Garbage collection** (Java, Python, Go, JavaScript): a runtime looks for memory nobody uses any more and frees it. Easy to use, but it costs run time and memory, and you do not decide when cleanup happens.\n- **Manual management** (C, C++): you allocate and free memory yourself. Fast, but forget to free and you leak; free twice or use memory after freeing it and you get crashes and security holes.\n\nRust takes a third way. Memory is managed through a set of **ownership** rules that the compiler checks. If a rule is broken, the program does not compile. When it does compile, the cleanup code is placed exactly where it belongs, with no garbage collector running in the background. Ownership is the topic that makes Rust feel different at first, and the one that pays off most once it clicks.\n"}, {"type": "text", "title": "The stack and the heap", "md": "To see why ownership exists, you need a rough picture of the two places a program keeps its data.\n\nThe **stack** stores values in the order they arrive and removes them in the opposite order, like a stack of plates: last in, first out. Everything on the stack must have a size known when the program is compiled. Pushing and popping is extremely fast, because the place for new data is always the top.\n\nThe **heap** is for data whose size is unknown when compiling, or which can change: text typed by a user, a list that grows. You ask the memory allocator for space, it finds a free block big enough and gives you its address, a **pointer**. The pointer has a fixed size, so it can live on the stack, while the data it points to lives on the heap. Allocating and reading through a pointer is slower than using the stack.\n"}, {"type": "callout", "kind": "key", "title": "What ownership is really about", "md": "Keeping track of which code is using which data on the heap, making sure nothing is duplicated by accident, and freeing heap memory that is no longer used. Once you understand ownership, you rarely need to think about the stack and the heap directly, but knowing they exist explains every rule that follows."}, {"type": "text", "title": "The three rules", "md": "1. Each value in Rust has an **owner**.\n2. There can only be **one owner at a time**.\n3. When the owner goes **out of scope**, the value is **dropped** (its memory is freed).\n\nA **scope** is the region of code where a name is valid, usually the `{ ... }` block it was declared in.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    {                      // s is not valid here, it is not declared yet\n        let s = \"hello\";   // s is valid from this point forward\n        println!(\"{s}\");\n    }                      // the scope is over, and s is no longer valid\n}\n", "output": "hello"}, {"type": "text", "title": "A type that lives on the heap: String", "md": "String literals like `\"hello\"` are baked into the program file, so they never need to be freed, and they cannot change. To show ownership in action we need text that lives on the heap: the `String` type. You create one from a literal with `String::from`, and unlike a literal it can grow:\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let mut s = String::from(\"hello\");\n    s.push_str(\", world!\"); // appends a literal to the String\n    println!(\"{s}\");\n}\n", "output": "hello, world!", "explain": "`String::from` asks the allocator for heap memory. Someone must give it back. In Rust, that happens automatically when `s` goes out of scope: Rust calls a special function, `drop`, at the closing brace. C++ programmers know this pattern as RAII."}, {"type": "text", "title": "Move", "md": "Here is where Rust differs from other languages. With integers, copying a variable copies the value, and both variables are usable:\n\n```rust\nlet x = 5;\nlet y = x;          // y is a copy of 5; x is still 5\n```\n\nA `String` is three parts on the stack, a pointer to the heap text, a length and a capacity, plus the text itself on the heap:\n"}, {"type": "svg", "caption": "`let s1 = String::from(\"hello\"); let s2 = s1;` copies the three stack fields. Both would point at the same heap text, so Rust marks `s1` as no longer valid: the value has **moved** to `s2`.", "svg": "<svg viewBox='0 0 560 230' xmlns='http://www.w3.org/2000/svg' font-family='ui-monospace, monospace' font-size='13'>\n  <g fill='none' stroke='currentColor' stroke-width='1'>\n    <rect x='20' y='40' width='150' height='90'/>\n    <path d='M20 70 H170 M20 100 H170 M95 40 V130'/>\n    <rect x='20' y='150' width='150' height='90' stroke-dasharray='4 3' opacity='.55'/>\n    <rect x='360' y='70' width='180' height='120'/>\n    <path d='M360 94 H540 M360 118 H540 M360 142 H540 M360 166 H540 M450 70 V190'/>\n    <path d='M150 55 C 250 55, 280 82, 356 82' stroke-width='1.5'/>\n    <path d='M350 78 L356 82 L350 86' stroke-width='1.5'/>\n  <\/g>\n  <g fill='currentColor'>\n    <text x='20' y='30' font-family='sans-serif' font-weight='600'>s2 (stack)<\/text>\n    <text x='28' y='60'>ptr<\/text><text x='28' y='90'>len<\/text><text x='103' y='90'>5<\/text>\n    <text x='28' y='120'>capacity<\/text><text x='130' y='120'>5<\/text>\n    <text x='360' y='60' font-family='sans-serif' font-weight='600'>heap<\/text>\n    <text x='368' y='87'>0<\/text><text x='458' y='87'>h<\/text>\n    <text x='368' y='111'>1<\/text><text x='458' y='111'>e<\/text>\n    <text x='368' y='135'>2<\/text><text x='458' y='135'>l<\/text>\n    <text x='368' y='159'>3<\/text><text x='458' y='159'>l<\/text>\n    <text x='368' y='183'>4<\/text><text x='458' y='183'>o<\/text>\n    <text x='190' y='190' font-family='sans-serif' opacity='.7'>s1: moved, no longer usable<\/text>\n  <\/g>\n<\/svg>\n"}, {"type": "text", "md": "If both `s1` and `s2` stayed valid, both would try to free the same heap memory when they go out of scope. That is a **double free**, one of the classic memory-safety bugs. Rust avoids it by treating `let s2 = s1;` as a **move**: ownership of the heap text passes to `s2`, and `s1` can no longer be used. Nothing on the heap is copied, so a move is cheap no matter how big the text is.\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "fn main() {\n    let s1 = String::from(\"hello\");\n    let s2 = s1;\n    println!(\"{s1}, world!\");\n}\n", "output": "error[E0382]: borrow of moved value: `s1`\n --> src/main.rs:4:16\n  |\n2 |     let s1 = String::from(\"hello\");\n  |         -- move occurs because `s1` has type `String`, which does not implement the `Copy` trait\n3 |     let s2 = s1;\n  |              -- value moved here\n4 |     println!(\"{s1}, world!\");\n  |                ^^ value borrowed here after move\n  |\nhelp: consider cloning the value if the performance cost is acceptable\n  |\n3 |     let s2 = s1.clone();\n  |                ++++++++\n", "output_label": "Compiler output", "explain": "The message tells the whole story in three labels: why it moved (`String` is not `Copy`), where it moved, and where you tried to use it afterwards. Learn to read these three lines; you will see them often in your first weeks."}, {"type": "callout", "kind": "note", "title": "Assigning a new value drops the old one", "md": "`let mut s = String::from(\"hello\"); s = String::from(\"ahoy\");` frees the memory of `\"hello\"` immediately, because nothing owns it any more. You do not have to do anything."}, {"type": "text", "title": "Clone", "md": "When you really do want a second, independent copy of the heap data, ask for it explicitly with `.clone()`. Cloning a big value can be expensive, and the visible `clone()` call is Rust's way of making that cost obvious when you read the code.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let s1 = String::from(\"hello\");\n    let s2 = s1.clone();\n    println!(\"s1 = {s1}, s2 = {s2}\");\n}\n", "output": "s1 = hello, s2 = hello"}, {"type": "text", "title": "Copy types", "md": "Why did `let y = x;` work for integers? Because integers live entirely on the stack, and copying them is as cheap as moving them. Types like that implement the **`Copy`** trait, and assigning them copies instead of moving. The original stays valid.\n\n`Copy` types: all integer types, `bool`, all floating-point types, `char`, and tuples and arrays that contain only `Copy` types, such as `(i32, f64)` or `[u8; 4]`. A type that owns heap memory, like `String`, can never be `Copy`.\n"}, {"type": "table", "title": "What happens on `let b = a;`", "headers": ["Type of `a`", "Result", "Can you still use `a`?"], "rows": [["`i32`, `f64`, `bool`, `char`", "copy", "yes"], ["`(i32, bool)`, `[u8; 4]`", "copy (all parts are `Copy`)", "yes"], ["`String`", "move", "no"], ["`(i32, String)`", "move (one part is not `Copy`)", "no"], ["`a.clone()` of a `String`", "deep copy of the heap data", "yes"]]}, {"type": "text", "title": "Ownership and functions", "md": "Passing a value to a function works exactly like assigning it to a variable: a `String` is **moved** into the function's parameter, and an `i32` is copied. Returning a value moves it out to the caller.\n"}, {"type": "stepper", "title": "Follow the ownership", "lang": "rust", "steps": [{"title": "s comes into scope", "md": "`s` owns a heap-allocated String.", "code": "fn main() {\n    let s = String::from(\"hello\");\n    takes_ownership(s);\n    let x = 5;\n    makes_copy(x);\n    println!(\"{x}\");\n}\n\nfn takes_ownership(some_string: String) {\n    println!(\"{some_string}\");\n}\n\nfn makes_copy(some_integer: i32) {\n    println!(\"{some_integer}\");\n}\n", "highlight": [2]}, {"title": "s moves into the function", "md": "Ownership passes to the parameter `some_string`. From this line on, using `s` in `main` would be a compile error.", "code": "fn main() {\n    let s = String::from(\"hello\");\n    takes_ownership(s);\n    let x = 5;\n    makes_copy(x);\n    println!(\"{x}\");\n}\n\nfn takes_ownership(some_string: String) {\n    println!(\"{some_string}\");\n}\n\nfn makes_copy(some_integer: i32) {\n    println!(\"{some_integer}\");\n}\n", "highlight": [3, 9]}, {"title": "The function ends: drop", "md": "`some_string` goes out of scope at the closing brace of `takes_ownership`, so the String is dropped and its heap memory freed, there and not in `main`.", "code": "fn main() {\n    let s = String::from(\"hello\");\n    takes_ownership(s);\n    let x = 5;\n    makes_copy(x);\n    println!(\"{x}\");\n}\n\nfn takes_ownership(some_string: String) {\n    println!(\"{some_string}\");\n}\n\nfn makes_copy(some_integer: i32) {\n    println!(\"{some_integer}\");\n}\n", "highlight": [11]}, {"title": "x is copied", "md": "`i32` is `Copy`, so `makes_copy` gets its own copy and `x` stays usable in `main`.", "code": "fn main() {\n    let s = String::from(\"hello\");\n    takes_ownership(s);\n    let x = 5;\n    makes_copy(x);\n    println!(\"{x}\");\n}\n\nfn takes_ownership(some_string: String) {\n    println!(\"{some_string}\");\n}\n\nfn makes_copy(some_integer: i32) {\n    println!(\"{some_integer}\");\n}\n", "highlight": [4, 5, 6]}]}, {"type": "text", "title": "Giving it back", "md": "A function can return ownership. That works, but threading every value in and back out quickly gets tedious, as this example shows:\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let s1 = String::from(\"hello\");\n    let (s2, len) = calculate_length(s1);\n    println!(\"The length of '{s2}' is {len}.\");\n}\n\nfn calculate_length(s: String) -> (String, usize) {\n    let length = s.len();\n    (s, length) // give the String back along with the answer\n}\n", "output": "The length of 'hello' is 5.", "explain": "All we wanted was the length, yet we had to pass the String in, get it back out in a tuple, and give it a new name. The next lesson shows the proper tool for \"let me look at this without taking it\": a **reference**."}, {"type": "playground", "id": "ch04-play-cubesat", "title": "The satellite that vanished", "lang": "rust", "md": "Adapted from *Rust in Action*. A ground station checks each satellite's status twice, but `check_status` takes ownership of the satellite name, so the second round does not compile. Run it and read the error. Then fix it **without** using `clone()`: make `check_status` return the name back together with the status, and rebind the variable on each call. The program should print the two lines shown in the task.\n", "task": "Print `sat-a: ok` twice, once per round, without calling clone().", "code": "fn check_status(sat: String) -> &'static str {\n    if sat.is_empty() { \"unknown\" } else { \"ok\" }\n}\n\nfn main() {\n    let sat_a = String::from(\"sat-a\");\n    let status = check_status(sat_a);\n    println!(\"{sat_a}: {status}\");\n    let status = check_status(sat_a);\n    println!(\"{sat_a}: {status}\");\n}\n", "expected_output": "sat-a: ok\nsat-a: ok\n", "hints": ["Change the return type to a tuple: `-> (String, &'static str)`, and return `(sat, status)`.", "In `main`, shadow the variable on each call: `let (sat_a, status) = check_status(sat_a);`", "This works but is clumsy. Lesson 2 replaces it with `fn check_status(sat: &String)`."]}, {"type": "reveal", "prompt": "Why does Rust move a String instead of copying it, as Python or Java appear to do?", "md": "Copying would mean duplicating the heap data on every assignment and every function call, which would be slow for big values and surprising. Sharing the heap data between two owners without copying (what garbage-collected languages do) needs a runtime to know when the last user is gone. A move gives you the speed of sharing and the safety of a single owner: exactly one variable is responsible for freeing the memory, and the compiler knows which.\n"}, {"type": "exercise", "id": "ch04-ex-ownership", "exercise_dir": "ch04-ownership", "title": "Pass, return and clone", "difficulty": "easy", "goal": "Write functions that take ownership of a String and hand back what the caller needs.", "behavior": "- `pub fn shout(s: String) -> String`: the same text in capital letters, with `!` added at the end. It takes ownership of `s` and may reuse it.\n- `pub fn join_words(a: String, b: String) -> String`: `a`, a space, then `b`.\n- `pub fn twice(s: &str) -> (String, String)`: two independent Strings containing the same text (you will need `String::from` or `.to_string()`, and `.clone()`).\n", "examples": [{"input": "shout(String::from(\"hello\"))", "output": "\"HELLO!\""}, {"input": "join_words(String::from(\"ground\"), String::from(\"station\"))", "output": "\"ground station\""}, {"input": "twice(\"sat\")", "output": "(\"sat\", \"sat\")"}], "hints": ["`s.to_uppercase()` returns a new String. Then `push('!')` onto it, or use `format!(\"{}!\", ...)`.", "`join_words` can take `mut a`, then `a.push(' ');` and `a.push_str(&b);` and return `a`. (The `&` is next lesson's topic; `push_str` wants to look at `b`, not own it.)", "`twice`: `let first = String::from(s); let second = first.clone(); (first, second)`."], "solution_explain": "`join_words` reuses `a`'s heap buffer instead of allocating a new String: since the function owns `a`, it may change it. `b` is dropped when the function returns. In `twice`, `clone` is the only way to get two owners of equal text.", "mode": "tests", "dir": "ch04-ownership", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// The text in capital letters with \"!\" at the end.\npub fn shout(s: String) -> String {\n    todo!()\n}\n\n/// \"a b\": the two words joined by one space.\npub fn join_words(a: String, b: String) -> String {\n    todo!()\n}\n\n/// Two separate Strings holding the same text.\npub fn twice(s: &str) -> (String, String) {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch04_ownership\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn shouting() {\n    assert_eq!(shout(String::from(\"hello\")), \"HELLO!\", \"shout(\\\"hello\\\")\");\n    assert_eq!(shout(String::new()), \"!\", \"shout of an empty String\");\n}\n\n#[test]\nfn joining() {\n    assert_eq!(join_words(String::from(\"ground\"), String::from(\"station\")), \"ground station\");\n    assert_eq!(join_words(String::from(\"a\"), String::new()), \"a \", \"an empty second word still gets the space\");\n}\n\n#[test]\nfn two_independent_copies() {\n    let (mut a, b) = twice(\"sat\");\n    assert_eq!((a.as_str(), b.as_str()), (\"sat\", \"sat\"), \"twice(\\\"sat\\\")\");\n    a.push('!');\n    assert_eq!(b, \"sat\", \"changing the first must not change the second\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// The text in capital letters with \"!\" at the end.\npub fn shout(s: String) -> String {\n    let mut loud = s.to_uppercase();\n    loud.push('!');\n    loud\n}\n\n/// \"a b\": the two words joined by one space.\npub fn join_words(mut a: String, b: String) -> String {\n    a.push(' ');\n    a.push_str(&b);\n    a\n}\n\n/// Two separate Strings holding the same text.\npub fn twice(s: &str) -> (String, String) {\n    let first = String::from(s);\n    let second = first.clone();\n    (first, second)\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch04-quiz-ownership", "title": "Check yourself", "questions": [{"type": "single", "q": "Which statement about the heap is true?", "options": ["Every value in Rust is on the heap", "Data whose size can change, like a String's text, is stored on the heap", "The heap is faster than the stack", "Heap memory is freed by a garbage collector in Rust"], "answer": 1, "explanation": "Growable data goes on the heap. Rust frees it when the owner goes out of scope; there is no garbage collector.", "hints": []}, {"type": "single", "q": "After `let a = String::from(\"x\"); let b = a;`, what happens if you use `a`?", "options": ["It prints `x`", "It prints an empty string", "Compile error: value used after move", "A panic at run time"], "answer": 2, "explanation": "Ownership moved to `b`. The compiler rejects any later use of `a`.", "hints": []}, {"type": "multi", "q": "Which types are `Copy`?", "options": ["`u64`", "`String`", "`(char, bool)`", "`[i32; 3]`", "`(i32, String)`"], "answer": [0, 2, 3], "explanation": "Plain numbers, `char`, `bool`, and tuples or arrays made only of `Copy` types are `Copy`. Anything containing a `String` is not.", "hints": []}, {"type": "single", "q": "When is the memory of `s` freed here?", "code": "fn eat(s: String) {\n    println!(\"{s}\");\n}\nfn main() {\n    let s = String::from(\"hi\");\n    eat(s);\n    println!(\"done\");\n}\n", "lang": "rust", "options": ["At the end of `main`", "At the end of `eat`", "Never, it leaks", "When the program exits"], "answer": 1, "explanation": "`s` moved into `eat`, so it is dropped when `eat`'s parameter goes out of scope.", "hints": []}, {"type": "truefalse", "q": "A move copies all of a String's heap data to the new owner.", "answer": false, "explanation": "Only the pointer, length and capacity (on the stack) are copied. That is why a move is cheap.", "hints": []}, {"type": "fill", "q": "To make a deep copy of a String so both variables stay usable, call `.______()`.", "answer": ["clone"], "explanation": "`clone` duplicates the heap data.", "hints": []}]}, {"type": "summary", "points": ["Stack: fast, fixed-size, last in first out. Heap: for data whose size is unknown or changes, reached through a pointer.", "Rules: every value has one owner; when the owner goes out of scope, the value is dropped.", "Assigning or passing a non-`Copy` value like `String` **moves** it; the old name can no longer be used.", "`Copy` types (numbers, `bool`, `char`, and tuples/arrays of them) are copied instead.", "`.clone()` makes an explicit, possibly expensive, deep copy.", "Functions take ownership of what they are given and can give it back by returning it."]}], "terms": [{"term": "ownership", "def": "Rust's system for memory management: each value has exactly one owner, and it is freed when the owner goes out of scope."}, {"term": "move", "def": "Transferring ownership of a value to another variable or function; the original can no longer be used."}, {"term": "drop", "def": "Freeing a value's resources when its owner goes out of scope; Rust inserts the call automatically."}, {"term": "Copy", "def": "A trait for types that are duplicated by simple bit copying (numbers, bool, char); assigning them copies instead of moving."}, {"term": "clone", "def": "An explicit deep copy of a value, including its heap data."}, {"term": "heap", "def": "Memory for data whose size is not known at compile time, allocated on request and reached through a pointer."}, {"term": "stack", "def": "Memory for fixed-size values, managed last in, first out; very fast."}], "id": "ch04-01-ownership", "chapter": "ch04", "kind": "lesson"}, "ch04-02-references": {"title": "References and borrowing", "summary": "Use a value without taking ownership: shared references (&T), mutable references (&mut T), the two borrowing rules, and why dangling references cannot exist in Rust.", "minutes": 35, "source": {"chapter": "ch04", "sections": ["TRPL 4.2 References and Borrowing", "TRPL 4.2 Mutable References", "TRPL 4.2 Dangling References", "TRPL 4.2 The Rules of References", "PR ch5 References to Values", "PR ch5 Working with References", "PR ch5 Sharing Versus Mutation", "RiA 4.3 Resolving ownership issues", "CR Day 3 Borrowing"]}, "blocks": [{"type": "text", "md": "At the end of the last lesson, finding the length of a String meant moving it into a function and getting it back. A **reference** removes that dance. A reference is like a pointer: an address you can follow to reach data owned by someone else. Unlike a raw pointer, a reference is guaranteed by the compiler to point to a valid value for as long as the reference exists.\n\nCreating a reference is called **borrowing**. As in real life, when you borrow something you do not own it, and you have to give it back.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let s1 = String::from(\"hello\");\n    let len = calculate_length(&s1);\n    println!(\"The length of '{s1}' is {len}.\");\n}\n\nfn calculate_length(s: &String) -> usize {\n    s.len()\n}\n", "output": "The length of 'hello' is 5.", "explain": "`&s1` creates a reference to `s1` without moving it, and the parameter type `&String` says \"a reference to a String\". When `s` goes out of scope at the end of `calculate_length`, nothing is dropped, because `s` never owned the String. `s1` is still valid afterwards."}, {"type": "svg", "caption": "`s` is a reference: a pointer to `s1` on the stack, which in turn owns the heap text. Dropping `s` frees nothing.", "svg": "<svg viewBox='0 0 600 150' xmlns='http://www.w3.org/2000/svg' font-family='ui-monospace, monospace' font-size='13'>\n  <g fill='none' stroke='currentColor' stroke-width='1'>\n    <rect x='20' y='40' width='100' height='34'/>\n    <rect x='190' y='40' width='150' height='90'/>\n    <path d='M190 70 H340 M190 100 H340 M265 40 V130'/>\n    <rect x='430' y='40' width='150' height='34'/>\n    <path d='M100 57 H184' stroke-width='1.5'/><path d='M178 53 L184 57 L178 61'/>\n    <path d='M320 55 C 380 55, 380 57, 424 57' stroke-width='1.5'/><path d='M418 53 L424 57 L418 61'/>\n  <\/g>\n  <g fill='currentColor'>\n    <text x='20' y='30' font-family='sans-serif' font-weight='600'>s<\/text>\n    <text x='30' y='62'>ptr<\/text>\n    <text x='190' y='30' font-family='sans-serif' font-weight='600'>s1<\/text>\n    <text x='198' y='60'>ptr<\/text><text x='198' y='90'>len<\/text><text x='275' y='90'>5<\/text>\n    <text x='198' y='120'>capacity<\/text><text x='300' y='120'>5<\/text>\n    <text x='430' y='30' font-family='sans-serif' font-weight='600'>heap<\/text>\n    <text x='440' y='62'>h e l l o<\/text>\n  <\/g>\n<\/svg>\n"}, {"type": "text", "title": "References are immutable by default", "md": "Like variables, references cannot change what they point to unless you say so. Try to modify borrowed data through a plain `&` and the compiler stops you:\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "fn main() {\n    let s = String::from(\"hello\");\n    change(&s);\n}\n\nfn change(some_string: &String) {\n    some_string.push_str(\", world\");\n}\n", "output": "error[E0596]: cannot borrow `*some_string` as mutable, as it is behind a `&` reference\n --> src/main.rs:7:5\n  |\n7 |     some_string.push_str(\", world\");\n  |     ^^^^^^^^^^^ `some_string` is a `&` reference, so it cannot be borrowed as mutable\n  |\nhelp: consider changing this to be a mutable reference\n  |\n6 | fn change(some_string: &mut String) {\n  |                         +++\n", "output_label": "Compiler output"}, {"type": "text", "title": "Mutable references", "md": "To allow changes, three things must say `mut`: the variable (`let mut s`), the borrow (`&mut s`), and the parameter type (`&mut String`). Seeing `&mut` at the call site is useful: anyone reading `change(&mut s)` knows `s` may be different afterwards.\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let mut s = String::from(\"hello\");\n    change(&mut s);\n    println!(\"{s}\");\n}\n\nfn change(some_string: &mut String) {\n    some_string.push_str(\", world\");\n}\n", "output": "hello, world"}, {"type": "text", "title": "The borrowing rules", "md": "At any given time, you can have **either**:\n\n- **any number of shared references** (`&T`), **or**\n- **exactly one mutable reference** (`&mut T`),\n\nbut not both. And every reference must always be **valid**.\n\n*Programming Rust* sums this up as \"sharing versus mutation\": you can share a value with many readers, or let one writer change it, but never both at once. The rule prevents a **data race**, where two pieces of code access the same data, at least one of them writes, and nothing orders the accesses. Data races cause unpredictable bugs that are very hard to reproduce. Rust rejects them at compile time.\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "fn main() {\n    let mut s = String::from(\"hello\");\n    let r1 = &mut s;\n    let r2 = &mut s;\n    println!(\"{r1}, {r2}\");\n}\n", "output": "error[E0499]: cannot borrow `s` as mutable more than once at a time\n --> src/main.rs:4:14\n  |\n3 |     let r1 = &mut s;\n  |              ------ first mutable borrow occurs here\n4 |     let r2 = &mut s;\n  |              ^^^^^^ second mutable borrow occurs here\n5 |     println!(\"{r1}, {r2}\");\n  |                -- first borrow later used here\n", "output_label": "Compiler output"}, {"type": "text", "title": "A borrow lasts until its last use", "md": "A reference's scope runs from where it is created to the **last place it is used**, not to the end of the block. The compiler figures this out (the feature is called *non-lexical lifetimes*). So this is fine, because the shared references are finished before the mutable one starts:\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let mut s = String::from(\"hello\");\n\n    let r1 = &s;\n    let r2 = &s;\n    println!(\"{r1} and {r2}\");\n    // r1 and r2 are not used after this point\n\n    let r3 = &mut s;\n    r3.push('!');\n    println!(\"{r3}\");\n}\n", "output": "hello and hello\nhello!\n"}, {"type": "playground", "id": "ch04-play-borrow-order", "title": "Reorder to satisfy the borrow checker", "lang": "rust", "md": "This program reads the first character through a shared reference, but changes the String while that reference is still needed. Run it and read the error. Fix it by **moving one line**, not by deleting anything or adding `clone()`. It should print `first: h` and then `hello!`.\n", "code": "fn main() {\n    let mut s = String::from(\"hello\");\n    let first = &s[0..1];\n    s.push('!');\n    println!(\"first: {first}\");\n    println!(\"{s}\");\n}\n", "expected_output": "first: h\nhello!\n", "hints": ["`&s[0..1]` is a reference into `s` (a slice, next lesson). `push` needs `&mut s`. Where is `first` last used?", "Move the `println!(\"first: {first}\");` line above `s.push('!');`."]}, {"type": "text", "title": "Dangling references are impossible", "md": "In C you can return a pointer to a local variable. The variable is freed when the function returns, and the pointer now **dangles**: it points to memory that may be reused for something else. Rust's compiler refuses to let a reference outlive the data it refers to:\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "fn dangle() -> &String {\n    let s = String::from(\"hello\");\n    &s\n}\n\nfn main() {\n    let reference_to_nothing = dangle();\n}\n", "output": "error[E0106]: missing lifetime specifier\n --> src/main.rs:1:16\n  |\n1 | fn dangle() -> &String {\n  |                ^ expected named lifetime parameter\n  |\n  = help: this function's return type contains a borrowed value, but there is no value for it to be borrowed from\nhelp: consider using the `'static` lifetime, but this is uncommon unless you're returning a borrowed value from a `const` or a `static`\n  |\n1 | fn dangle() -> &'static String {\n  |                 +++++++\nhelp: instead, you are more likely to want to return an owned value\n  |\n1 - fn dangle() -> &String {\n1 + fn dangle() -> String {\n", "output_label": "Compiler output", "explain": "The first help line is the key: the function returns a borrow, but there is nothing it could be borrowing from, because `s` dies when `dangle` returns. Ignore the `'static` suggestion; the last one is the real fix: return the `String` itself, moving ownership out. Lifetimes, the mechanism behind this check, get a full lesson in chapter 10."}, {"type": "callout", "kind": "tip", "title": "Which parameter type should a function take?", "md": "- Only needs to **read** the value: take `&T`. This is the most common choice.\n- Needs to **change** the caller's value: take `&mut T`.\n- Needs to **keep** the value, store it, or hand it on: take `T` (ownership).\n\nChoosing the weakest one that works keeps your functions easy to call.\n"}, {"type": "playground", "id": "ch04-play-borrow-fix", "title": "Borrow instead of move", "lang": "rust", "md": "The satellite check from lesson 1 again, the proper way. Change `check_status` to **borrow** the name, and `log_contact` to borrow it **mutably** and append `\" (contacted)\"`. The program should then print the lines shown in the task.\n", "task": "Print `sat-a: ok`, then `sat-a: ok` again, then `sat-a (contacted)`.", "code": "fn check_status(sat: String) -> &'static str {\n    if sat.is_empty() { \"unknown\" } else { \"ok\" }\n}\n\nfn log_contact(sat: String) {\n    sat.push_str(\" (contacted)\");\n}\n\nfn main() {\n    let sat_a = String::from(\"sat-a\");\n    println!(\"{sat_a}: {}\", check_status(sat_a));\n    println!(\"{sat_a}: {}\", check_status(sat_a));\n    log_contact(sat_a);\n    println!(\"{sat_a}\");\n}\n", "expected_output": "sat-a: ok\nsat-a: ok\nsat-a (contacted)\n", "hints": ["Parameter types: `sat: &String` and `sat: &mut String`.", "Call sites: `check_status(&sat_a)` and `log_contact(&mut sat_a)`. The variable needs `let mut`."]}, {"type": "text", "title": "Dereferencing with *", "md": "A reference is an address. Most of the time Rust follows it for you: method calls like `s.len()` and `println!` work through references automatically. When you need the value itself, for example to do arithmetic or to assign through a `&mut`, use the **dereference operator** `*`:\n"}, {"type": "code", "lang": "rust", "code": "fn add_bonus(score: &mut u32, bonus: u32) {\n    *score += bonus; // change the value the reference points to\n}\n\nfn main() {\n    let mut score = 40;\n    add_bonus(&mut score, 2);\n    let r = &score;\n    let doubled = *r * 2;\n    println!(\"{score} {doubled}\");\n}\n", "output": "42 84"}, {"type": "exercise", "id": "ch04-ex-borrowing", "exercise_dir": "ch04-borrowing", "title": "Read with &, change with &mut", "difficulty": "medium", "goal": "Choose the right kind of reference for each function, and use * where you need the value.", "behavior": "- `pub fn count_vowels(s: &String) -> usize`: how many of the characters are a, e, i, o or u (lowercase or uppercase).\n- `pub fn make_title(s: &mut String)`: change the String in place so that its first character is uppercase. An empty String stays empty.\n- `pub fn add_points(total: &mut u32, points: &[u32; 3])`: add all three points to `total`.\n- `pub fn longer<'a>(a: &'a String, b: &'a String) -> &'a String`: a reference to the longer of the two; if they have equal length, return `a`. (The `'a` is a lifetime annotation, explained in chapter 10; it is already written for you.)\n", "examples": [{"input": "count_vowels(&String::from(\"Rust in Action\"))", "output": "5"}, {"input": "make_title on \"ferris\"", "output": "\"Ferris\""}, {"input": "add_points(&mut 10, &[1, 2, 3])", "output": "total becomes 16"}], "hints": ["`for c in s.chars()` gives each `char`. `\"aeiouAEIOU\".contains(c)` checks if it is a vowel.", "`make_title`: if `s` is not empty, take the first char with `s.remove(0)` and put back its uppercase with `s.insert_str(0, &first.to_uppercase().to_string())`.", "`add_points`: `for p in points { *total += p; }`. Iterating a `&[u32; 3]` gives `&u32`, which `+=` accepts.", "`longer`: `if b.len() > a.len() { b } else { a }`."], "solution_explain": "Each signature tells the caller what happens to their data: `&String` promises only to read, `&mut String` warns that it will change. `to_uppercase` on a `char` returns several characters in general (the German ß becomes SS), which is why it is turned into a String before inserting.", "mode": "tests", "dir": "ch04-borrowing", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// Counts a, e, i, o, u in either case.\npub fn count_vowels(s: &String) -> usize {\n    todo!()\n}\n\n/// Uppercases the first character, in place.\npub fn make_title(s: &mut String) {\n    todo!()\n}\n\n/// Adds the three points to the total.\npub fn add_points(total: &mut u32, points: &[u32; 3]) {\n    todo!()\n}\n\n/// The longer String; `a` when they are the same length.\npub fn longer<'a>(a: &'a String, b: &'a String) -> &'a String {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch04_borrowing\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn vowels() {\n    assert_eq!(count_vowels(&String::from(\"Rust in Action\")), 5, \"Rust in Action: u, i, A, i, o\");\n    assert_eq!(count_vowels(&String::from(\"rhythm\")), 0, \"rhythm\");\n    assert_eq!(count_vowels(&String::from(\"AEIOU aeiou\")), 10, \"all vowels\");\n}\n\n#[test]\nfn vowels_do_not_take_ownership() {\n    let s = String::from(\"borrowed\");\n    let _ = count_vowels(&s);\n    assert_eq!(s, \"borrowed\", \"the caller still owns s\");\n}\n\n#[test]\nfn title() {\n    let mut s = String::from(\"ferris\");\n    make_title(&mut s);\n    assert_eq!(s, \"Ferris\", \"make_title(\\\"ferris\\\")\");\n    let mut already = String::from(\"Crab\");\n    make_title(&mut already);\n    assert_eq!(already, \"Crab\", \"already uppercase\");\n}\n\n#[test]\nfn title_of_empty() {\n    let mut s = String::new();\n    make_title(&mut s);\n    assert_eq!(s, \"\", \"empty stays empty\");\n}\n\n#[test]\nfn points() {\n    let mut total = 10;\n    add_points(&mut total, &[1, 2, 3]);\n    assert_eq!(total, 16, \"10 + 1 + 2 + 3\");\n    add_points(&mut total, &[0, 0, 4]);\n    assert_eq!(total, 20, \"a second call keeps adding\");\n}\n\n#[test]\nfn longest() {\n    let a = String::from(\"orbit\");\n    let b = String::from(\"constellation\");\n    assert_eq!(longer(&a, &b), \"constellation\");\n    let c = String::from(\"12345\");\n    assert!(std::ptr::eq(longer(&a, &c), &a), \"a tie returns the first argument\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// Counts a, e, i, o, u in either case.\npub fn count_vowels(s: &String) -> usize {\n    let mut count = 0;\n    for c in s.chars() {\n        if \"aeiouAEIOU\".contains(c) {\n            count += 1;\n        }\n    }\n    count\n}\n\n/// Uppercases the first character, in place.\npub fn make_title(s: &mut String) {\n    if s.is_empty() {\n        return;\n    }\n    let first = s.remove(0);\n    s.insert_str(0, &first.to_uppercase().to_string());\n}\n\n/// Adds the three points to the total.\npub fn add_points(total: &mut u32, points: &[u32; 3]) {\n    for p in points {\n        *total += p;\n    }\n}\n\n/// The longer String; `a` when they are the same length.\npub fn longer<'a>(a: &'a String, b: &'a String) -> &'a String {\n    if b.len() > a.len() { b } else { a }\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch04-quiz-references", "title": "Check yourself", "questions": [{"type": "single", "q": "What does `&s1` do in `calculate_length(&s1)`?", "options": ["Copies the String", "Moves the String into the function", "Creates a reference that borrows `s1` without taking ownership", "Takes the address and frees `s1`"], "answer": 2, "explanation": "A reference borrows: the function can read `s1`, and `s1` stays valid afterwards.", "hints": []}, {"type": "multi", "q": "Which combinations can exist at the same moment for one variable `s`?", "options": ["Three `&s`", "One `&mut s`", "Two `&mut s`", "One `&s` and one `&mut s`"], "answer": [0, 1], "explanation": "Many readers or one writer, never both, and never two writers.", "hints": []}, {"type": "single", "q": "Does this compile?", "code": "let mut s = String::from(\"hi\");\nlet r = &s;\nprintln!(\"{r}\");\ns.push('!');\n", "lang": "rust", "options": ["Yes: `r` is no longer used when `s` is changed", "No: `r` is still in scope", "No: `s` cannot be `mut` if borrowed", "Only with `clone()`"], "answer": 0, "explanation": "A borrow ends at its last use, so `push` is fine after the `println!`.", "hints": []}, {"type": "single", "q": "Why can't a function return a reference to a String it created inside itself?", "options": ["Strings cannot be returned", "The String is dropped when the function ends, so the reference would dangle", "References can only be parameters", "It needs `&mut`"], "answer": 1, "explanation": "Return the `String` itself instead, moving ownership to the caller.", "hints": []}, {"type": "fill", "q": "Inside `fn inc(n: &mut i32)`, the line that adds 1 to the caller's number is `___n += 1;`", "answer": ["*"], "explanation": "`*n` dereferences the reference to reach the number.", "hints": []}, {"type": "single", "q": "A function only needs to look at a `Vec<String>`. Which parameter type is best?", "options": ["`Vec<String>`", "`&Vec<String>`", "`&mut Vec<String>`", "`Vec<&String>`"], "answer": 1, "explanation": "Reading needs only a shared reference. (Chapter 8 shows that `&[String]` is even more flexible.)", "hints": []}]}, {"type": "summary", "points": ["A reference `&x` borrows a value without owning it; nothing is dropped when the reference goes away.", "`&mut x` allows changing the borrowed value; the variable must be `let mut`.", "At any moment: many shared references **or** one mutable reference.", "A borrow lasts until its last use, not to the end of the block.", "References can never dangle: the compiler rejects any reference that would outlive its data.", "`*r` dereferences; method calls and `println!` dereference automatically.", "Take `&T` to read, `&mut T` to change, `T` to keep."]}], "terms": [{"term": "reference", "def": "A pointer that is guaranteed to point to a valid value of a given type, written &T or &mut T."}, {"term": "borrowing", "def": "Creating a reference to a value owned by someone else."}, {"term": "mutable reference", "def": "A reference (&mut T) that allows changing the value; only one can exist at a time, and no shared references alongside it."}, {"term": "data race", "def": "Two accesses to the same data at the same time, at least one a write, with nothing ordering them. Rust rejects these at compile time."}, {"term": "dangling reference", "def": "A reference to memory that has been freed. Impossible in safe Rust."}, {"term": "dereference", "def": "Following a reference to the value it points to, with the * operator."}, {"term": "borrow checker", "def": "The part of the compiler that checks every reference against the ownership and borrowing rules."}], "id": "ch04-02-references", "chapter": "ch04", "kind": "lesson"}, "ch04-03-slices": {"title": "Slices: borrowing part of a collection", "summary": "Refer to a run of elements instead of the whole: string slices (&str), why string literals are slices, array slices (&[T]), and why slices make APIs both safer and more flexible.", "minutes": 28, "source": {"chapter": "ch04", "sections": ["TRPL 4.3 The Slice Type", "TRPL 4.3 String Slices", "TRPL 4.3 String Literals as Slices", "TRPL 4.3 String Slices as Parameters", "TRPL 4.3 Other Slices", "PR ch3 Slices", "PR ch3 String Literals", "CR Day 1 Slices"]}, "blocks": [{"type": "text", "md": "A **slice** is a reference to a contiguous run of elements in a collection, rather than the whole collection. Because it is a reference, it does not own anything. This lesson follows *The Rust Programming Language*'s example, a function that finds the first word of a sentence, and shows how slices turn a subtle bug into a compile error.\n"}, {"type": "text", "title": "The problem", "md": "Write a function that takes a string of words separated by spaces and returns the first word. Without slices, the best we can return is the **index** where the first word ends:\n"}, {"type": "code", "lang": "rust", "code": "fn first_word(s: &String) -> usize {\n    let bytes = s.as_bytes();\n    for (i, &item) in bytes.iter().enumerate() {\n        if item == b' ' {\n            return i;\n        }\n    }\n    s.len()\n}\n\nfn main() {\n    let mut s = String::from(\"hello world\");\n    let word = first_word(&s); // word = 5\n    s.clear();                 // empties the String\n    println!(\"{word}\");        // 5, but there is no word any more!\n}\n", "output": "5", "explain": "`as_bytes` gives the String's bytes; `enumerate` pairs each with its index; `b' '` is the byte for a space. The bug: `word` is just a number with no connection to `s`. After `s.clear()` the number is meaningless, and nothing warns us. Keeping such indexes in sync by hand is fragile."}, {"type": "text", "title": "String slices", "md": "A **string slice** is a reference to part of a String, written with a range in brackets:\n"}, {"type": "code", "lang": "rust", "code": "fn main() {\n    let s = String::from(\"hello world\");\n    let hello = &s[0..5];\n    let world = &s[6..11];\n    let all = &s[..];      // the whole string\n    let start = &s[..2];   // from the beginning: \"he\"\n    let end = &s[8..];     // to the end: \"rld\"\n    println!(\"{hello}|{world}|{all}|{start}|{end}\");\n}\n", "output": "hello|world|hello world|he|rld", "explain": "`[a..b]` includes `a` and stops before `b`; either end can be left out. Internally a slice stores a pointer to the starting byte and a length, so `world` points at byte 6 of `s` with length 5."}, {"type": "callout", "kind": "warning", "title": "Slice indexes are bytes, not characters", "md": "String slice ranges count **bytes** of UTF-8. Slicing in the middle of a multi-byte character, like `&\"Здравствуйте\"[0..1]` (each Cyrillic letter is 2 bytes), panics with `byte index 1 is not a char boundary`. For ASCII text bytes and characters are the same; chapter 8 shows how to work with characters safely."}, {"type": "text", "title": "first_word, fixed", "md": "The type of a string slice is written `&str`. Returning one ties the result to the String it came from:\n"}, {"type": "code", "lang": "rust", "code": "fn first_word(s: &String) -> &str {\n    let bytes = s.as_bytes();\n    for (i, &item) in bytes.iter().enumerate() {\n        if item == b' ' {\n            return &s[0..i];\n        }\n    }\n    &s[..]\n}\n\nfn main() {\n    let s = String::from(\"hello world\");\n    let word = first_word(&s);\n    println!(\"the first word is: {word}\");\n}\n", "output": "the first word is: hello"}, {"type": "text", "md": "Now try the bug from before. `word` is a shared borrow of `s`, and `s.clear()` needs a mutable borrow while `word` is still used. The borrowing rules from the last lesson forbid exactly that, so the compiler catches the bug:\n"}, {"type": "code", "lang": "rust", "file": "src/main.rs", "code": "fn first_word(s: &String) -> &str {\n    &s[..s.find(' ').unwrap_or(s.len())]\n}\n\nfn main() {\n    let mut s = String::from(\"hello world\");\n    let word = first_word(&s);\n    s.clear();\n    println!(\"the first word is: {word}\");\n}\n", "output": "error[E0502]: cannot borrow `s` as mutable because it is also borrowed as immutable\n --> src/main.rs:8:5\n  |\n7 |     let word = first_word(&s);\n  |                           -- immutable borrow occurs here\n8 |     s.clear();\n  |     ^^^^^^^^^ mutable borrow occurs here\n9 |     println!(\"the first word is: {word}\");\n  |                                   ---- immutable borrow later used here\n", "output_label": "Compiler output", "explain": "`s.find(' ')` returns the byte index of the first space, or `None`; `unwrap_or(s.len())` uses the full length when there is no space. It is a shorter way to write the loop above."}, {"type": "text", "title": "String literals are slices", "md": "Remember `let s = \"Hello, world!\";`? The type of `s` is `&str`: a slice pointing to text stored inside the program's binary. That is why literals are immutable: `&str` is a shared reference.\n\nThis also means a function that takes `&str` can accept both literals and Strings, because a `&String` converts to a `&str` automatically (this is called **deref coercion**, chapter 15). So the better signature for `first_word` is:\n\n```rust\nfn first_word(s: &str) -> &str\n```\n"}, {"type": "code", "lang": "rust", "code": "fn first_word(s: &str) -> &str {\n    &s[..s.find(' ').unwrap_or(s.len())]\n}\n\nfn main() {\n    let my_string = String::from(\"hello world\");\n    println!(\"{}\", first_word(&my_string[0..6])); // a slice of a String\n    println!(\"{}\", first_word(&my_string));       // a whole String\n    println!(\"{}\", first_word(\"hi there\"));       // a literal\n}\n", "output": "hello\nhello\nhi\n"}, {"type": "callout", "kind": "key", "title": "&str versus String", "md": "`String` owns growable text on the heap. `&str` borrows some text that lives elsewhere: in a String, in the binary, anywhere. Store `String` in your data; take `&str` as a parameter when you only read text. This is one of the most common pairs of types you will use."}, {"type": "playground", "id": "ch04-play-last-word", "title": "Write last_word", "lang": "rust", "md": "Write `last_word`, returning a slice of everything after the last space (or the whole text when there is no space). `rfind` is like `find` but searches from the end. The program should print the three lines in the task.\n", "task": "Print `world`, `Ferris` and `crab`, one per line.", "code": "fn last_word(s: &str) -> &str {\n    s // replace with a slice after the last space\n}\n\nfn main() {\n    println!(\"{}\", last_word(\"hello world\"));\n    println!(\"{}\", last_word(\"Ferris\"));\n    let owned = String::from(\"Ferris the crab\");\n    println!(\"{}\", last_word(&owned));\n}\n", "expected_output": "world\nFerris\ncrab\n", "hints": ["`s.rfind(' ')` returns `Some(index)` of the last space, or `None`.", "The word starts one byte after the space: `&s[i + 1..]`. Use `match` as in the guessing game, or `if let Some(i) = s.rfind(' ')`."]}, {"type": "text", "title": "Other slices", "md": "Slices are not just for text. A slice of an array (or, later, a `Vec`) has type `&[T]`, and `&mut [T]` is a slice you can change. Functions that take `&[T]` work for arrays of any length, which plain arrays cannot do because the length is part of their type.\n"}, {"type": "code", "lang": "rust", "code": "fn sum(values: &[i32]) -> i32 {\n    let mut total = 0;\n    for v in values {\n        total += v;\n    }\n    total\n}\n\nfn double_all(values: &mut [i32]) {\n    for v in values {\n        *v *= 2;\n    }\n}\n\nfn main() {\n    let mut a = [1, 2, 3, 4, 5];\n    println!(\"{}\", sum(&a));        // the whole array\n    println!(\"{}\", sum(&a[1..3]));  // [2, 3]\n    double_all(&mut a[3..]);        // only the last two\n    println!(\"{a:?}\");\n}\n", "output": "15\n5\n[1, 2, 3, 8, 10]\n"}, {"type": "flashcards", "id": "ch04-cards-slices", "title": "Ownership and borrowing vocabulary", "cards": [{"front": "`String`", "back": "Owned, growable UTF-8 text on the heap."}, {"front": "`&str`", "back": "A borrowed string slice: pointer + length into text owned elsewhere. String literals have this type."}, {"front": "`&[T]`", "back": "A borrowed slice of elements of type T, from an array, a Vec or another slice."}, {"front": "`&mut [T]`", "back": "A mutable slice: lets a function change elements, but not add or remove them."}, {"front": "`&s[2..5]`", "back": "A slice of bytes 2, 3 and 4 of `s`."}, {"front": "E0502", "back": "Cannot borrow as mutable because it is also borrowed as immutable: a shared borrow is still in use."}, {"front": "E0382", "back": "Use of a moved value."}]}, {"type": "exercise", "id": "ch04-ex-slices", "exercise_dir": "ch04-slices", "title": "Slicing text and numbers", "difficulty": "medium", "goal": "Write functions that take and return slices, so they work on Strings, literals, arrays and parts of them.", "behavior": "- `pub fn first_word(s: &str) -> &str`: everything before the first space (the whole text if there is none).\n- `pub fn nth_word(s: &str, n: usize) -> Option<&str>`: the n-th word (0-based) when words are separated by single spaces, or `None` if there are fewer words.\n- `pub fn largest(values: &[i32]) -> Option<i32>`: the largest value, or `None` for an empty slice.\n- `pub fn zero_negatives(values: &mut [i32])`: replace every negative number with 0, in place.\n", "examples": [{"input": "first_word(\"ground control\")", "output": "\"ground\""}, {"input": "nth_word(\"to be or not\", 2)", "output": "Some(\"or\")"}, {"input": "largest(&[3, 9, -1])", "output": "Some(9)"}, {"input": "zero_negatives on [4, -2, 0, -7]", "output": "[4, 0, 0, 0]"}], "hints": ["`first_word`: `&s[..s.find(' ').unwrap_or(s.len())]`.", "`nth_word`: `s.split(' ')` gives the words one by one; count them in a `for` loop with a counter, and `return Some(word)` when the counter equals `n`. After the loop, `None`.", "`largest`: return `None` if `values.is_empty()`, else start from `values[0]` and loop.", "`zero_negatives`: `for v in values { if *v < 0 { *v = 0; } }`."], "solution_explain": "Every function borrows, so callers keep ownership and can pass whole collections or parts of them. `for &v in values` destructures each `&i32` into an `i32`. Later chapters replace these loops with iterator methods such as `s.split(' ').nth(n)` and `values.iter().max()`.", "mode": "tests", "dir": "ch04-slices", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// Everything before the first space.\npub fn first_word(s: &str) -> &str {\n    todo!()\n}\n\n/// The n-th word (0-based), if there is one.\npub fn nth_word(s: &str, n: usize) -> Option<&str> {\n    todo!()\n}\n\n/// The largest value, or None when the slice is empty.\npub fn largest(values: &[i32]) -> Option<i32> {\n    todo!()\n}\n\n/// Sets every negative value to 0.\npub fn zero_negatives(values: &mut [i32]) {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch04_slices\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn first_words() {\n    assert_eq!(first_word(\"ground control\"), \"ground\");\n    assert_eq!(first_word(\"single\"), \"single\", \"no space: the whole text\");\n    assert_eq!(first_word(\"\"), \"\", \"empty text\");\n    let owned = String::from(\"major tom\");\n    assert_eq!(first_word(&owned), \"major\", \"works with a &String too\");\n}\n\n#[test]\nfn nth_words() {\n    assert_eq!(nth_word(\"to be or not\", 0), Some(\"to\"));\n    assert_eq!(nth_word(\"to be or not\", 2), Some(\"or\"));\n    assert_eq!(nth_word(\"to be or not\", 3), Some(\"not\"));\n    assert_eq!(nth_word(\"to be or not\", 4), None, \"only four words\");\n}\n\n#[test]\nfn largest_values() {\n    assert_eq!(largest(&[3, 9, -1]), Some(9));\n    assert_eq!(largest(&[-5, -2, -9]), Some(-2), \"all negative\");\n    assert_eq!(largest(&[]), None, \"empty slice\");\n    let a = [1, 50, 2, 99];\n    assert_eq!(largest(&a[..3]), Some(50), \"only part of an array\");\n}\n\n#[test]\nfn zeroing() {\n    let mut v = [4, -2, 0, -7];\n    zero_negatives(&mut v);\n    assert_eq!(v, [4, 0, 0, 0]);\n    let mut w = [-1, -1, -1, -1];\n    zero_negatives(&mut w[2..]);\n    assert_eq!(w, [-1, -1, 0, 0], \"only the slice is changed\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// Everything before the first space.\npub fn first_word(s: &str) -> &str {\n    &s[..s.find(' ').unwrap_or(s.len())]\n}\n\n/// The n-th word (0-based), if there is one.\npub fn nth_word(s: &str, n: usize) -> Option<&str> {\n    let mut i = 0;\n    for word in s.split(' ') {\n        if i == n {\n            return Some(word);\n        }\n        i += 1;\n    }\n    None\n}\n\n/// The largest value, or None when the slice is empty.\npub fn largest(values: &[i32]) -> Option<i32> {\n    if values.is_empty() {\n        return None;\n    }\n    let mut max = values[0];\n    for &v in values {\n        if v > max {\n            max = v;\n        }\n    }\n    Some(max)\n}\n\n/// Sets every negative value to 0.\npub fn zero_negatives(values: &mut [i32]) {\n    for v in values {\n        if *v < 0 {\n            *v = 0;\n        }\n    }\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch04-quiz-slices", "title": "Check yourself", "questions": [{"type": "single", "q": "`let s = String::from(\"rustacean\");` What is `&s[4..]`?", "options": ["\"rust\"", "\"acean\"", "\"tacean\"", "\"cean\""], "answer": 1, "explanation": "Bytes 4 to the end: r-u-s-t are 0 to 3, so the slice starts at `a`.", "hints": []}, {"type": "single", "q": "What is the type of the literal `\"hi\"`?", "options": ["`String`", "`&String`", "`&str`", "`[char; 2]`"], "answer": 2, "explanation": "A string literal is a slice of text stored in the binary.", "hints": []}, {"type": "single", "q": "Why is `fn f(s: &str)` usually better than `fn f(s: &String)`?", "options": ["`&str` is faster to copy", "It accepts both literals and Strings (and slices of them)", "`&String` cannot be read", "`&str` can be changed"], "answer": 1, "explanation": "A `&String` coerces to `&str`, but not the other way round, so `&str` accepts more.", "hints": []}, {"type": "truefalse", "q": "Holding a slice of a String while calling `clear()` on that String compiles, and the slice becomes empty.", "answer": false, "explanation": "The slice is a shared borrow; `clear` needs a mutable one. The compiler reports E0502.", "hints": []}, {"type": "single", "q": "Which signature lets a function sum arrays of **any** length?", "options": ["`fn sum(a: [i32; 5]) -> i32`", "`fn sum(a: &[i32; 5]) -> i32`", "`fn sum(a: &[i32]) -> i32`", "`fn sum(a: i32...) -> i32`"], "answer": 2, "explanation": "A slice type has no length in it, so any array (or part of one) fits.", "hints": []}, {"type": "single", "q": "What happens with `&\"héllo\"[0..2]`? (`é` takes 2 bytes)", "options": ["Returns \"hé\"", "Returns \"h\" and half of é", "Panics: byte index 2 is not a char boundary", "Compile error"], "answer": 2, "explanation": "Byte 2 falls inside `é` (bytes 1 and 2), and string slices must start and end on character boundaries.", "hints": []}]}, {"type": "summary", "points": ["A slice borrows a contiguous part of a collection: `&s[a..b]`, `&s[..b]`, `&s[a..]`, `&s[..]`.", "`&str` is a string slice; string literals are `&str`.", "Returning a slice ties it to its source, so the borrow checker catches uses after the source changes.", "Prefer `&str` parameters to `&String`, and `&[T]` to `&[T; N]` or `&Vec<T>`.", "String slice indexes are byte positions and must fall on character boundaries.", "`&mut [T]` lets a function change elements in place."]}], "terms": [{"term": "slice", "def": "A reference to a contiguous sequence of elements in a collection: a pointer and a length."}, {"term": "&str", "def": "A string slice: borrowed UTF-8 text. String literals have this type."}, {"term": "deref coercion", "def": "Automatic conversion of a reference to another reference type, such as &String to &str."}], "id": "ch04-03-slices", "chapter": "ch04", "kind": "lesson"}, "ch04-99-test": {"title": "Chapter test: Ownership, Borrowing and Slices", "kind": "test", "summary": "Twelve questions on moves, copies, references, the borrowing rules and slices. You need 70% to pass; you can retry and your best score is kept.", "blocks": [{"type": "quiz", "id": "ch04-test", "pass_score": 0.7, "questions": [{"type": "single", "q": "Which of these is **not** one of the ownership rules?", "options": ["Each value has an owner", "There is only one owner at a time", "When the owner goes out of scope, the value is dropped", "A value can be read by only one variable at a time"], "answer": 3, "explanation": "Many shared references can read a value at once. Only ownership is exclusive.", "hints": []}, {"type": "single", "q": "Does this compile?", "code": "let a = (1, 2.5);\nlet b = a;\nprintln!(\"{a:?} {b:?}\");\n", "lang": "rust", "options": ["Yes: the tuple is `Copy`", "No: `a` was moved", "No: tuples cannot be printed", "Only with `clone()`"], "answer": 0, "explanation": "A tuple of `Copy` types is `Copy`, so `a` is still usable.", "hints": []}, {"type": "single", "q": "Does this compile?", "code": "let a = (1, String::from(\"x\"));\nlet b = a;\nprintln!(\"{}\", a.0);\n", "lang": "rust", "options": ["Yes: `a.0` is an `i32`", "No: `a` was moved as a whole", "Yes: only the String moved", "No: tuples are always moved"], "answer": 1, "explanation": "The tuple contains a String, so it is not `Copy`; `let b = a;` moves the whole tuple.", "hints": []}, {"type": "single", "q": "How many times is the heap text of `s` freed?", "code": "fn keep(s: String) -> String { s }\nfn main() {\n    let s = String::from(\"orbit\");\n    let t = keep(s);\n    let u = t;\n}\n", "lang": "rust", "options": ["Zero", "Once", "Twice", "Three times"], "answer": 1, "explanation": "Ownership moves `s` → parameter → `t` → `u`. Only the final owner, `u`, drops it, once.", "hints": []}, {"type": "multi", "q": "Which lines are allowed at the marked point, given `let mut v = String::new(); let r = &v;` and that `r` is used after the marked point?", "options": ["`let r2 = &v;`", "`v.push('a');`", "`let m = &mut v;`", "`println!(\"{v}\");`"], "answer": [0, 3], "explanation": "While a shared borrow is alive, more shared reads are fine; any mutable borrow is not.", "hints": []}, {"type": "single", "q": "Which signature is best for a function that appends a timestamp to the caller's String?", "options": ["`fn stamp(s: String)`", "`fn stamp(s: &String)`", "`fn stamp(s: &mut String)`", "`fn stamp(s: &str)`"], "answer": 2, "explanation": "It changes the caller's value but does not need to own it.", "hints": []}, {"type": "fill", "q": "The error code for \"cannot borrow as mutable because it is also borrowed as immutable\" is E0___.", "answer": ["502"], "explanation": "E0502. E0499 is two mutable borrows; E0382 is use after move.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "fn bump(n: &mut i32) { *n += 10; }\nfn main() {\n    let mut x = 1;\n    bump(&mut x);\n    bump(&mut x);\n    println!(\"{x}\");\n}\n", "lang": "rust", "options": ["1", "11", "21", "It does not compile"], "answer": 2, "explanation": "Each mutable borrow ends when `bump` returns, so two calls in a row are fine: 1 + 10 + 10.", "hints": []}, {"type": "single", "q": "`let s = String::from(\"hello world\"); let w = &s[6..];` What is `w`?", "options": ["\"hello\"", "\" world\"", "\"world\"", "\"orld\""], "answer": 2, "explanation": "Byte 6 is `w`; the slice runs to the end.", "hints": []}, {"type": "truefalse", "q": "A function returning `&str` that points into its own local `String` compiles if the String is long enough.", "answer": false, "explanation": "The local String is dropped when the function returns; the slice would dangle, so the compiler rejects it.", "hints": []}, {"type": "single", "q": "Which call does **not** compile for `fn count(s: &str) -> usize`?", "options": ["`count(\"abc\")`", "`count(&String::from(\"abc\"))`", "`count(String::from(\"abc\"))`", "`count(&\"abcdef\"[..3])`"], "answer": 2, "explanation": "A `String` value is not a reference. Pass `&string` and it coerces to `&str`.", "hints": []}, {"type": "order", "q": "Order what happens in `let s1 = String::from(\"hi\"); let s2 = s1; println!(\"{s2}\");` from the first step to the last.", "items": ["The allocator gives heap memory for \"hi\"", "Pointer, length and capacity are copied into s2", "s1 is marked as moved", "s2 is printed", "s2 goes out of scope and the heap memory is freed"], "explanation": "One allocation, one cheap move, one free at the end of the owner's scope.", "hints": []}], "mode": "test"}], "id": "ch04-99-test", "chapter": "ch04", "minutes": 10}, "ch05-01-define": {"title": "Defining and creating structs", "summary": "Named fields, instances, mutable instances, field init shorthand, struct update syntax, tuple structs, unit-like structs, and who owns a struct's fields.", "minutes": 26, "source": {"chapter": "ch05", "sections": ["TRPL 5.1 Defining and Instantiating Structs", "TRPL 5.1 Using the Field Init Shorthand", "TRPL 5.1 Creating Instances with Struct Update Syntax", "TRPL 5.1 Tuple Structs", "TRPL 5.1 Unit-Like Structs", "TRPL 5.1 Ownership of Struct Data", "PR ch9 Named-Field Structs", "PR ch9 Tuple-Like Structs", "PR ch9 Unit-Like Structs", "CR Day 1 Afternoon Structs"]}, "blocks": [{"type": "text", "md": "A tuple groups values by position. A **struct** groups them by **name**. Each piece of data in a struct is a **field**, with a name and a type, so code that uses it reads `user.email` instead of `user.2`. Structs are how you model the things your program is about: a user, a rectangle, a file, a satellite. With enums (next chapter) they are the building blocks of every Rust program's data.\n"}, {"type": "code", "lang": "rust", "title": "Defining a struct and creating an instance", "code": "struct User {\n    active: bool,\n    username: String,\n    email: String,\n    sign_in_count: u64,\n}\n\nfn main() {\n    let user1 = User {\n        active: true,\n        username: String::from(\"someusername123\"),\n        email: String::from(\"someone@example.com\"),\n        sign_in_count: 1,\n    };\n    println!(\"{} <{}>, {} sign-in(s), active: {}\",\n        user1.username, user1.email, user1.sign_in_count, user1.active);\n}\n", "output": "someusername123 <someone@example.com>, 1 sign-in(s), active: true", "explain": "The definition is a template; an **instance** fills in concrete values. Fields can be listed in any order when creating an instance. Struct names use **UpperCamelCase**, field names use snake_case."}, {"type": "text", "title": "Changing fields", "md": "To change a field, the whole instance must be mutable: `let mut user1 = User { ... };` then `user1.email = String::from(\"new@example.com\");`. Rust does not let you mark only some fields as mutable. Mutability belongs to the variable, not to the type.\n"}, {"type": "text", "title": "Field init shorthand", "md": "A function that builds a struct often has parameters with the same names as the fields. Then you can write the name once:\n"}, {"type": "code", "lang": "rust", "code": "fn build_user(email: String, username: String) -> User {\n    User {\n        active: true,\n        username,       // same as username: username\n        email,          // same as email: email\n        sign_in_count: 1,\n    }\n}\n"}, {"type": "text", "title": "Struct update syntax", "md": "To create an instance that is mostly a copy of another, list the fields that differ and finish with `..other`:\n"}, {"type": "code", "lang": "rust", "code": "let user2 = User {\n    email: String::from(\"another@example.com\"),\n    ..user1\n};\n", "explain": "`..user1` takes every remaining field from `user1`. It works like assignment, so it **moves** data: `user1.username` (a String) moves into `user2`, and `user1` can no longer be used as a whole. `active` and `sign_in_count` are `Copy`, and `user1.email` was not used, so those fields of `user1` would still be readable on their own."}, {"type": "playground", "id": "ch05-play-update", "title": "Struct update and moves", "lang": "rust", "md": "Run it: the last `println!` fails because `user1.username` moved into `user2`. Fix it by giving `user2` its own `username` (for example `String::from(\"other\")`), so nothing is moved out of `user1` except `Copy` fields. The program should print the two lines in the task.\n", "task": "Print `ferris (2 sign-ins)` and then `other (2 sign-ins)`.", "code": "struct User {\n    username: String,\n    sign_in_count: u64,\n}\n\nfn main() {\n    let user1 = User { username: String::from(\"ferris\"), sign_in_count: 2 };\n    let user2 = User { ..user1 };\n    println!(\"{} ({} sign-ins)\", user1.username, user1.sign_in_count);\n    println!(\"{} ({} sign-ins)\", user2.username, user2.sign_in_count);\n}\n", "expected_output": "ferris (2 sign-ins)\nother (2 sign-ins)\n", "hints": ["`User { username: String::from(\"other\"), ..user1 }` copies only `sign_in_count`, which is `Copy`."]}, {"type": "text", "title": "Tuple structs", "md": "A **tuple struct** has a name but unnamed fields. Use one when naming each field would add nothing, but you want a distinct type. `Color` and `Point` below hold the same three numbers, yet you cannot pass a `Point` where a `Color` is expected. This is the **newtype** idea: wrapping a value in its own type so the compiler keeps different meanings apart.\n"}, {"type": "code", "lang": "rust", "code": "struct Color(i32, i32, i32);\nstruct Point(i32, i32, i32);\nstruct Meters(f64);\n\nfn main() {\n    let black = Color(0, 0, 0);\n    let origin = Point(0, 0, 0);\n    let Point(x, y, z) = origin;       // destructure with the type name\n    let height = Meters(1.8);\n    println!(\"{} {x}{y}{z} {}\", black.0, height.0);\n}\n", "output": "0 000 1.8", "explain": "Fields are reached by position (`black.0`) or by destructuring. A function `fn climb(by: Meters)` can never be called with feet or seconds by mistake, even though both are plain numbers underneath."}, {"type": "text", "title": "Unit-like structs", "md": "A struct can have no fields at all: `struct AlwaysEqual;`. It holds no data, so it takes no memory. That sounds useless, but it becomes handy with traits (chapter 10), where you want a type that has behavior but no state.\n"}, {"type": "text", "title": "Who owns the fields", "md": "`User` uses `String` rather than `&str` for its text. That is deliberate: each instance **owns** all its data, and the data lives exactly as long as the instance. A struct can hold references, but then the compiler needs to know the referenced data lives long enough, which requires **lifetimes** (chapter 10). Try it now and you get `error[E0106]: missing lifetime specifier`. Until then, give your structs owned types.\n"}, {"type": "exercise", "id": "ch05-ex-define", "exercise_dir": "ch05-structs", "title": "Model a book in a library", "difficulty": "easy", "goal": "Define a struct, build instances with shorthand and update syntax, and use a newtype.", "behavior": "The starter defines `pub struct Isbn(pub String);` and an empty `pub struct Book`. Complete it and the functions:\n- `Book` has public fields `title: String`, `author: String`, `isbn: Isbn`, `year: u16`, `available: bool`.\n- `pub fn new_book(title: String, author: String, isbn: Isbn, year: u16) -> Book`: a book that is available. Use field init shorthand.\n- `pub fn second_edition(book: &Book, isbn: Isbn, year: u16) -> Book`: a new book with the same title and author (cloned), the new ISBN and year, and available.\n- `pub fn describe(book: &Book) -> String`: `\"<title> by <author> (<year>)\"`, plus `\" [on loan]\"` when not available.\n", "examples": [{"input": "describe(&new_book(\"Dune\".into(), \"Frank Herbert\".into(), Isbn(\"978-0441013593\".into()), 1965))", "output": "\"Dune by Frank Herbert (1965)\""}], "hints": ["Fields in a struct are private outside their module unless marked `pub`. The tests are a separate module, so write `pub title: String,` and so on.", "`second_edition`: `Book { title: book.title.clone(), author: book.author.clone(), isbn, year, available: true }`.", "`describe`: `let mut s = format!(\"{} by {} ({})\", book.title, book.author, book.year);` then push the loan note if needed."], "solution_explain": "`second_edition` borrows the original, so it must clone the Strings it reuses; `..*book` would try to move them out of a borrow and fail. `format!` works like `println!` but returns the String instead of printing it.", "mode": "tests", "dir": "ch05-structs", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// An International Standard Book Number.\npub struct Isbn(pub String);\n\n/// A book in the library. Add the fields: title, author, isbn, year, available.\npub struct Book {\n}\n\n/// A new, available book.\npub fn new_book(title: String, author: String, isbn: Isbn, year: u16) -> Book {\n    todo!()\n}\n\n/// Same title and author, a new ISBN and year.\npub fn second_edition(book: &Book, isbn: Isbn, year: u16) -> Book {\n    todo!()\n}\n\n/// \"Title by Author (year)\", with \" [on loan]\" if it is not available.\npub fn describe(book: &Book) -> String {\n    todo!()\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch05_structs\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\nfn dune() -> Book {\n    new_book(String::from(\"Dune\"), String::from(\"Frank Herbert\"), Isbn(String::from(\"978-0441013593\")), 1965)\n}\n\n#[test]\nfn new_books_are_available() {\n    let b = dune();\n    assert_eq!(b.title, \"Dune\");\n    assert_eq!(b.author, \"Frank Herbert\");\n    assert_eq!(b.isbn.0, \"978-0441013593\");\n    assert_eq!(b.year, 1965);\n    assert!(b.available, \"a new book is available\");\n}\n\n#[test]\nfn describing() {\n    let mut b = dune();\n    assert_eq!(describe(&b), \"Dune by Frank Herbert (1965)\");\n    b.available = false;\n    assert_eq!(describe(&b), \"Dune by Frank Herbert (1965) [on loan]\");\n}\n\n#[test]\nfn new_edition_keeps_the_original() {\n    let mut first = dune();\n    first.available = false;\n    let second = second_edition(&first, Isbn(String::from(\"978-0593099322\")), 2019);\n    assert_eq!(describe(&second), \"Dune by Frank Herbert (2019)\", \"the new edition is available\");\n    assert_eq!(second.isbn.0, \"978-0593099322\");\n    assert_eq!(describe(&first), \"Dune by Frank Herbert (1965) [on loan]\", \"the first edition is unchanged\");\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// An International Standard Book Number.\npub struct Isbn(pub String);\n\n/// A book in the library.\npub struct Book {\n    pub title: String,\n    pub author: String,\n    pub isbn: Isbn,\n    pub year: u16,\n    pub available: bool,\n}\n\n/// A new, available book.\npub fn new_book(title: String, author: String, isbn: Isbn, year: u16) -> Book {\n    Book { title, author, isbn, year, available: true }\n}\n\n/// Same title and author, a new ISBN and year.\npub fn second_edition(book: &Book, isbn: Isbn, year: u16) -> Book {\n    Book {\n        title: book.title.clone(),\n        author: book.author.clone(),\n        isbn,\n        year,\n        available: true,\n    }\n}\n\n/// \"Title by Author (year)\", with \" [on loan]\" if it is not available.\npub fn describe(book: &Book) -> String {\n    let mut s = format!(\"{} by {} ({})\", book.title, book.author, book.year);\n    if !book.available {\n        s.push_str(\" [on loan]\");\n    }\n    s\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch05-quiz-define", "title": "Check yourself", "questions": [{"type": "single", "q": "How do you make only the `email` field of a struct instance changeable?", "options": ["`mut email: String` in the struct", "`let user.email = mut ...`", "You cannot: the whole instance must be `mut`", "Use `&mut email`"], "answer": 2, "explanation": "Mutability belongs to the binding: `let mut user = ...` makes every field changeable.", "hints": []}, {"type": "single", "q": "What does field init shorthand let you write?", "options": ["`User { email }` instead of `User { email: email }`", "`User(email)` instead of `User { email }`", "`..user1` to copy fields", "`user.0` instead of `user.email`"], "answer": 0, "explanation": "When a variable has the same name as the field, write it once.", "hints": []}, {"type": "single", "q": "After `let u2 = User { email: e, ..u1 };` where `User` has a `username: String`, can you still use `u1.username`?", "options": ["Yes", "No: it was moved into `u2`", "Only if `u1` is `mut`", "Only inside a block"], "answer": 1, "explanation": "Struct update syntax moves the non-`Copy` fields it takes.", "hints": []}, {"type": "single", "q": "What is a tuple struct good for?", "options": ["Storing many fields with names", "Giving a distinct type to a value without naming its fields, like `struct Meters(f64)`", "Making fields public", "Avoiding moves"], "answer": 1, "explanation": "It is the newtype pattern: same data, different meaning, checked by the compiler.", "hints": []}, {"type": "truefalse", "q": "A struct field of type `&str` compiles without any extra annotation.", "answer": false, "explanation": "Reference fields need a lifetime parameter (chapter 10). Prefer owned `String` for now.", "hints": []}]}, {"type": "summary", "points": ["`struct Name { field: Type, ... }` defines a type; `Name { field: value, ... }` creates an instance.", "Read and write fields with dot notation; the whole instance must be `mut` to change any field.", "Field init shorthand: `User { email }` when a variable has the field's name.", "Struct update syntax `..other` fills the rest from another instance, moving non-`Copy` fields.", "Tuple structs (`struct Meters(f64)`) give a distinct type without field names; unit-like structs have no fields.", "Prefer owned field types like `String`; reference fields need lifetimes."]}], "terms": [{"term": "struct", "def": "A custom type that groups named fields into one value."}, {"term": "field", "def": "A named piece of data inside a struct."}, {"term": "instance", "def": "A concrete value of a struct type, with every field filled in."}, {"term": "tuple struct", "def": "A struct whose fields have no names, only positions, like struct Color(i32, i32, i32)."}, {"term": "newtype", "def": "A tuple struct wrapping a single value to give it its own type, like struct Meters(f64)."}, {"term": "unit-like struct", "def": "A struct with no fields, useful for implementing traits on a type that holds no data."}], "id": "ch05-01-define", "chapter": "ch05", "kind": "lesson"}, "ch05-02-rectangles": {"title": "From loose variables to a struct", "summary": "Refactor a small program three times, from separate variables to a tuple to a struct, and learn to print structs with Debug, {:#?} and dbg!.", "minutes": 22, "source": {"chapter": "ch05", "sections": ["TRPL 5.2 An Example Program Using Structs", "TRPL 5.2 Refactoring with Tuples", "TRPL 5.2 Refactoring with Structs", "TRPL 5.2 Adding Functionality with Derived Traits", "PR ch9 Deriving Common Traits for Struct Types"]}, "blocks": [{"type": "text", "md": "When should you reach for a struct? This lesson follows one small program, which computes the area of a rectangle, through three versions. Each version works. What changes is how clearly the code says what it means.\n"}, {"type": "stepper", "title": "Three versions of the same program", "lang": "rust", "steps": [{"title": "1. Separate variables", "md": "It works, but nothing in `area(width: u32, height: u32)` says the two numbers belong together. A caller could pass two unrelated numbers, or swap them.", "code": "fn main() {\n    let width1 = 30;\n    let height1 = 50;\n    println!(\"The area of the rectangle is {} square pixels.\", area(width1, height1));\n}\n\nfn area(width: u32, height: u32) -> u32 {\n    width * height\n}\n", "highlight": [7]}, {"title": "2. A tuple", "md": "Now there is one argument, so the values travel together. But `dimensions.0` and `dimensions.1` have no names: which one is the width? For area it does not matter; for drawing the rectangle on screen it would.", "code": "fn main() {\n    let rect1 = (30, 50);\n    println!(\"The area of the rectangle is {} square pixels.\", area(rect1));\n}\n\nfn area(dimensions: (u32, u32)) -> u32 {\n    dimensions.0 * dimensions.1\n}\n", "highlight": [6, 7]}, {"title": "3. A struct", "md": "The signature now reads as a sentence: the area of a rectangle. It borrows the rectangle (`&Rectangle`), so `main` keeps ownership, and the body says `width * height`.", "code": "struct Rectangle {\n    width: u32,\n    height: u32,\n}\n\nfn main() {\n    let rect1 = Rectangle { width: 30, height: 50 };\n    println!(\"The area of the rectangle is {} square pixels.\", area(&rect1));\n}\n\nfn area(rectangle: &Rectangle) -> u32 {\n    rectangle.width * rectangle.height\n}\n", "highlight": [1, 2, 3, 4, 11, 12]}]}, {"type": "text", "title": "Printing a struct", "md": "`println!(\"{rect1}\")` does not compile: `Rectangle` does not implement `std::fmt::Display`. Rust does not guess how your type should look to users. For debugging, though, Rust can write a printer for you. Add `#[derive(Debug)]` above the struct and use `{:?}`, or `{:#?}` for one field per line:\n"}, {"type": "code", "lang": "rust", "code": "#[derive(Debug)]\nstruct Rectangle {\n    width: u32,\n    height: u32,\n}\n\nfn main() {\n    let rect1 = Rectangle { width: 30, height: 50 };\n    println!(\"rect1 is {rect1:?}\");\n    println!(\"rect1 is {rect1:#?}\");\n}\n", "output": "rect1 is Rectangle { width: 30, height: 50 }\nrect1 is Rectangle {\n    width: 30,\n    height: 50,\n}\n", "explain": "`#[derive(Debug)]` is an **attribute** that asks the compiler to generate an implementation of the `Debug` trait. Traits are chapter 10's topic; for now, `derive` is the line you add to make a struct printable with `{:?}`."}, {"type": "text", "title": "dbg!", "md": "The `dbg!` macro prints the file, line, the expression you wrote, and its value, to **standard error**, then hands the value back. Because it returns the value, you can wrap it around part of an expression without changing what the program does. It takes ownership of what you pass, so pass a reference (`dbg!(&rect1)`) when you want to keep using the value.\n"}, {"type": "code", "lang": "rust", "code": "#[derive(Debug)]\nstruct Rectangle {\n    width: u32,\n    height: u32,\n}\n\nfn main() {\n    let scale = 2;\n    let rect1 = Rectangle {\n        width: dbg!(30 * scale),\n        height: 50,\n    };\n    dbg!(&rect1);\n}\n", "output": "[src/main.rs:10:16] 30 * scale = 60\n[src/main.rs:13:5] &rect1 = Rectangle {\n    width: 60,\n    height: 50,\n}\n", "output_label": "Standard error", "explain": "Because `dbg!` writes to stderr and `println!` to stdout, debug output does not get mixed into a program's real output when it is redirected to a file."}, {"type": "playground", "id": "ch05-play-rect", "title": "Perimeter and a square check", "lang": "rust", "md": "Add two functions next to `area`: `perimeter(&Rectangle) -> u32` and `is_square(&Rectangle) -> bool`, and print them for both rectangles in `main` as shown in the task. Keep `#[derive(Debug)]` and the first `println!`.\n", "task": "Print `Rectangle { width: 30, height: 50 }: area 1500, perimeter 160, square false`, then the same for a 20 × 20 rectangle (`area 400, perimeter 80, square true`).", "code": "#[derive(Debug)]\nstruct Rectangle {\n    width: u32,\n    height: u32,\n}\n\nfn area(r: &Rectangle) -> u32 {\n    r.width * r.height\n}\n\nfn main() {\n    let shapes = [Rectangle { width: 30, height: 50 }, Rectangle { width: 20, height: 20 }];\n    for r in &shapes {\n        println!(\"{r:?}: area {}\", area(r));\n    }\n}\n", "expected_output": "Rectangle { width: 30, height: 50 }: area 1500, perimeter 160, square false\nRectangle { width: 20, height: 20 }: area 400, perimeter 80, square true\n", "hints": ["`for r in &shapes` borrows each element, so `r` is already a `&Rectangle`: call `perimeter(r)`, not `perimeter(&r)`.", "`2 * (r.width + r.height)` and `r.width == r.height`."]}, {"type": "quiz", "id": "ch05-quiz-rect", "title": "Check yourself", "questions": [{"type": "single", "q": "Why is `fn area(rectangle: &Rectangle)` better than `fn area(width: u32, height: u32)`?", "options": ["It runs faster", "It says the values belong together and names them", "It is the only way to multiply", "It avoids heap allocation"], "answer": 1, "explanation": "The struct carries meaning: the function works on a rectangle, and its fields have names.", "hints": []}, {"type": "single", "q": "Which line makes `println!(\"{:?}\", r)` work for a struct?", "options": ["`use std::fmt;`", "`#[derive(Debug)]` above the struct", "`impl Print for Rectangle`", "`#[debug]` on each field"], "answer": 1, "explanation": "Deriving `Debug` generates the debug printer.", "hints": []}, {"type": "multi", "q": "Which are true about `dbg!`?", "options": ["It prints to standard error", "It shows the file and line", "It returns the value it was given", "It only works on numbers"], "answer": [0, 1, 2], "explanation": "It works on any `Debug` value and takes ownership unless you pass a reference.", "hints": []}, {"type": "single", "q": "What is the difference between `{:?}` and `{:#?}`?", "options": ["`{:#?}` prints in hexadecimal", "`{:#?}` pretty-prints over several lines", "`{:#?}` prints only field names", "No difference"], "answer": 1, "explanation": "The `#` asks for the indented, multi-line form.", "hints": []}]}, {"type": "summary", "points": ["Group values that belong together in a struct; names make code say what it means.", "Borrow structs (`&Rectangle`) in functions that only read them.", "`#[derive(Debug)]` enables `{:?}` and pretty `{:#?}` printing.", "`dbg!(expr)` prints file, line, expression and value to stderr, and returns the value."]}], "terms": [{"term": "attribute", "def": "Metadata in #[...] that tells the compiler something about the item below it, like #[derive(Debug)]."}, {"term": "derive", "def": "An attribute that asks the compiler to generate a standard trait implementation, such as Debug, Clone or PartialEq."}, {"term": "dbg!", "def": "A macro that prints an expression and its value with the file and line to stderr, and returns the value."}], "id": "ch05-02-rectangles", "chapter": "ch05", "kind": "lesson"}, "ch05-03-methods": {"title": "Methods and associated functions", "summary": "Attach behavior to a struct with impl blocks: methods taking &self, &mut self or self, getters, methods with more parameters, associated functions like new, and automatic referencing.", "minutes": 30, "source": {"chapter": "ch05", "sections": ["TRPL 5.3 Methods", "TRPL 5.3 Method Syntax", "TRPL 5.3 Methods with More Parameters", "TRPL 5.3 Associated Functions", "TRPL 5.3 Multiple impl Blocks", "PR ch9 Defining Methods with impl", "PR ch9 Passing Self as a Box, Rc, or Arc", "PR ch9 Type-Associated Functions", "RiA 3.2 Modeling files with struct", "RiA 3.3 Adding methods to a struct with impl", "CR Day 2 Methods"]}, "blocks": [{"type": "text", "md": "A **method** is a function that belongs to a type. You define it inside an `impl` block (short for *implementation*), and its first parameter is always `self`, the instance the method is called on. Methods keep a type's behavior next to its data, and let callers write `rect.area()` instead of `area(&rect)`.\n"}, {"type": "code", "lang": "rust", "code": "#[derive(Debug)]\nstruct Rectangle {\n    width: u32,\n    height: u32,\n}\n\nimpl Rectangle {\n    fn area(&self) -> u32 {\n        self.width * self.height\n    }\n}\n\nfn main() {\n    let rect1 = Rectangle { width: 30, height: 50 };\n    println!(\"The area of the rectangle is {} square pixels.\", rect1.area());\n}\n", "output": "The area of the rectangle is 1500 square pixels.", "explain": "Inside `impl Rectangle`, the type `Self` is an alias for `Rectangle`, and `&self` is short for `self: &Self`. The method borrows the instance, exactly as `area(rectangle: &Rectangle)` did, but now it is found through the type."}, {"type": "table", "title": "The three kinds of self", "headers": ["First parameter", "The method...", "Typical use"], "rows": [["`&self`", "borrows the instance to read it", "getters, calculations: `area`, `len`, `is_empty`"], ["`&mut self`", "borrows the instance to change it", "setters, updates: `push`, `resize`, `clear`"], ["`self`", "takes ownership; the caller cannot use the instance afterwards", "turning a value into something else: `into_string`, `finish`"]]}, {"type": "callout", "kind": "note", "title": "Where is the -> operator?", "md": "C and C++ use `.` on a value and `->` on a pointer. Rust has only `.`: it adds `&`, `&mut` or `*` automatically so the receiver matches the method's `self`. `rect1.area()` and `(&rect1).area()` are the same call. This **automatic referencing** is why methods are so convenient: the signature says whether the method reads, changes or consumes, and the call site stays tidy."}, {"type": "text", "title": "Methods with more parameters, and getters", "md": "A method can take more parameters after `self`. A method can also share a field's name: `rect.width()` with parentheses is the method, `rect.width` is the field. Such methods are **getters**, often used to make a field read-only from outside the module (privacy is covered in chapter 7).\n"}, {"type": "code", "lang": "rust", "code": "struct Rectangle {\n    width: u32,\n    height: u32,\n}\n\nimpl Rectangle {\n    fn width(&self) -> bool {\n        self.width > 0\n    }\n\n    fn can_hold(&self, other: &Rectangle) -> bool {\n        self.width > other.width && self.height > other.height\n    }\n}\n\nfn main() {\n    let rect1 = Rectangle { width: 30, height: 50 };\n    let rect2 = Rectangle { width: 10, height: 40 };\n    let rect3 = Rectangle { width: 60, height: 45 };\n    println!(\"rect1 has a nonzero width: {}\", rect1.width());\n    println!(\"Can rect1 hold rect2? {}\", rect1.can_hold(&rect2));\n    println!(\"Can rect1 hold rect3? {}\", rect1.can_hold(&rect3));\n}\n", "output": "rect1 has a nonzero width: true\nCan rect1 hold rect2? true\nCan rect1 hold rect3? false\n"}, {"type": "text", "title": "Associated functions", "md": "Functions in an `impl` block that do **not** take `self` are **associated functions**. They belong to the type but do not need an instance, and you call them with `::`, as you did with `String::from`. The most common one is a constructor, by convention named `new`. Rust has no special constructor syntax; `new` is just a convention.\n"}, {"type": "code", "lang": "rust", "code": "#[derive(Debug)]\nstruct Rectangle {\n    width: u32,\n    height: u32,\n}\n\nimpl Rectangle {\n    fn new(width: u32, height: u32) -> Self {\n        Self { width, height }\n    }\n\n    fn square(size: u32) -> Self {\n        Self { width: size, height: size }\n    }\n}\n\nfn main() {\n    let r = Rectangle::new(3, 4);\n    let sq = Rectangle::square(3);\n    println!(\"{r:?} {sq:?}\");\n}\n", "output": "Rectangle { width: 3, height: 4 } Rectangle { width: 3, height: 3 }", "explain": "`Self` inside the `impl` means `Rectangle`, so renaming the type later only touches one line. A type may have several `impl` blocks; that is useful with generics and traits later, though one block is usual for a simple struct."}, {"type": "text", "title": "A worked example: files, from Rust in Action", "md": "*Rust in Action* models a file as a struct with a name and its contents, then adds methods. `Vec<u8>` is a growable list of bytes (chapter 8 covers `Vec`); here it is enough to know that `Vec::new()` makes an empty one, `push` and `extend` add bytes, and `len` counts them.\n"}, {"type": "code", "lang": "rust", "code": "#[derive(Debug)]\nstruct File {\n    name: String,\n    data: Vec<u8>,\n}\n\nimpl File {\n    fn new(name: &str) -> File {\n        File { name: String::from(name), data: Vec::new() }\n    }\n\n    fn len(&self) -> usize {\n        self.data.len()\n    }\n\n    fn write(&mut self, bytes: &[u8]) {\n        self.data.extend_from_slice(bytes);\n    }\n\n    fn into_name(self) -> String {\n        self.name\n    }\n}\n\nfn main() {\n    let mut f = File::new(\"f1.txt\");\n    f.write(b\"hello\");\n    println!(\"{} is {} bytes\", f.name, f.len());\n    let name = f.into_name();     // f is consumed here\n    println!(\"only the name is left: {name}\");\n}\n", "output": "f1.txt is 5 bytes\nonly the name is left: f1.txt\n", "explain": "`b\"hello\"` is a **byte string**: a `&[u8; 5]`, which coerces to the `&[u8]` slice that `write` takes. `into_name(self)` consumes the file and returns its name; by convention, methods named `into_...` take `self`. Using `f` after that line is a compile error."}, {"type": "playground", "id": "ch05-play-counter", "title": "A counter with &mut self", "lang": "rust", "md": "Complete the `impl` block: `new` starts the count at 0, `increment` adds one, `add` adds `n`, and `get` returns the current value. Then `main` prints `3`. Pay attention to which methods need `&mut self`.\n", "task": "Make the program print `count: 3`.", "code": "struct Counter {\n    count: u32,\n}\n\nimpl Counter {\n    // fn new() -> Self\n    // fn increment(...)\n    // fn add(..., n: u32)\n    // fn get(...) -> u32\n}\n\nfn main() {\n    let mut c = Counter::new();\n    c.increment();\n    c.add(2);\n    println!(\"count: {}\", c.get());\n}\n", "expected_output": "count: 3", "hints": ["`new` takes no `self`: `fn new() -> Self { Self { count: 0 } }`.", "`increment` and `add` change the count, so they take `&mut self`; `get` only reads, so `&self`."]}, {"type": "exercise", "id": "ch05-ex-methods", "exercise_dir": "ch05-bank-account", "title": "A bank account with methods", "difficulty": "medium", "goal": "Design a type whose methods protect its rules: the balance never goes negative and every change is recorded.", "behavior": "`pub struct Account { owner: String, balance: u64, history: Vec<i64> }` (fields private) with:\n- `pub fn new(owner: &str) -> Self`: balance 0, empty history.\n- `pub fn owner(&self) -> &str` and `pub fn balance(&self) -> u64`: getters.\n- `pub fn deposit(&mut self, amount: u64)`: adds to the balance and records `+amount` in the history.\n- `pub fn withdraw(&mut self, amount: u64) -> bool`: if the balance is enough, subtracts it, records `-amount`, and returns `true`; otherwise changes nothing and returns `false`.\n- `pub fn history(&self) -> &[i64]`: the recorded changes in order.\n- `pub fn close(self) -> u64`: consumes the account and returns the final balance.\n", "examples": [{"input": "new(\"Ada\"), deposit(100), withdraw(30), withdraw(500)", "output": "balance 70, history [100, -30], last withdraw returned false"}], "hints": ["`history.push(amount as i64)` and `history.push(-(amount as i64))`.", "`withdraw`: `if amount > self.balance { return false; }` first.", "`history(&self) -> &[i64]` can return `&self.history`: a `&Vec<i64>` coerces to `&[i64]`."], "solution_explain": "Because the fields are private and the only way to change the balance is through `deposit` and `withdraw`, the rule \"never negative\" is enforced in one place. Using `u64` for the balance makes a negative balance impossible to even represent; `withdraw` checks first so the subtraction cannot underflow.", "mode": "tests", "dir": "ch05-bank-account", "command_display": "cargo test --offline", "language": "rust", "files": {"starter": [{"path": "src/lib.rs", "content": "/// A bank account. The balance can never go below zero.\npub struct Account {\n    owner: String,\n    balance: u64,\n    history: Vec<i64>,\n}\n\nimpl Account {\n    /// A new, empty account.\n    pub fn new(owner: &str) -> Self {\n        todo!()\n    }\n\n    pub fn owner(&self) -> &str {\n        todo!()\n    }\n\n    pub fn balance(&self) -> u64 {\n        todo!()\n    }\n\n    /// Adds money and records +amount.\n    pub fn deposit(&mut self, amount: u64) {\n        todo!()\n    }\n\n    /// Takes money out if there is enough; records -amount. Returns whether it happened.\n    pub fn withdraw(&mut self, amount: u64) -> bool {\n        todo!()\n    }\n\n    /// Every change, in order.\n    pub fn history(&self) -> &[i64] {\n        todo!()\n    }\n\n    /// Closes the account and returns what was left.\n    pub fn close(self) -> u64 {\n        todo!()\n    }\n}\n\n#[cfg(test)]\nmod tests;\n"}, {"path": "Cargo.toml", "content": "[package]\nname = \"ch05_bank_account\"\nversion = \"0.1.0\"\nedition = \"2024\"\n\n[dependencies]\n"}], "tests": [{"path": "src/tests.rs", "content": "use super::*;\n\n#[test]\nfn new_account_is_empty() {\n    let a = Account::new(\"Ada\");\n    assert_eq!(a.owner(), \"Ada\");\n    assert_eq!(a.balance(), 0);\n    assert!(a.history().is_empty(), \"no history yet\");\n}\n\n#[test]\nfn deposits_and_withdrawals() {\n    let mut a = Account::new(\"Ada\");\n    a.deposit(100);\n    assert!(a.withdraw(30), \"withdrawing 30 of 100 works\");\n    assert_eq!(a.balance(), 70);\n    assert_eq!(a.history(), &[100, -30]);\n}\n\n#[test]\nfn cannot_overdraw() {\n    let mut a = Account::new(\"Ada\");\n    a.deposit(50);\n    assert!(!a.withdraw(51), \"withdrawing more than the balance fails\");\n    assert_eq!(a.balance(), 50, \"a failed withdrawal changes nothing\");\n    assert_eq!(a.history(), &[50], \"a failed withdrawal is not recorded\");\n    assert!(a.withdraw(50), \"withdrawing exactly the balance works\");\n    assert_eq!(a.balance(), 0);\n}\n\n#[test]\nfn closing_returns_the_balance() {\n    let mut a = Account::new(\"Ada\");\n    a.deposit(7);\n    assert_eq!(a.close(), 7);\n}\n"}], "solution": [{"path": "src/lib.rs", "content": "/// A bank account. The balance can never go below zero.\npub struct Account {\n    owner: String,\n    balance: u64,\n    history: Vec<i64>,\n}\n\nimpl Account {\n    /// A new, empty account.\n    pub fn new(owner: &str) -> Self {\n        Self { owner: String::from(owner), balance: 0, history: Vec::new() }\n    }\n\n    pub fn owner(&self) -> &str {\n        &self.owner\n    }\n\n    pub fn balance(&self) -> u64 {\n        self.balance\n    }\n\n    /// Adds money and records +amount.\n    pub fn deposit(&mut self, amount: u64) {\n        self.balance += amount;\n        self.history.push(amount as i64);\n    }\n\n    /// Takes money out if there is enough; records -amount. Returns whether it happened.\n    pub fn withdraw(&mut self, amount: u64) -> bool {\n        if amount > self.balance {\n            return false;\n        }\n        self.balance -= amount;\n        self.history.push(-(amount as i64));\n        true\n    }\n\n    /// Every change, in order.\n    pub fn history(&self) -> &[i64] {\n        &self.history\n    }\n\n    /// Closes the account and returns what was left.\n    pub fn close(self) -> u64 {\n        self.balance\n    }\n}\n\n#[cfg(test)]\nmod tests;\n"}]}}, {"type": "quiz", "id": "ch05-quiz-methods", "title": "Check yourself", "questions": [{"type": "single", "q": "Which first parameter should a method have if it changes a field?", "options": ["`self`", "`&self`", "`&mut self`", "None: methods cannot change fields"], "answer": 2, "explanation": "`&mut self` borrows the instance mutably.", "hints": []}, {"type": "single", "q": "How do you call an associated function `new` on `Rectangle`?", "options": ["`Rectangle.new()`", "`Rectangle::new()`", "`new Rectangle()`", "`rect.new()`"], "answer": 1, "explanation": "Associated functions are called with `Type::function`.", "hints": []}, {"type": "single", "q": "After `let n = f.into_name();` where `into_name` takes `self`, what happens to `f`?", "options": ["Nothing", "It is consumed: using it afterwards is a compile error", "It becomes empty", "It is cloned"], "answer": 1, "explanation": "A `self` method takes ownership of the instance.", "hints": []}, {"type": "truefalse", "q": "You must write `(&mut v).push(1)` to call a `&mut self` method on a `let mut v`.", "answer": false, "explanation": "Automatic referencing adds the `&mut` for you: `v.push(1)`.", "hints": []}, {"type": "single", "q": "Inside `impl Rectangle { ... }`, what is `Self`?", "options": ["The current instance", "An alias for the type `Rectangle`", "A keyword for constructors", "The module"], "answer": 1, "explanation": "`Self` is the type; `self` (lowercase) is the instance.", "hints": []}, {"type": "multi", "q": "Which are associated functions rather than methods?", "options": ["`fn new(w: u32) -> Self`", "`fn area(&self) -> u32`", "`fn square(size: u32) -> Self`", "`fn close(self) -> u64`"], "answer": [0, 2], "explanation": "Associated functions have no `self` parameter.", "hints": []}]}, {"type": "summary", "points": ["Methods live in `impl Type { ... }` blocks and take `self`, `&self` or `&mut self` first.", "Choose the weakest `self` that works: read with `&self`, change with `&mut self`, consume with `self`.", "Automatic referencing makes `value.method()` work for every kind of `self`.", "Associated functions have no `self` and are called with `Type::name`; `new` is the usual constructor.", "`Self` is the type being implemented; private fields plus methods let a type protect its own rules."]}], "terms": [{"term": "method", "def": "A function defined in an impl block whose first parameter is self, &self or &mut self, called with value.method()."}, {"term": "impl block", "def": "A block that defines methods and associated functions for a type."}, {"term": "associated function", "def": "A function in an impl block without a self parameter, called with Type::name, like String::from."}, {"term": "Self", "def": "Inside an impl block, an alias for the type being implemented."}, {"term": "getter", "def": "A method that returns a field's value, often so the field itself can stay private."}], "id": "ch05-03-methods", "chapter": "ch05", "kind": "lesson"}, "ch05-99-test": {"title": "Chapter test: Structs", "kind": "test", "summary": "Ten questions on defining structs, update syntax, Debug printing, methods and associated functions. You need 70% to pass; you can retry and your best score is kept.", "blocks": [{"type": "quiz", "id": "ch05-test", "pass_score": 0.7, "questions": [{"type": "single", "q": "Which defines a struct correctly?", "options": ["`struct Point { x: f64; y: f64 }`", "`struct Point { x: f64, y: f64 }`", "`struct Point(x: f64, y: f64)`", "`struct point { f64 x, f64 y }`"], "answer": 1, "explanation": "Fields are `name: Type`, separated by commas.", "hints": []}, {"type": "single", "q": "What does this print?", "code": "struct P { x: i32, y: i32 }\nfn main() {\n    let a = P { x: 1, y: 2 };\n    let b = P { y: 9, ..a };\n    println!(\"{} {} {} {}\", a.x, a.y, b.x, b.y);\n}\n", "lang": "rust", "options": ["1 2 1 9", "1 9 1 9", "It does not compile: a was moved", "9 2 1 9"], "answer": 0, "explanation": "The fields are `i32`, which is `Copy`, so `a` stays usable; `b` takes `x` from `a` and its own `y`.", "hints": []}, {"type": "single", "q": "Why might you write `struct Celsius(f64);` instead of using `f64`?", "options": ["It is faster", "So the compiler stops you passing a Fahrenheit value where Celsius is expected", "`f64` cannot be printed", "To allocate on the heap"], "answer": 1, "explanation": "A newtype gives a value its own type, checked by the compiler, at no run-time cost.", "hints": []}, {"type": "fill", "q": "To print a struct with `{:?}`, put `#[derive(_____)]` above it.", "answer": ["Debug"], "explanation": "Deriving `Debug` generates the formatter.", "hints": []}, {"type": "single", "q": "Where does `dbg!` print?", "options": ["Standard output", "Standard error", "A log file", "Nowhere in release builds"], "answer": 1, "explanation": "To stderr, so it does not mix with the program's normal output.", "hints": []}, {"type": "single", "q": "Which method signature fits a method that returns the length of a list without changing it?", "options": ["`fn len(self) -> usize`", "`fn len(&self) -> usize`", "`fn len(&mut self) -> usize`", "`fn len() -> usize`"], "answer": 1, "explanation": "Reading needs only `&self`.", "hints": []}, {"type": "single", "q": "Does this compile?", "code": "struct S { n: u32 }\nimpl S {\n    fn bump(&mut self) { self.n += 1; }\n}\nfn main() {\n    let s = S { n: 0 };\n    s.bump();\n}\n", "lang": "rust", "options": ["Yes", "No: `s` must be declared `let mut`", "No: methods cannot change fields", "No: `bump` must return a value"], "answer": 1, "explanation": "Calling a `&mut self` method needs a mutable borrow, so the variable must be `mut`.", "hints": []}, {"type": "multi", "q": "Which are true about associated functions?", "options": ["They have no `self` parameter", "They are called with `Type::name()`", "`String::from` is one", "They can only be named `new`"], "answer": [0, 1, 2], "explanation": "`new` is only a convention; any name works.", "hints": []}, {"type": "truefalse", "q": "A struct can have more than one `impl` block.", "answer": true, "explanation": "Several blocks are allowed and are merged; it matters most with generics and traits.", "hints": []}, {"type": "single", "q": "A method `fn finish(self) -> Report` is called as `let r = builder.finish();`. Which is true afterwards?", "options": ["`builder` can still be used", "`builder` was moved into `finish` and cannot be used", "`builder` is reset", "`builder` becomes a reference to `r`"], "answer": 1, "explanation": "A `self` method consumes its receiver.", "hints": []}], "mode": "test"}], "id": "ch05-99-test", "chapter": "ch05", "minutes": 10}}, "glossary": [{"term": "compiler", "def": "A program that checks your source code and translates it into a program the computer can run. For Rust it is called `rustc`.", "lesson": "ch01-01-why-rust"}, {"term": "undefined behavior", "def": "What happens when a C or C++ program breaks a language rule, such as writing past the end of an array: the program is allowed to do anything at all.", "lesson": "ch01-01-why-rust"}, {"term": "garbage collector", "def": "A helper that runs alongside a program and frees memory that is no longer used. Rust does not have one.", "lesson": "ch01-01-why-rust"}, {"term": "panic", "def": "Rust stopping a program on purpose with an error message, for example when you read past the end of a vector.", "lesson": "ch01-01-why-rust"}, {"term": "zero-cost abstraction", "def": "A language feature that adds no run-time cost compared with writing the same thing by hand.", "lesson": "ch01-01-why-rust"}, {"term": "rustup", "def": "The installer and version manager for Rust: `rustup update` upgrades, `rustup doc` opens offline docs.", "lesson": "ch01-02-install-hello"}, {"term": "function", "def": "A named block of instructions, started with `fn`. It can take inputs (parameters) and give back a value.", "lesson": "ch01-02-install-hello"}, {"term": "macro", "def": "Code that writes more code. Called with a `!`, like `println!`. Macros can do things ordinary functions cannot, such as take any number of arguments.", "lesson": "ch01-02-install-hello"}, {"term": "string", "def": "A piece of text. A string literal is text written in double quotes in your code, like `\"Hello\"`.", "lesson": "ch01-02-install-hello"}, {"term": "executable", "def": "A file produced by the compiler that the operating system can run directly.", "lesson": "ch01-02-install-hello"}, {"term": "linker", "def": "A tool that joins compiled pieces into one executable. Installed with a C compiler or Visual Studio's build tools.", "lesson": "ch01-02-install-hello"}, {"term": "UTF-8", "def": "The text encoding Rust strings use. It can store characters from every writing system.", "lesson": "ch01-02-install-hello"}, {"term": "Cargo", "def": "Rust's build system and package manager. It builds code, downloads dependencies and runs tests.", "lesson": "ch01-03-cargo"}, {"term": "crate", "def": "A package of Rust code. Your project is a crate; libraries you use are crates too.", "lesson": "ch01-03-cargo"}, {"term": "dependency", "def": "A crate that your project uses, listed under `[dependencies]` in `Cargo.toml`.", "lesson": "ch01-03-cargo"}, {"term": "Cargo.toml", "def": "The project settings file written in TOML: package name, version, edition and dependencies.", "lesson": "ch01-03-cargo"}, {"term": "Cargo.lock", "def": "A file that records the exact versions of all dependencies so builds can be repeated. Managed by Cargo.", "lesson": "ch01-03-cargo"}, {"term": "edition", "def": "A set of language conventions (2015, 2018, 2021, 2024) a crate opts into in `Cargo.toml`.", "lesson": "ch01-03-cargo"}, {"term": "release profile", "def": "The build settings used by `cargo build --release`: slower to compile, faster to run.", "lesson": "ch01-03-cargo"}, {"term": "variable", "def": "A name bound to a value with `let`. Immutable by default; `let mut` makes it changeable.", "lesson": "ch02-01-setup-input"}, {"term": "associated function", "def": "A function that belongs to a type and is called with `::`, like `String::new()`.", "lesson": "ch02-01-setup-input"}, {"term": "Result", "def": "A value that is either `Ok(value)` for success or `Err(error)` for failure. Rust uses it for anything that can fail.", "lesson": "ch02-01-setup-input"}, {"term": "reference", "def": "A way to let code use a value without taking it over, written `&value` (read-only) or `&mut value` (may change it).", "lesson": "ch02-01-setup-input"}, {"term": "prelude", "def": "The short list of names Rust brings into every program automatically, such as `String` and `println!`.", "lesson": "ch02-01-setup-input"}, {"term": "crates.io", "def": "The public registry where Rust crates are published and downloaded from.", "lesson": "ch02-02-random-compare"}, {"term": "Semantic Versioning", "def": "Version numbers as MAJOR.MINOR.PATCH with rules about compatibility. Cargo uses it to decide which versions are safe.", "lesson": "ch02-02-random-compare"}, {"term": "match", "def": "An expression that compares a value against patterns (arms) and runs the code of the first one that fits. It must cover every possible value.", "lesson": "ch02-02-random-compare"}, {"term": "enum", "def": "A type whose value is one of a fixed list of variants, like `Ordering::Less`, `Ordering::Greater`, `Ordering::Equal`.", "lesson": "ch02-02-random-compare"}, {"term": "type annotation", "def": "Writing a type explicitly, as in `let n: u32 = ...`, when Rust cannot or should not infer it.", "lesson": "ch02-02-random-compare"}, {"term": "shadowing", "def": "Declaring a new variable with the same name as an earlier one, which hides the earlier one from then on.", "lesson": "ch02-02-random-compare"}, {"term": "loop", "def": "Repeats its block forever, until `break` (or `return`) leaves it.", "lesson": "ch02-03-loop-quit"}, {"term": "break", "def": "Ends the innermost loop immediately.", "lesson": "ch02-03-loop-quit"}, {"term": "continue", "def": "Skips the rest of the current round of a loop and starts the next one.", "lesson": "ch02-03-loop-quit"}, {"term": "unit test", "def": "A small function marked `#[test]` that calls your code and checks the result; `cargo test` runs them all.", "lesson": "ch02-03-loop-quit"}, {"term": "Option", "def": "A value that is either `Some(value)` or `None`: Rust's way of saying 'there may be no value' without null.", "lesson": "ch02-03-loop-quit"}, {"term": "Vec", "def": "A growable list of values of one type, like `Vec<String>`.", "lesson": "ch02-03-loop-quit"}, {"term": "immutable", "def": "Cannot be changed after it is given a value. Rust variables are immutable unless declared with `mut`.", "lesson": "ch03-01-variables"}, {"term": "constant", "def": "A named value fixed at compile time, declared with `const` and an explicit type.", "lesson": "ch03-01-variables"}, {"term": "scope", "def": "The part of the program, usually a `{ }` block, in which a name is valid.", "lesson": "ch03-01-variables"}, {"term": "type inference", "def": "The compiler working out a variable's type from how it is used, so you need not write it.", "lesson": "ch03-01-variables"}, {"term": "scalar type", "def": "A type holding a single value: an integer, a float, a bool or a char.", "lesson": "ch03-02-scalar-types"}, {"term": "integer overflow", "def": "A result outside the type's range. Debug builds panic; release builds wrap around unless you choose otherwise.", "lesson": "ch03-02-scalar-types"}, {"term": "usize", "def": "The unsigned integer type as wide as a memory address; used for sizes and indexes.", "lesson": "ch03-02-scalar-types"}, {"term": "char", "def": "One Unicode scalar value, 4 bytes, written in single quotes like 'a'.", "lesson": "ch03-02-scalar-types"}, {"term": "tuple", "def": "A fixed-size group of values that may have different types, like (\"Ada\", 36).", "lesson": "ch03-03-compound-types"}, {"term": "destructuring", "def": "Splitting a compound value into separate variables with a pattern, like let (a, b) = pair;", "lesson": "ch03-03-compound-types"}, {"term": "unit", "def": "The empty tuple (), the value of expressions and functions that produce nothing useful.", "lesson": "ch03-03-compound-types"}, {"term": "array", "def": "A fixed-length sequence of values of one type, written [T; N].", "lesson": "ch03-03-compound-types"}, {"term": "parameter", "def": "A variable in a function's signature that receives a value when the function is called.", "lesson": "ch03-04-functions"}, {"term": "argument", "def": "The value passed for a parameter when calling a function.", "lesson": "ch03-04-functions"}, {"term": "statement", "def": "An instruction that performs an action and produces no value, like let x = 5;", "lesson": "ch03-04-functions"}, {"term": "expression", "def": "Code that evaluates to a value, like 5 + 6, a function call, a block or an if.", "lesson": "ch03-04-functions"}, {"term": "doc comment", "def": "A comment starting with /// that documents the item below it and is turned into documentation by cargo doc.", "lesson": "ch03-04-functions"}, {"term": "loop label", "def": "A name like 'outer: on a loop, so break 'outer; or continue 'outer; can target it from an inner loop.", "lesson": "ch03-05-control-flow"}, {"term": "range", "def": "A sequence of numbers written a..b (end excluded) or a..=b (end included).", "lesson": "ch03-05-control-flow"}, {"term": "break value", "def": "break followed by an expression: ends a loop and makes the loop expression produce that value.", "lesson": "ch03-05-control-flow"}, {"term": "ownership", "def": "Rust's system for memory management: each value has exactly one owner, and it is freed when the owner goes out of scope.", "lesson": "ch04-01-ownership"}, {"term": "move", "def": "Transferring ownership of a value to another variable or function; the original can no longer be used.", "lesson": "ch04-01-ownership"}, {"term": "drop", "def": "Freeing a value's resources when its owner goes out of scope; Rust inserts the call automatically.", "lesson": "ch04-01-ownership"}, {"term": "Copy", "def": "A trait for types that are duplicated by simple bit copying (numbers, bool, char); assigning them copies instead of moving.", "lesson": "ch04-01-ownership"}, {"term": "clone", "def": "An explicit deep copy of a value, including its heap data.", "lesson": "ch04-01-ownership"}, {"term": "heap", "def": "Memory for data whose size is not known at compile time, allocated on request and reached through a pointer.", "lesson": "ch04-01-ownership"}, {"term": "stack", "def": "Memory for fixed-size values, managed last in, first out; very fast.", "lesson": "ch04-01-ownership"}, {"term": "borrowing", "def": "Creating a reference to a value owned by someone else.", "lesson": "ch04-02-references"}, {"term": "mutable reference", "def": "A reference (&mut T) that allows changing the value; only one can exist at a time, and no shared references alongside it.", "lesson": "ch04-02-references"}, {"term": "data race", "def": "Two accesses to the same data at the same time, at least one a write, with nothing ordering them. Rust rejects these at compile time.", "lesson": "ch04-02-references"}, {"term": "dangling reference", "def": "A reference to memory that has been freed. Impossible in safe Rust.", "lesson": "ch04-02-references"}, {"term": "dereference", "def": "Following a reference to the value it points to, with the * operator.", "lesson": "ch04-02-references"}, {"term": "borrow checker", "def": "The part of the compiler that checks every reference against the ownership and borrowing rules.", "lesson": "ch04-02-references"}, {"term": "slice", "def": "A reference to a contiguous sequence of elements in a collection: a pointer and a length.", "lesson": "ch04-03-slices"}, {"term": "&str", "def": "A string slice: borrowed UTF-8 text. String literals have this type.", "lesson": "ch04-03-slices"}, {"term": "deref coercion", "def": "Automatic conversion of a reference to another reference type, such as &String to &str.", "lesson": "ch04-03-slices"}, {"term": "struct", "def": "A custom type that groups named fields into one value.", "lesson": "ch05-01-define"}, {"term": "field", "def": "A named piece of data inside a struct.", "lesson": "ch05-01-define"}, {"term": "instance", "def": "A concrete value of a struct type, with every field filled in.", "lesson": "ch05-01-define"}, {"term": "tuple struct", "def": "A struct whose fields have no names, only positions, like struct Color(i32, i32, i32).", "lesson": "ch05-01-define"}, {"term": "newtype", "def": "A tuple struct wrapping a single value to give it its own type, like struct Meters(f64).", "lesson": "ch05-01-define"}, {"term": "unit-like struct", "def": "A struct with no fields, useful for implementing traits on a type that holds no data.", "lesson": "ch05-01-define"}, {"term": "attribute", "def": "Metadata in #[...] that tells the compiler something about the item below it, like #[derive(Debug)].", "lesson": "ch05-02-rectangles"}, {"term": "derive", "def": "An attribute that asks the compiler to generate a standard trait implementation, such as Debug, Clone or PartialEq.", "lesson": "ch05-02-rectangles"}, {"term": "dbg!", "def": "A macro that prints an expression and its value with the file and line to stderr, and returns the value.", "lesson": "ch05-02-rectangles"}, {"term": "method", "def": "A function defined in an impl block whose first parameter is self, &self or &mut self, called with value.method().", "lesson": "ch05-03-methods"}, {"term": "impl block", "def": "A block that defines methods and associated functions for a type.", "lesson": "ch05-03-methods"}, {"term": "Self", "def": "Inside an impl block, an alias for the type being implemented.", "lesson": "ch05-03-methods"}, {"term": "getter", "def": "A method that returns a field's value, often so the field itself can stay private.", "lesson": "ch05-03-methods"}]};
